/* miniapp/styles/tokens.css */
:root {
  color-scheme: dark;
  --bg: #080410;
  --bg-2: #120826;
  --card: rgba(26, 14, 50, 0.72);
  --card-border: rgba(120, 74, 255, 0.35);
  --text: #f5f1ff;
  --muted: rgba(214, 202, 255, 0.65);
  --accent: #7a3cff;
  --accent-2: #a067ff;
  --glow: rgba(144, 88, 255, 0.6);
  --bottom-nav-height: 108px;
  --tg-safe-top-offset: calc(max(var(--tg-content-safe-top, 0px), env(safe-area-inset-top)) + var(--tg-overlay-offset-top, 0px));
  --tg-safe-bottom-offset: max(var(--tg-content-safe-bottom, 0px), env(safe-area-inset-bottom));
  --tg-page-top-gap: 10px;
  --app-brand-top-height: 30px;
  --app-brand-top-width: 220px;
  --app-brand-top-gap: 4px;
  --app-brand-top-offset: calc(var(--tg-safe-top-offset) + 1px);
  --deal-chat-viewport-height: calc(
    100dvh
    - (var(--tg-safe-top-offset) + 10px)
    - (24px + var(--tg-safe-bottom-offset))
  );
}

/* miniapp/styles/base.css */
.page-admin {
  gap: 16px;
}

.admin-card {
  display: grid;
  gap: 12px;
}

.admin-tabs {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 8px;
}

.admin-section {
  display: none;
  gap: 10px;
}

.admin-section.active {
  display: grid;
}

.admin-game-section {
  gap: 12px;
  min-width: 0;
}

.admin-game-section .admin-accordion {
  min-width: 0;
  overflow: hidden;
}

.admin-subtitle {
  font-size: 12px;
  font-weight: 700;
  color: #cbb6ff;
  opacity: 0.92;
  margin-top: 4px;
}

.admin-accordion {
  border: 1px solid rgba(124, 92, 255, 0.26);
  background: rgba(25, 14, 48, 0.44);
  border-radius: 14px;
  padding: 10px 12px;
}

.admin-accordion + .admin-accordion {
  margin-top: 6px;
}

.admin-accordion > summary {
  list-style: none;
  cursor: pointer;
  font-size: 13px;
  font-weight: 700;
  color: #efe7ff;
  display: flex;
  align-items: center;
  justify-content: space-between;
  user-select: none;
}

.admin-accordion > summary::-webkit-details-marker {
  display: none;
}

.admin-accordion > summary::after {
  content: "▾";
  color: #9b7cff;
  transition: transform 0.2s ease;
}

.admin-accordion[open] > summary::after {
  transform: rotate(0deg);
}

.admin-accordion:not([open]) > summary::after {
  transform: rotate(-90deg);
}

.admin-accordion .stats-grid,
.admin-accordion #adminSystemTopRewards,
.admin-accordion #adminSystemCaseActions {
  margin-top: 10px;
}

.admin-tabs .pill {
  font-size: 11px;
}

.admin-row {
  display: grid;
  gap: 4px;
}

.notice-card {
  border-radius: 14px;
  padding: 10px 12px;
  background: rgba(124, 92, 255, 0.12);
  border: 1px solid rgba(124, 92, 255, 0.35);
  margin-top: 10px;
}

.notice-title {
  font-size: 12px;
  font-weight: 600;
  margin-bottom: 4px;
}

.notice-text {
  font-size: 12px;
  color: var(--muted);
}

.notice-actions {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 8px;
  margin-top: 10px;
}

.toast-stack {
  position: fixed;
  left: 50%;
  bottom: calc(var(--bottom-nav-height, 108px) + 18px + env(safe-area-inset-bottom));
  transform: translateX(-50%);
  display: grid;
  gap: 8px;
  z-index: 140;
  width: min(320px, 92vw);
  pointer-events: none;
}

.toast {
  background: rgba(18, 12, 32, 0.95);
  border: 1px solid rgba(124, 92, 255, 0.35);
  border-radius: 14px;
  padding: 10px 12px;
  color: #fff;
  font-size: 12px;
  box-shadow: 0 12px 24px rgba(10, 4, 26, 0.35);
  opacity: 0;
  transform: translateY(10px);
  transition: opacity 180ms ease, transform 180ms ease;
  white-space: pre-line;
}

.toast.show {
  opacity: 1;
  transform: translateY(0);
}

.toast-success {
  border-color: rgba(110, 245, 163, 0.4);
}

.toast-danger {
  border-color: rgba(255, 143, 143, 0.45);
}

.admin-row strong {
  font-size: 13px;
}

.admin-complaint-card {
  cursor: pointer;
  position: relative;
  z-index: 1;
}

.admin-complaint-card.menu-open {
  z-index: 12;
}

.admin-complaints-toolbar {
  align-items: center;
  gap: 8px;
  margin-top: 8px;
  margin-bottom: 8px;
}

.admin-complaints-toolbar .pill-group {
  flex: 1;
}

.admin-complaints-toolbar .pill {
  white-space: nowrap;
}

.admin-complaint-actions {
  position: relative;
}

.admin-complaint-menu-toggle {
  min-width: 36px;
  width: 36px;
  height: 36px;
  font-size: 20px;
  line-height: 1;
}

.admin-complaint-card-menu {
  position: absolute;
  top: calc(100% + 6px);
  right: 0;
  z-index: 8;
  min-width: 190px;
}

.admin-complaint-detail-card {
  max-width: 520px;
}

.admin-complaint-detail-block {
  margin-top: 10px;
}

.admin-complaint-detail-comment {
  border: 1px solid rgba(124, 92, 255, 0.28);
  border-radius: 12px;
  padding: 10px 12px;
  font-size: 13px;
  color: #f3ecff;
  background: rgba(18, 10, 36, 0.52);
  white-space: pre-wrap;
}

.admin-complaint-detail-images {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(84px, 1fr));
  gap: 8px;
}

.admin-complaint-image {
  border: 1px solid rgba(124, 92, 255, 0.28);
  border-radius: 10px;
  padding: 0;
  overflow: hidden;
  background: rgba(18, 10, 36, 0.52);
  cursor: pointer;
  aspect-ratio: 5 / 4;
}

.admin-complaint-image img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}

.admin-complaint-detail-history {
  display: grid;
  gap: 8px;
  max-height: 220px;
  overflow-y: auto;
  padding-right: 2px;
}

.admin-complaint-action {
  border: 1px solid rgba(124, 92, 255, 0.24);
  border-radius: 12px;
  padding: 10px 12px;
  background: rgba(18, 10, 36, 0.45);
}

.admin-complaint-action-title {
  font-size: 12px;
  font-weight: 700;
  color: #efe3ff;
}

.admin-complaint-action-meta {
  font-size: 11px;
  color: rgba(205, 190, 238, 0.75);
  margin-top: 2px;
}

.admin-complaint-action-note {
  font-size: 12px;
  color: #ddd1f7;
  margin-top: 8px;
  white-space: pre-wrap;
}

.admin-complaint-empty {
  border: 1px dashed rgba(124, 92, 255, 0.34);
  border-radius: 12px;
  padding: 10px 12px;
  font-size: 12px;
  color: rgba(205, 190, 238, 0.82);
}

.admin-complaint-detail-actions {
  margin-top: 14px;
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 8px;
}

.card {
  background: var(--card);
  border: 1px solid var(--card-border);
  border-radius: 24px;
  padding: 20px;
  backdrop-filter: blur(18px);
  box-shadow: 0 20px 40px rgba(10, 4, 26, 0.45);
  animation: fadeUp 0.8s ease forwards;
  width: 100%;
  max-width: 100%;
  min-width: 0;
  align-self: start;
}

.identity-card {
  display: grid;
  grid-template-columns: 96px 1fr auto;
  gap: 16px;
  align-items: center;
}

.identity-card--public {
  grid-template-columns: 96px 1fr;
}

.profile-header--seller {
  grid-template-columns: 76px 1fr;
}

.profile-header--seller .identity-side {
  display: none;
}

.profile-header--seller .avatar {
  width: 56px;
  height: 56px;
  font-size: 16px;
}

.profile-header--seller .role-badge {
  margin-top: 4px;
}

.profile-header--mini {
  grid-template-columns: 72px 1fr;
  gap: 12px;
}

.profile-header--mini .identity-side {
  display: none;
}

.profile-header--mini .avatar {
  width: 54px;
  height: 54px;
  font-size: 16px;
  box-shadow: 0 0 14px rgba(122, 60, 255, 0.55);
}

.profile-header--mini .shop-preview-name {
  font-weight: 900;
  font-size: 16px;
  color: rgba(255, 255, 255, 0.94);
}

.profile-header--mini .role-badge.compact {
  margin-top: 4px;
}

.shop-tryon {
  margin-top: 14px;
  display: grid;
  gap: 10px;
  padding: 12px;
  border-radius: 22px;
  background: rgba(0, 0, 0, 0.16);
  border: 1px solid rgba(255, 255, 255, 0.08);
}

.shop-tryon-title {
  font-size: 12px;
  font-weight: 900;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  color: rgba(214, 205, 255, 0.72);
}

.shop-tryon-row {
  display: flex;
  align-items: center;
  gap: 12px;
  min-width: 0;
}

.shop-tryon-main {
  min-width: 0;
  flex: 1;
  display: grid;
  gap: 6px;
}

.shop-tryon-name-row {
  min-width: 0;
}

.shop-tryon-name {
  font-weight: 900;
  font-size: 16px;
  color: rgba(255, 255, 255, 0.94);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.shop-tryon-avatar {
  width: 44px;
  height: 44px;
  font-size: 16px;
  box-shadow: 0 0 12px rgba(122, 60, 255, 0.45);
  flex: 0 0 auto;
}

.shop-tryon-avatar--sm {
  width: 34px;
  height: 34px;
  font-size: 14px;
  box-shadow: none;
}

.shop-mini-listing-title {
  font-weight: 900;
  font-size: 15px;
  color: rgba(255, 255, 255, 0.92);
}

.shop-mini-listing-meta {
  font-size: 12px;
  color: rgba(214, 205, 255, 0.68);
}

.store-listing-preview {
  margin-top: 10px;
  display: grid;
  grid-template-columns: 1fr auto;
  gap: 12px;
  align-items: center;
  min-width: 0;
}

.store-listing-preview-text {
  min-width: 0;
  display: grid;
  gap: 4px;
}

.store-listing-title {
  font-weight: 900;
  font-size: 14px;
  color: rgba(255, 255, 255, 0.92);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.store-listing-meta {
  font-size: 12px;
  color: rgba(214, 205, 255, 0.68);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.store-listing-seller {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 8px 10px;
  border-radius: 16px;
  border: 1px solid rgba(255, 255, 255, 0.08);
  background: rgba(255, 255, 255, 0.02);
  min-width: 0;
}

.store-listing-avatar {
  width: 34px;
  height: 34px;
  font-size: 14px;
  box-shadow: none;
}

.store-listing-name-row {
  min-width: 0;
}

.store-listing-name {
  font-weight: 900;
  font-size: 14px;
  color: rgba(255, 255, 255, 0.92);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.listing-frame-target[data-listing-frame="listing_frame_violet"] {
  border-color: rgba(155, 108, 255, 0.55);
  box-shadow:
    inset 0 0 0 1px rgba(181, 144, 255, 0.3),
    inset 0 0 0 2px rgba(155, 108, 255, 0.16),
    0 14px 28px rgba(155, 108, 255, 0.12);
}

.listing-frame-target[data-listing-frame="listing_frame_ice"] {
  border-color: rgba(192, 235, 255, 0.78);
  box-shadow:
    inset 0 0 0 1px rgba(236, 250, 255, 0.46),
    inset 0 0 0 2px rgba(166, 220, 255, 0.24),
    0 14px 30px rgba(116, 189, 255, 0.18);
}

.listing-frame-target[data-listing-frame="listing_frame_cyan"] {
  border-color: rgba(73, 233, 255, 0.85);
  box-shadow:
    inset 0 0 0 1px rgba(121, 246, 255, 0.44),
    inset 0 0 0 2px rgba(31, 230, 209, 0.22),
    0 0 18px rgba(31, 230, 209, 0.2),
    0 14px 30px rgba(46, 173, 255, 0.16);
}

.listing-frame-target[data-listing-frame="listing_frame_gold"] {
  border-color: rgba(255, 206, 122, 0.8);
  box-shadow:
    inset 0 0 0 1px rgba(255, 236, 186, 0.44),
    inset 0 0 0 2px rgba(255, 186, 103, 0.24),
    0 14px 30px rgba(255, 170, 90, 0.16);
}

.avatar-stack {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 10px;
}

.identity-side {
  display: grid;
  justify-items: end;
  gap: 8px;
  align-self: center;
}

.identity-side .ghost-btn {
  width: 40px;
  height: 40px;
  padding: 0;
  display: grid;
  place-items: center;
}

.identity-side .ghost-btn svg {
  width: 18px;
  height: 18px;
}

.identity-side .notif-btn svg {
  width: 60%;
  height: 60%;
}

.avatar {
  width: 72px;
  height: 72px;
  border-radius: 50%;
  display: grid;
  place-items: center;
  background: linear-gradient(145deg, #9c62ff, #5a2fd2);
  font-weight: 600;
  font-size: 20px;
  box-shadow: 0 0 18px rgba(122, 60, 255, 0.7);
  overflow: hidden;
}

.avatar.avatar-photo {
  background-size: cover;
  background-position: center;
  background-repeat: no-repeat;
}

.avatar-photo {
  background-size: cover !important;
  background-position: center !important;
  background-repeat: no-repeat !important;
}

.identity-info .profile-name {
  font-size: 22px;
  margin-bottom: 4px;
}

.identity-info {
  display: grid;
  align-content: center;
  gap: 2px;
}

.name-row {
  display: inline-flex;
  align-items: center;
  gap: 8px;
}

.role-inline {
  margin-left: 2px;
}

.name-row .profile-name {
  margin-bottom: 0;
}

.handle {
  font-size: 13px;
  color: var(--muted);
  margin-bottom: 8px;
}

.profile-badges {
  display: inline-grid;
  gap: 6px;
  margin-top: 6px;
}

.restriction-pill {
  margin-top: 6px;
  padding: 6px 10px;
  border-radius: 999px;
  font-size: 11px;
  background: rgba(255, 120, 120, 0.14);
  border: 1px solid rgba(255, 120, 120, 0.45);
  color: #ffd1d1;
}

.role-inline {
  font-size: 11px;
  color: rgba(170, 150, 215, 0.85);
  font-weight: 500;
  letter-spacing: 0.2px;
}

.staff-shield {
  width: 22px;
  height: 22px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border-radius: 999px;
  background: rgba(122, 60, 255, 0.12);
  border: 1px solid rgba(122, 60, 255, 0.35);
  color: #f7f1ff;
}

.staff-shield svg {
  width: 14px;
  height: 14px;
}

.cosmetic-badge {
  width: 24px;
  height: 24px;
  position: relative;
  display: inline-grid;
  place-items: center;
  border-radius: 999px;
  background: radial-gradient(circle at 30% 25%, rgba(255, 255, 255, 0.14), rgba(255, 255, 255, 0.02) 48%), rgba(14, 9, 28, 0.72);
  border: 1px solid rgba(180, 160, 255, 0.42);
  color: rgba(255, 236, 205, 0.98);
  box-shadow: 0 8px 18px rgba(124, 92, 255, 0.18);
  font-size: 15px;
  line-height: 1;
  font-family: "Apple Color Emoji", "Segoe UI Emoji", "Noto Color Emoji", system-ui, sans-serif;
  overflow: visible;
  flex: 0 0 auto;
}

.cosmetic-badge .badge-glyph {
  width: 15px;
  height: 15px;
  display: grid;
  place-items: center;
  z-index: 2;
}

.cosmetic-badge .badge-glyph svg {
  width: 100%;
  height: 15px;
  display: block;
  filter: drop-shadow(0 1px 2px rgba(0, 0, 0, 0.45));
}

.cosmetic-badge::before,
.cosmetic-badge::after {
  content: "";
  position: absolute;
  pointer-events: none;
  opacity: 0;
  z-index: 1;
}

.cosmetic-badge[data-badge="icon_lightning"] {
  border-color: rgba(255, 186, 86, 0.62);
  box-shadow: 0 0 0 2px rgba(255, 186, 86, 0.12), 0 10px 24px rgba(255, 171, 64, 0.18);
}

.cosmetic-badge[data-badge="icon_lightning"]::before {
  width: 9px;
  height: 9px;
  top: -4px;
  right: -3px;
  border-radius: 50%;
  background: radial-gradient(circle, rgba(255, 238, 170, 0.95) 0%, rgba(255, 186, 86, 0.5) 45%, rgba(255, 186, 86, 0) 70%);
  opacity: 0.9;
  animation: badgeLightningSpark 2.4s ease-in-out infinite;
}

.cosmetic-badge[data-badge="icon_diamond"] {
  border-color: rgba(118, 218, 255, 0.62);
  box-shadow: 0 0 0 2px rgba(118, 218, 255, 0.11), 0 10px 24px rgba(80, 188, 255, 0.2);
}

.cosmetic-badge[data-badge="icon_diamond"]::before,
.cosmetic-badge[data-badge="icon_diamond"]::after {
  width: 6px;
  height: 6px;
  border-radius: 1px;
  transform: rotate(45deg);
  background: radial-gradient(circle, rgba(255, 255, 255, 0.95) 0%, rgba(190, 240, 255, 0.6) 55%, rgba(190, 240, 255, 0) 72%);
  opacity: 0.85;
}

.cosmetic-badge[data-badge="icon_diamond"]::before {
  top: -3px;
  left: -2px;
  animation: badgeDiamondSparkle 2.8s ease-in-out infinite;
}

.cosmetic-badge[data-badge="icon_diamond"]::after {
  right: -2px;
  bottom: -2px;
  animation: badgeDiamondSparkle 2.8s ease-in-out infinite 1.4s;
}

.cosmetic-badge[data-badge="icon_crown"] {
  border-color: rgba(255, 216, 126, 0.62);
  box-shadow: 0 0 0 2px rgba(255, 216, 126, 0.1), 0 10px 24px rgba(255, 196, 82, 0.22);
}

.cosmetic-badge[data-badge="icon_crown"]::before {
  inset: -3px;
  border-radius: 999px;
  border: 1px solid rgba(255, 216, 126, 0.42);
  opacity: 0.55;
  animation: badgeCrownAura 3.8s ease-in-out infinite;
}

.cosmetic-badge[data-badge="icon_youtube"] {
  border-color: rgba(255, 92, 92, 0.68);
  box-shadow: 0 0 0 2px rgba(255, 72, 72, 0.14), 0 10px 26px rgba(255, 54, 54, 0.26);
}

.cosmetic-badge[data-badge="icon_youtube"]::before,
.cosmetic-badge[data-badge="icon_youtube"]::after {
  border-radius: 999px;
  opacity: 0.78;
}

.cosmetic-badge[data-badge="icon_youtube"]::before {
  inset: -3px;
  border: 1px solid rgba(255, 124, 124, 0.58);
  animation: badgeYoutubePulse 2.2s ease-in-out infinite;
}

.cosmetic-badge[data-badge="icon_youtube"]::after {
  inset: -6px;
  border: 1px solid rgba(255, 86, 86, 0.34);
  animation: badgeYoutubePulse 2.2s ease-in-out infinite 1.1s;
}

.cosmetic-badge[data-badge="icon_hearts"] {
  border-color: rgba(255, 130, 170, 0.68);
  box-shadow: 0 0 0 2px rgba(255, 110, 150, 0.14), 0 10px 24px rgba(255, 72, 126, 0.22);
}

.cosmetic-badge[data-badge="icon_hearts"]::before {
  width: 9px;
  height: 9px;
  top: -4px;
  left: -3px;
  border-radius: 50%;
  background: radial-gradient(circle, rgba(255, 255, 255, 0.95) 0%, rgba(255, 171, 206, 0.62) 46%, rgba(255, 171, 206, 0) 72%);
  opacity: 0.85;
  animation: badgeHeartsShimmer 2.5s ease-in-out infinite;
}

.cosmetic-badge[data-badge="icon_hearts"] .badge-glyph svg .heart-main {
  transform-origin: 50% 64%;
  animation: badgeHeartPulse 2.2s ease-in-out infinite;
}

.cosmetic-badge[data-badge="icon_hearts"] .badge-glyph svg .heart-float {
  transform-box: fill-box;
  transform-origin: center;
}

.cosmetic-badge[data-badge="icon_hearts"] .badge-glyph svg .heart-float--left {
  animation: badgeHeartFloatLeft 3.2s ease-in-out infinite;
}

.cosmetic-badge[data-badge="icon_hearts"] .badge-glyph svg .heart-float--right {
  animation: badgeHeartFloatRight 2.9s ease-in-out infinite 0.55s;
}

.cosmetic-badge[data-badge="icon_stars"] {
  border-color: rgba(255, 216, 126, 0.62);
  box-shadow: 0 0 0 2px rgba(255, 214, 118, 0.12), 0 10px 24px rgba(255, 196, 90, 0.2);
}

.cosmetic-badge[data-badge="icon_stars"]::before,
.cosmetic-badge[data-badge="icon_stars"]::after {
  width: 8px;
  height: 8px;
  border-radius: 1px;
  transform: rotate(45deg);
  background: radial-gradient(circle, rgba(255, 248, 212, 0.98) 0%, rgba(255, 221, 136, 0.68) 52%, rgba(255, 221, 136, 0) 76%);
  opacity: 0.82;
}

.cosmetic-badge[data-badge="icon_stars"]::before {
  top: -4px;
  left: -3px;
  animation: badgeStarsDrift 3s ease-in-out infinite;
}

.cosmetic-badge[data-badge="icon_stars"]::after {
  right: -3px;
  bottom: -3px;
  animation: badgeStarsDrift 3s ease-in-out infinite 1.5s;
}

.cosmetic-badge[data-badge="icon_stars"] .badge-glyph svg .star-main {
  transform-origin: 50% 44%;
  animation: badgeStarsPulse 2.2s ease-in-out infinite;
}

.cosmetic-badge[data-badge="icon_stars"] .badge-glyph svg .star-small {
  transform-box: fill-box;
  transform-origin: center;
}

.cosmetic-badge[data-badge="icon_stars"] .badge-glyph svg .star-small--left {
  animation: badgeStarsOrbitLeft 2.8s ease-in-out infinite;
}

.cosmetic-badge[data-badge="icon_stars"] .badge-glyph svg .star-small--right {
  animation: badgeStarsOrbitRight 2.6s ease-in-out infinite 0.35s;
}

@keyframes badgeLightningSpark {
  0%, 100% {
    transform: scale(0.85);
    opacity: 0.55;
  }
  50% {
    transform: scale(1.18);
    opacity: 1;
  }
}

@keyframes badgeDiamondSparkle {
  0%, 100% {
    transform: rotate(45deg) scale(0.7);
    opacity: 0.35;
  }
  50% {
    transform: rotate(45deg) scale(1.15);
    opacity: 0.95;
  }
}

@keyframes badgeCrownAura {
  0%, 100% {
    transform: scale(0.96);
    opacity: 0.4;
  }
  50% {
    transform: scale(1.08);
    opacity: 0.8;
  }
}

@keyframes badgeYoutubePulse {
  0%, 100% {
    transform: scale(0.92);
    opacity: 0.25;
  }
  50% {
    transform: scale(1.08);
    opacity: 0.78;
  }
}

@keyframes badgeHeartPulse {
  0%, 100% {
    transform: translateY(0) scale(0.96);
  }
  50% {
    transform: translateY(-0.2px) scale(1.06);
  }
}

@keyframes badgeHeartFloatLeft {
  0%, 100% {
    transform: translate(-0.1px, 0.3px) scale(0.94);
    opacity: 0.72;
  }
  50% {
    transform: translate(-0.45px, -0.65px) scale(1.08);
    opacity: 1;
  }
}

@keyframes badgeHeartFloatRight {
  0%, 100% {
    transform: translate(0.1px, 0.28px) scale(0.93);
    opacity: 0.7;
  }
  50% {
    transform: translate(0.42px, -0.62px) scale(1.06);
    opacity: 0.96;
  }
}

@keyframes badgeHeartsShimmer {
  0%, 100% {
    transform: scale(0.78);
    opacity: 0.45;
  }
  50% {
    transform: scale(1.2);
    opacity: 0.9;
  }
}

@keyframes badgeStarsPulse {
  0%, 100% {
    transform: scale(0.94) rotate(0deg);
    opacity: 0.84;
  }
  50% {
    transform: scale(1.1) rotate(3deg);
    opacity: 1;
  }
}

@keyframes badgeStarsOrbitLeft {
  0%, 100% {
    transform: translate(-0.08px, 0.22px) scale(0.9);
    opacity: 0.68;
  }
  50% {
    transform: translate(-0.58px, -0.72px) scale(1.08);
    opacity: 0.98;
  }
}

@keyframes badgeStarsOrbitRight {
  0%, 100% {
    transform: translate(0.1px, 0.2px) scale(0.92);
    opacity: 0.7;
  }
  50% {
    transform: translate(0.56px, -0.68px) scale(1.06);
    opacity: 0.96;
  }
}

@keyframes badgeStarsDrift {
  0%, 100% {
    transform: rotate(45deg) scale(0.7);
    opacity: 0.34;
  }
  50% {
    transform: rotate(45deg) scale(1.14);
    opacity: 0.9;
  }
}

