/* miniapp/styles/layout/shell.css */
body {
  font-family: "Space Grotesk", "Manrope", "Segoe UI", sans-serif;
  background: var(--bg);
  color: var(--text);
  min-height: 100dvh;
  padding:
    calc(18px + var(--tg-safe-top-offset) + var(--app-brand-top-height) + 4px)
    16px
    calc(110px + var(--tg-safe-bottom-offset));
  overflow-x: hidden;
  touch-action: manipulation;
  width: 100%;
  max-width: 100vw;
}

.app-brand-top {
  position: absolute;
  top: var(--app-brand-top-offset);
  left: 50%;
  transform: translateX(-50%);
  width: min(76vw, var(--app-brand-top-width));
  height: var(--app-brand-top-height);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  z-index: 40;
  pointer-events: none;
  overflow: hidden;
}

.app-brand-top-logo {
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: center;
  display: block;
  filter: drop-shadow(0 2px 10px rgba(0, 0, 0, 0.42));
}

.app-brand-top .capture-online-badge {
  display: none;
}

/* Desktop (macOS/Windows): hide top brand logo, keep it on phones/tablets touch */
@media (hover: hover) and (pointer: fine) {
  .app-brand-top {
    display: none;
  }

  body {
    padding-top: calc(18px + var(--tg-safe-top-offset));
  }
}

html,
body {
  overscroll-behavior-x: none;
  overscroll-behavior-y: none;
}

/* The page glow is a viewport-sized fixed layer: as a body background it was scaled to the DOCUMENT height, so the colour
   changed when the number of cards changed (Все → Продать) and faded to black while scrolling a long list. */
body::before {
  content: "";
  position: fixed;
  inset: 0;
  z-index: -1;
  pointer-events: none;
  background:
    radial-gradient(circle 1400px at 50% 0%, #1c0f37 0%, var(--bg) 100%),
    radial-gradient(circle 520px at 20% 100%, rgba(43, 22, 79, 0.9) 0%, transparent 100%);
}

body.mining-active::before {
  display: none;
}

body.admin-active {
  scrollbar-width: none;
  -ms-overflow-style: none;
}

body.admin-active::-webkit-scrollbar {
  width: 0;
  height: 0;
}

body.case-open-active {
  overflow: hidden;
  padding-bottom: calc(16px + var(--tg-safe-bottom-offset));
}

body.capture-active {
  padding: 0;
  overflow-x: hidden;
}

body.capture-active .app-brand-top {
  display: none;
}

@media (max-width: 719px) {
  body.capture-active .app-brand-top {
    display: inline-flex;
    width: auto;
    min-width: 0;
    height: auto;
    padding: 0 8px;
    overflow: visible;
    transform: translate(-50%, 4px);
  }

  body.capture-active .app-brand-top-logo {
    display: none;
  }

  body.capture-active .app-brand-top .capture-online-badge {
    display: inline-flex;
    font-size: 13px;
    font-weight: 800;
    color: rgba(210, 235, 255, 0.96);
    text-shadow: 0 1px 6px rgba(0, 0, 0, 0.45);
    transform: none;
  }

  body.capture-active .app-brand-top .capture-online-badge.hidden {
    display: none;
  }

  body.capture-active.capture-online-scroll-hidden .app-brand-top .capture-online-badge {
    display: none;
  }
}

body.capture-active .shell {
  max-width: none;
  width: 100vw;
  margin: 0;
  gap: 0;
}

body.capture-active .page-capture.active {
  width: 100vw;
  max-width: 100vw;
  min-height: 100dvh;
  min-height: 100vh;
  height: 100dvh;
  height: 100vh;
  margin: 0;
}

