  padding-bottom: calc(var(--bottom-nav-height, 108px) + 36px + env(safe-area-inset-bottom));
}

body.modal-open {
  overflow: hidden;
}

body.capture-modal-open {
  overflow: hidden;
  overscroll-behavior: none;
}

body.capture-modal-open .capture-map-card {
  pointer-events: none;
}

body.capture-modal-open .action-bar {
  opacity: 0 !important;
  pointer-events: none !important;
}

body.deal-chat-active {
  overflow: hidden;
  padding-top: calc(var(--tg-safe-top-offset) + 10px);
  padding-left: 0;
  padding-right: 0;
  padding-bottom: calc(24px + var(--tg-safe-bottom-offset));
}

body.conversations-bg-active {
  padding-left: 0;
  padding-right: 0;
}

body.deal-chat-active .app-brand-top {
  display: none;
}

.bg-orbs {
  display: none;
}

/* Hide decorative orbs on profile — profile has its own gradient */
body.profile-bg-active .bg-orbs {
  display: none;
}

body.deal-chat-active .bg-orbs {
  display: none;
}

/* Keep dialogs background clean without the floating purple orbs */
body.conversations-bg-active .bg-orbs {
  display: none;
}

