/* iOS/Telegram WebView can leave transformed page layers after interrupted swipe transitions.
   Force-reset Activity pages so they don't render as a narrow clipped strip. */
.page.page-coins.active,
.page.page-coins-detail.active {
  transform: none;
  opacity: 1;
}

@keyframes pageFadeIn {
  from { opacity: 0; }
  to { opacity: 1; }
}

/* One page transition for every screen (2026-10): a soft rise from below + fade, no sideways slide, no scale.
   The page rises first, its top blocks follow one after another. The Market page already rises block by block (marketBlockEnter, market-shell.css) and is the reference, so it is excluded. Only opacity/transform are animated and the fill
   mode is "backwards", so no transformed layer is left behind once it ends. */
@keyframes pageEnter {
  from { opacity: 0; transform: translateY(10px); }
  to { opacity: 1; transform: translateY(0); }
}

.page.active:not(.page-market).swipe-enter-left,
.page.active:not(.page-market).swipe-enter-right {
  animation: pageEnter 240ms cubic-bezier(0.22, 0.8, 0.3, 1) backwards;
}

.page.active:not(.page-market).swipe-enter-left > *,
.page.active:not(.page-market).swipe-enter-right > *,
.page-profile.active .profile-content-layer.swipe-enter-left > *,
.page-profile.active .profile-content-layer.swipe-enter-right > * {
  animation: pageEnter 280ms cubic-bezier(0.22, 0.8, 0.3, 1) backwards;
}

.page.active:not(.page-market).swipe-enter-left > *:nth-child(1), .page.active:not(.page-market).swipe-enter-right > *:nth-child(1),
.page-profile.active .profile-content-layer.swipe-enter-left > *:nth-child(1), .page-profile.active .profile-content-layer.swipe-enter-right > *:nth-child(1) { animation-delay: 30ms; }
.page.active:not(.page-market).swipe-enter-left > *:nth-child(2), .page.active:not(.page-market).swipe-enter-right > *:nth-child(2),
.page-profile.active .profile-content-layer.swipe-enter-left > *:nth-child(2), .page-profile.active .profile-content-layer.swipe-enter-right > *:nth-child(2) { animation-delay: 65ms; }
.page.active:not(.page-market).swipe-enter-left > *:nth-child(3), .page.active:not(.page-market).swipe-enter-right > *:nth-child(3),
.page-profile.active .profile-content-layer.swipe-enter-left > *:nth-child(3), .page-profile.active .profile-content-layer.swipe-enter-right > *:nth-child(3) { animation-delay: 100ms; }
.page.active:not(.page-market).swipe-enter-left > *:nth-child(4), .page.active:not(.page-market).swipe-enter-right > *:nth-child(4),
.page-profile.active .profile-content-layer.swipe-enter-left > *:nth-child(4), .page-profile.active .profile-content-layer.swipe-enter-right > *:nth-child(4) { animation-delay: 135ms; }
.page.active:not(.page-market).swipe-enter-left > *:nth-child(n+5), .page.active:not(.page-market).swipe-enter-right > *:nth-child(n+5),
.page-profile.active .profile-content-layer.swipe-enter-left > *:nth-child(n+5), .page-profile.active .profile-content-layer.swipe-enter-right > *:nth-child(n+5) { animation-delay: 160ms; }

html.android-lite .page.active {
  min-height: calc(var(--app-height, 100dvh) - 110px);
}

html.android-lite .page.active:not(.page-market).swipe-enter-left,
html.android-lite .page.active:not(.page-market).swipe-enter-right {
  animation: pageFadeIn 160ms ease-out backwards;
}

html.android-lite .page.active:not(.page-market).swipe-enter-left > *,
html.android-lite .page.active:not(.page-market).swipe-enter-right > * {
  animation: none;
}

@media (prefers-reduced-motion: reduce) {
  .page.active:not(.page-market).swipe-enter-left,
  .page.active:not(.page-market).swipe-enter-right {
    animation: pageFadeIn 120ms ease-out backwards;
  }

  .page.active:not(.page-market).swipe-enter-left > *,
  .page.active:not(.page-market).swipe-enter-right > *,
  .page-profile.active .profile-content-layer.swipe-enter-left > *,
  .page-profile.active .profile-content-layer.swipe-enter-right > * {
    animation: none;
  }
}


/* A page's own cards must not replay the old fadeUp when the transition class is removed (it showed as a second flash after
   ~0.3s on every page, most visibly in chats); the chat page has no extra slide of its own either. */
.page > .card {
  animation: none;
}

.page.page-deal-chat.anim-enter {
  animation: none;
}

/* The page loader covers the whole screen down to the bottom edge (it used to stop one nav-height short, leaving an
   unfilled strip under the floating bar); its content stays centred above the bar via bottom padding. */
.page-data-loader.root-page-data-loader,
.page-data-loader--capture {
  inset: 0;
  padding-bottom: calc(var(--bottom-nav-height, 76px) + env(safe-area-inset-bottom, 0px));
  box-sizing: border-box;
}

/* miniapp/styles/components/market-cards.css */
/* ============================================
   MARKET CARDS - NEW DESIGN
   ============================================ */

.market-card {
  --market-card-border: rgba(124, 92, 255, 0.16);
  --market-card-bg-start: rgba(34, 20, 66, 0.95);
  --market-card-bg-end: rgba(22, 13, 43, 0.97);
  --market-thumb-glow: rgba(115, 80, 210, 0.1);
  --market-thumb-bg-start: rgba(33, 20, 62, 0.96);
  --market-thumb-bg-end: rgba(22, 13, 43, 0.98);
  --market-chip-border: rgba(170, 136, 255, 0.34);
  --market-chip-bg: rgba(124, 92, 255, 0.18);
  --market-chip-text: rgba(234, 220, 255, 0.98);
  position: relative;
  padding: 0;
  border-radius: 16px;
  background: linear-gradient(160deg, var(--market-card-bg-start), var(--market-card-bg-end));
  border: 1px solid var(--market-card-border);
  cursor: pointer;
  display: grid;
  grid-template-rows: auto auto;
  gap: 0;
  transition: all 0.2s ease;
  overflow: clip;
}

.market-card::before {
  content: "";
  position: absolute;
  inset: 0;
  background:
    linear-gradient(180deg, rgba(255, 255, 255, 0.02), rgba(255, 255, 255, 0));
  pointer-events: none;
  border-radius: 16px;
}

.market-card-thumb {
  --market-thumb-pad: 9px;
  position: relative;
  overflow: hidden;
  border-radius: 16px;
  aspect-ratio: 1 / 1;
  padding: var(--market-thumb-pad);
  background:
    radial-gradient(90% 80% at 50% 100%, var(--market-thumb-glow), rgba(115, 80, 210, 0) 70%),
    linear-gradient(160deg, var(--market-thumb-bg-start), var(--market-thumb-bg-end));
}

.market-card-thumb::before {
  content: "";
  position: absolute;
  inset: var(--market-thumb-pad);
  border-radius: 14px;
  border: 1px solid rgba(136, 162, 232, 0.24);
  background: linear-gradient(160deg, rgba(18, 24, 44, 0.52), rgba(14, 18, 34, 0.58));
  pointer-events: none;
}

.market-card-thumb-skeleton {
  position: absolute;
  inset: var(--market-thumb-pad);
  border-radius: 14px;
  background: linear-gradient(100deg, rgba(95, 65, 170, 0.16) 30%, rgba(180, 152, 255, 0.36) 50%, rgba(95, 65, 170, 0.16) 70%);
  background-size: 220% 100%;
  animation: marketThumbPulse 1.4s linear infinite;
}

.market-card-thumb-img {
  position: absolute;
  inset: var(--market-thumb-pad);
  width: calc(100% - var(--market-thumb-pad) * 2);
  height: calc(100% - var(--market-thumb-pad) * 2);
  border-radius: 14px;
  object-fit: cover;
  display: block;
  opacity: 0;
  transition: opacity 0.22s ease;
}

.market-card-thumb-img.is-cover {
  object-fit: contain;
  padding: 10%;
  transform: scale(0.97);
  filter: drop-shadow(0 10px 18px rgba(16, 10, 30, 0.35));
}

.market-card-thumb-img--cover-realestate {
  object-position: 50% 50%;
  transform: scale(1.1);
  transform-origin: center center;
}

.market-card-thumb-fallback {
  position: absolute;
  inset: var(--market-thumb-pad);
  border-radius: 14px;
  display: grid;
  place-items: center;
  padding: 20px;
  color: rgba(194, 169, 255, 0.9);
  opacity: 0;
  transition: opacity 0.2s ease;
  background: linear-gradient(160deg, rgba(35, 22, 66, 0.98), rgba(19, 12, 36, 0.98));
}

.market-card-thumb-fallback-label {
  display: inline-flex;
  padding: 6px 10px;
  border-radius: 999px;
  font-size: 11px;
  font-weight: 700;
  border: 1px solid rgba(134, 102, 230, 0.38);
  background: rgba(88, 58, 164, 0.28);
  color: #efe7ff;
  text-align: center;
}

.market-card-thumb.is-loading .market-card-thumb-img {
  opacity: 0;
}

.market-card-thumb:not(.is-loading) .market-card-thumb-img {
  opacity: 1;
}

.market-card-thumb:not(.is-loading) .market-card-thumb-skeleton {
  opacity: 0;
  transition: opacity 0.2s ease;
}

.market-card-thumb-fallback.is-visible {
  opacity: 1;
}

.market-card:active {
  transform: scale(0.985);
}

.market-card--buy {
  --market-card-border: rgba(91, 196, 255, 0.24);
  --market-card-bg-start: rgba(16, 44, 76, 0.95);
  --market-card-bg-end: rgba(10, 26, 49, 0.98);
  --market-thumb-glow: rgba(79, 176, 255, 0.16);
  --market-thumb-bg-start: rgba(14, 45, 74, 0.97);
  --market-thumb-bg-end: rgba(9, 28, 49, 0.99);
  --market-chip-border: rgba(114, 206, 255, 0.36);
  --market-chip-bg: rgba(68, 170, 255, 0.18);
  --market-chip-text: rgba(224, 245, 255, 0.98);
}

/* TOP Card */
.market-card--top {
  border-color: rgba(255, 194, 88, 0.72);
  background: linear-gradient(145deg,
    rgba(62, 36, 88, 0.92) 0%,
    rgba(46, 25, 72, 0.95) 52%,
    rgba(31, 18, 57, 0.97) 100%
  );
  box-shadow:
    0 10px 24px rgba(38, 22, 74, 0.26),
    inset 0 1px 0 rgba(255, 225, 140, 0.28);
}

.market-card--top .market-card-thumb {
  background: linear-gradient(160deg, rgba(33, 20, 62, 0.96), rgba(22, 13, 43, 0.98));
}

.market-card--top::after {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 2px;
  background: linear-gradient(90deg,
    transparent,
    rgba(255, 180, 50, 0.6),
    rgba(255, 220, 100, 0.8),
    rgba(255, 180, 50, 0.6),
    transparent
  );
}

.market-card-top-badge {
  position: absolute;
  top: calc(var(--market-thumb-pad) + 6px);
  left: calc(var(--market-thumb-pad) + 6px);
  font-size: 9px;
  font-weight: 700;
  padding: 4px 8px;
  border-radius: 999px;
  background: rgba(255, 179, 59, 0.94);
  border: 1px solid rgba(255, 213, 130, 0.58);
  color: #2d1306;
  letter-spacing: 0.3px;
  text-transform: uppercase;
  z-index: 4;
}

.market-card-top-badge--new {
  background: linear-gradient(135deg, rgba(92, 224, 255, 0.95), rgba(66, 172, 255, 0.95));
  border-color: rgba(163, 231, 255, 0.7);
  color: #032235;
}

.market-card--top .market-card-title {
  text-shadow: 0 1px 12px rgba(255, 204, 104, 0.18);
}

.market-card--top .market-card-price {
  background: linear-gradient(90deg, #FFD87A, #FFC15D);
  -webkit-background-clip: text;
  background-clip: text;
}

/* Card Content */
.market-card-content {
  display: grid;
  grid-template-rows: auto auto auto;
  gap: 5px;
  padding: 7px 10px 10px;
  background: transparent;
  border-top: none;
}

.market-card-price-row {
  display: flex;
  align-items: center;
  justify-content: flex-start;
  min-width: 0;
  width: 100%;
  margin-top: 2px;
}

.market-card-price-chip {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 3px 10px;
  border-radius: 999px;
  border: 1px solid var(--market-chip-border);
  background: var(--market-chip-bg);
  margin-inline: 0;
}

.market-card-price-chip::before {
  content: "";
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: linear-gradient(135deg, #ffd56a, #ffb340);
  box-shadow: 0 0 8px rgba(255, 192, 93, 0.45);
}

.market-card-icon {
  flex-shrink: 0;
  width: 40px;
  height: 40px;
  border-radius: 10px;
  background: linear-gradient(145deg, rgba(124, 92, 255, 0.15), rgba(77, 163, 255, 0.1));
  border: 1px solid rgba(124, 92, 255, 0.25);
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 8px;
}

.market-card-icon svg {
  width: 100%;
  height: 100%;
}

.market-card-info {
  display: none;
}

.market-card-title {
  font-size: 14px;
  font-weight: 700;
  line-height: 1.18;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  color: #ffffff;
  min-height: 1.15em;
  margin-bottom: 0;
}

.market-card-price {
  font-size: 13px;
  font-weight: 800;
  color: var(--market-chip-text);
  line-height: 1.1;
}

.market-card-type-badge {
  position: absolute;
  left: calc(var(--market-thumb-pad) + 10px);
  bottom: calc(var(--market-thumb-pad) + 10px);
  z-index: 4;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 0;
  max-width: calc(100% - (var(--market-thumb-pad) * 2) - 20px);
  padding: 6px 12px;
  border-radius: 11px;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.08px;
  line-height: 1;
  backdrop-filter: blur(14px);
  -webkit-backdrop-filter: blur(14px);
  box-shadow: 0 6px 18px rgba(7, 12, 24, 0.16);
  white-space: nowrap;
}

.market-card-type-badge--sell {
  color: rgba(255, 247, 255, 0.96);
  background: rgba(255, 255, 255, 0.16);
  border: 1px solid rgba(236, 211, 255, 0.26);
}

.market-card-type-badge--buy {
  color: rgba(244, 252, 255, 0.96);
  background: rgba(206, 240, 255, 0.18);
  border: 1px solid rgba(196, 233, 255, 0.26);
}

.market-card-meta-line {
  display: block;
  min-width: 0;
  color: rgba(188, 194, 208, 0.78);
  font-size: 11px;
  font-weight: 620;
  line-height: 1.2;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

/* Card Footer */
.market-card-footer {
  display: flex;
  justify-content: flex-end;
  align-items: center;
  gap: 8px;
  padding-top: 6px;
  border-top: 1px solid rgba(124, 92, 255, 0.12);
}

.market-card-meta {
  display: flex;
  align-items: center;
  gap: 6px;
  min-width: 0;
  overflow: hidden;
}

.market-card-meta-category-chip {
  display: inline-flex;
  align-items: center;
  width: 100%;
  min-width: 0;
  padding: 2px 7px;
  border-radius: 999px;
  border: 1px solid rgba(132, 98, 255, 0.36);
  background: rgba(126, 90, 255, 0.2);
  color: #e6d8ff;
  font-size: 9px;
  font-weight: 700;
  line-height: 1.2;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.market-card-meta-server-chip {
  max-width: 118px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 2px 7px;
  border-radius: 999px;
  border: 1px solid rgba(82, 199, 255, 0.35);
  background: rgba(68, 142, 255, 0.14);
  color: rgba(185, 228, 255, 0.96);
  font-size: 9px;
  font-weight: 700;
  line-height: 1.2;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.market-card-meta-server-text {
  flex: 1 1 auto;
  min-width: 0;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  color: rgba(180, 160, 220, 0.88);
  font-size: 11px;
  font-weight: 600;
  line-height: 1.2;
}

.market-card-actions {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  width: 100%;
}

.market-card-views {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  color: rgba(172, 224, 255, 0.95);
  font-size: 13px;
  font-weight: 700;
  font-variant-numeric: tabular-nums;
}

.market-card-views svg {
  width: 16px;
  height: 16px;
  opacity: 0.92;
}

.market-card-fav {
  width: 24px;
  height: 24px;
  border-radius: 0;
  background: transparent;
  border: none;
  display: flex;
  align-items: center;
  justify-content: center;
  color: rgba(180, 160, 220, 0.75);
  cursor: pointer;
  transition: all 0.2s ease;
  padding: 0;
}

.market-card-fav svg {
  width: 18px;
  height: 18px;
}

.market-card-fav:active {
  transform: scale(0.92);
}

.market-card-fav.active {
  color: #FF5078;
}

.market-card-thumb-fav {
  position: absolute;
  right: calc(var(--market-thumb-pad) + 6px);
  bottom: calc(var(--market-thumb-pad) + 6px);
  z-index: 4;
  width: 26px;
  height: 26px;
  border: none;
  border-radius: 0;
  background: transparent;
  color: rgba(255, 192, 216, 0.86);
  backdrop-filter: none;
  -webkit-backdrop-filter: none;
  box-shadow: none;
}

.market-card-thumb-fav svg {
  width: 22px;
  height: 22px;
  filter: drop-shadow(0 2px 6px rgba(22, 10, 44, 0.42));
}

.market-card-thumb-fav .fav-heart-fill {
  opacity: 0.2;
  transition: opacity 0.2s ease;
}

.market-card-thumb-fav.active .fav-heart-fill {
  opacity: 0.86;
}

.market-listings--list .market-card {
  display: grid;
  grid-template-columns: 88px 1fr;
  gap: 10px;
  align-items: stretch;
}

.market-listings--list .market-card-thumb {
  --market-thumb-pad: 6px;
  aspect-ratio: 1 / 1;
}

.market-listings--list .market-card-content {
  display: grid;
  gap: 6px;
}

.market-listings--list .market-card-info {
  grid-template-rows: auto auto auto;
  gap: 5px;
}

.market-listings--list .market-card-desc {
  min-height: 0;
}

.market-listings--list .market-card-footer {
  grid-column: 1 / -1;
}

.market-listings--list .market-card-title,
.market-listings--list .market-card-meta {
  min-height: 0;
}

/* Animation for cards appearing */
@keyframes marketCardIn {
  from {
    opacity: 0;
    transform: translateY(10px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@keyframes marketThumbPulse {
  0% {
    background-position: 220% 0;
  }
  100% {
    background-position: -220% 0;
  }
}

.market-card {
  animation: marketCardIn 0.3s ease backwards;
}

.market-listings.no-card-anim .market-card {
  animation: none;
}

.market-card:nth-child(1) { animation-delay: 0s; }
.market-card:nth-child(2) { animation-delay: 0.05s; }
.market-card:nth-child(3) { animation-delay: 0.1s; }
.market-card:nth-child(4) { animation-delay: 0.15s; }
.market-card:nth-child(5) { animation-delay: 0.2s; }

/* Mobile adjustments */
@media (max-width: 380px) {
  .market-card {
    border-radius: 14px;
  }

  .market-card-thumb-fav {
    width: 26px;
    height: 26px;
  }

  .market-listings--grid {
    gap: 8px;
  }

  .market-card-content {
    padding: 7px 8px 7px;
  }
}

.market-type-switch,
.create-type-switch {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 8px;
  margin: 10px 0 14px;
}

.create-type-switch {
  grid-template-columns: repeat(2, minmax(0, 1fr));
  margin: 2px 0 12px;
}

.market-type-chip,
.create-type-chip {
