  min-height: 42px;
  border: 1px solid rgba(255, 255, 255, 0.08);
  border-radius: 14px;
  background: rgba(17, 13, 33, 0.74);
  color: rgba(212, 218, 236, 0.82);
  font-size: 13px;
  font-weight: 800;
  letter-spacing: 0.1px;
  cursor: pointer;
  transition: transform 0.18s ease, border-color 0.18s ease, background 0.18s ease, color 0.18s ease, box-shadow 0.18s ease;
}

.market-type-chip:active,
.create-type-chip:active {
  transform: scale(0.98);
}

.market-type-chip.active,
.create-type-chip.active {
  color: #fff;
  box-shadow: 0 12px 26px rgba(14, 18, 36, 0.3);
}

.market-type-chip[data-market-type="all"].active {
  border-color: rgba(188, 168, 255, 0.32);
  background: linear-gradient(135deg, rgba(67, 49, 112, 0.92), rgba(47, 33, 83, 0.94));
}

.market-type-chip[data-market-type="buy"].active,
.create-type-chip[data-create-type="buy"].active {
  border-color: rgba(155, 228, 255, 0.34);
  background: linear-gradient(135deg, rgba(50, 138, 221, 0.92), rgba(34, 98, 181, 0.94));
}

.market-type-chip[data-market-type="sell"].active,
.create-type-chip[data-create-type="sell"].active {
  border-color: rgba(216, 188, 255, 0.34);
  background: linear-gradient(135deg, rgba(120, 82, 223, 0.92), rgba(91, 61, 196, 0.94));
}

.listing-main {
  display: grid;
  gap: 6px;
}

.listing-title {
  font-size: 16px;
  font-weight: 700;
  letter-spacing: 0.2px;
}

.market-price {
  font-size: 18px;
  font-weight: 800;
  line-height: 1.1;
  background: linear-gradient(90deg, #f3eaff, #c4a7ff);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
}

.market-price,
.public-listing-price,
.listing-price {
  display: inline-flex;
  align-items: baseline;
  gap: 6px;
}

.price-game-note {
  font-size: 10px;
  color: rgba(198, 179, 255, 0.6);
  letter-spacing: 0.2px;
}

.coin-hero {
  padding: 18px;
  background: radial-gradient(circle at top, rgba(140, 98, 255, 0.22), rgba(17, 10, 35, 0.9));
  border-color: rgba(130, 92, 255, 0.45);
  box-shadow: 0 20px 40px rgba(68, 35, 140, 0.28);
}

.coin-hero-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
}

.coin-balance-row {
  margin-top: 6px;
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 12px;
}

.coin-history-link {
  background: transparent;
  border: none;
  padding: 0;
  color: rgba(214, 199, 255, 0.85);
  font-size: 12px;
  font-weight: 700;
  cursor: pointer;
  white-space: nowrap;
  text-decoration: none;
}

.coin-history-link:active {
  opacity: 0.8;
}

.coin-tiles {
