}

body.coins-window-open .action-bar {
  opacity: 0;
  pointer-events: none;
}

body.keyboard-open .action-bar {
  transform: translateX(calc(-50% + var(--swipe-dx, 0px))) translateY(22px) scale(0.96);
  opacity: 0;
  pointer-events: none;
}

body.coins-window-open #createFab {
  opacity: 0;
  pointer-events: none;
}

body.keyboard-open #createFab {
  opacity: 0;
  pointer-events: none;
}

.shop-action {
  margin-top: 8px;
  width: 100%;
  border-radius: 14px;
  border: 1px solid rgba(122, 60, 255, 0.35);
  background: rgba(122, 60, 255, 0.14);
  color: #fff;
