/* miniapp/styles/components/modals.css */
.modal {
  position: fixed;
  inset: 0;
  display: none;
  align-items: center;
  justify-content: center;
  background: rgba(6, 4, 12, 0);
  z-index: 100;
  padding: 16px;
  transition: background 0.3s ease;
}

.modal.show {
  display: flex;
  background: rgba(6, 4, 12, 0.85);
  backdrop-filter: blur(16px);
  -webkit-backdrop-filter: blur(16px);
}

.modal-card {
  position: relative;
  width: 100%;
  max-width: 420px;
  max-height: 85vh;
  overflow-y: auto;
  background: linear-gradient(165deg, rgba(30, 20, 55, 0.98) 0%, rgba(15, 10, 30, 0.98) 100%);
  border-radius: 24px;
  padding: 24px 20px;
  border: 1px solid rgba(124, 92, 255, 0.3);
  box-shadow:
    0 25px 60px rgba(0, 0, 0, 0.5),
    0 0 0 1px rgba(255, 255, 255, 0.05) inset,
    0 0 80px rgba(124, 92, 255, 0.15);
  transform: scale(0.9) translateY(20px);
  opacity: 0;
  animation: modalPopIn 0.35s cubic-bezier(0.34, 1.56, 0.64, 1) forwards;
}

.modal-corner-close {
  position: absolute;
  top: 12px;
  right: 12px;
  width: 30px;
  height: 30px;
  border-radius: 10px;
  border: 1px solid rgba(255, 255, 255, 0.16);
  background: rgba(255, 255, 255, 0.06);
  color: rgba(232, 224, 255, 0.92);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-size: 16px;
  line-height: 1;
  cursor: pointer;
  z-index: 2;
  transition: background 0.18s ease, border-color 0.18s ease, transform 0.18s ease;
}

.modal-corner-close:active {
  transform: scale(0.95);
}

.modal-corner-close:hover {
  background: rgba(255, 255, 255, 0.11);
  border-color: rgba(255, 255, 255, 0.26);
}

@keyframes modalPopIn {
  from {
    transform: scale(0.9) translateY(20px);
    opacity: 0;
  }
  to {
    transform: scale(1) translateY(0);
    opacity: 1;
  }
}

