}

.page-deal-chat {
  display: none;
}

.page-deal-chat.active {
  display: flex;
  align-items: stretch;
  height: max(320px, var(--deal-chat-viewport-height));
  min-height: max(320px, var(--deal-chat-viewport-height));
  max-height: max(320px, var(--deal-chat-viewport-height));
  overflow: hidden;
}

.deal-chat-page {
  align-self: stretch;
  flex: 1 1 auto;
  width: 100%;
  height: 100%;
  min-height: 0;
  display: flex;
  flex-direction: column;
  gap: 8px;
  overflow: hidden;
}

/* Remove card frame from deal-chat — chat should feel like a full-screen messenger */
.deal-chat-page.card {
  background: transparent;
  border: none;
  border-radius: 0;
  box-shadow: none;
  backdrop-filter: none;
  -webkit-backdrop-filter: none;
  padding: 8px 10px 0;
}

/* ── Deal Chat Header (Telegram-style) ── */

.deal-chat-top {
  display: grid;
  gap: 0;
  flex: 0 0 auto;
  min-height: 0;
  padding: 0;
  border-bottom: 1px solid rgba(255, 255, 255, 0.06);
  background: rgba(15, 20, 40, 0.15);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
}

.deal-chat-header {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 10px;
  align-items: center;
  padding: 7px 2px;
}

.deal-chat-header-media {
  display: grid;
  grid-template-columns: 38px minmax(0, 1fr);
  gap: 10px;
  align-items: center;
  min-width: 0;
}

.deal-chat-avatar {
  position: relative;
  width: 38px;
  height: 38px;
  border-radius: 50%;
  overflow: visible;
  border: none;
  background: rgba(80, 120, 200, 0.35);
  display: grid;
  place-items: center;
  flex-shrink: 0;
}

.deal-chat-avatar img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
  border-radius: 50%;
}

.deal-chat-avatar img.deal-chat-avatar-img--cover {
  object-fit: contain;
  padding: 3px;
}

.deal-chat-avatar-fallback {
  font-size: 16px;
  font-weight: 600;
  color: rgba(255, 255, 255, 0.9);
}

.deal-chat-avatar.deal-chat-avatar--support {
  background: linear-gradient(135deg, #3b82f6, #60a5fa);
}

.deal-chat-avatar.deal-chat-avatar--server {
  background: linear-gradient(145deg, hsl(var(--server-hue, 170) 68% 56%), hsl(calc(var(--server-hue, 170) + 28) 60% 32%));
}

/* server chat cover: big number + caption on the per-server gradient; sizes follow the circle (cqw), so list and header look alike */
.deal-chat-avatar-server-svg {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 50%;
  overflow: hidden;
  container-type: size;
  pointer-events: none;
}
.conversations-item-avatar--server {
  container-type: size;
}
.server-cover {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 3cqw;
  line-height: 1;
  color: #fff;
  text-shadow: 0 1px 3px rgba(0, 0, 0, 0.28);
}
.server-cover-num {
  font-size: 40cqw;
  font-weight: 800;
  letter-spacing: -0.02em;
}
.server-cover-cap {
  font-size: max(6px, 13cqw);
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  opacity: 0.85;
}


.deal-chat-avatar.deal-chat-avatar--support img {
  object-fit: contain;
  padding: 3px;
}

.deal-chat-avatar.deal-chat-avatar--support .deal-chat-avatar-fallback {
  font-size: 20px;
}

.deal-chat-avatar-online-dot {
  position: absolute;
  right: -1px;
  bottom: -1px;
  width: 11px;
  height: 11px;
  border-radius: 50%;
  background: #2ecc71;
  border: 2px solid rgba(15, 20, 40, 0.92);
  box-shadow: 0 0 10px rgba(46, 204, 113, 0.75);
  opacity: 0;
  transform: scale(0.75);
  transition: opacity 0.18s ease, transform 0.18s ease;
  pointer-events: none;
}

.deal-chat-avatar-online-dot.is-visible {
  opacity: 1;
  transform: scale(1);
}

.deal-chat-header-main {
  min-width: 0;
  display: grid;
  gap: 1px;
}

.deal-chat-title {
  font-size: 15px;
  font-weight: 600;
  line-height: 1.25;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  color: rgba(240, 240, 255, 0.97);
}

.deal-chat-title.is-link {
  cursor: pointer;
}

.deal-chat-counterparty {
  font-size: 12px;
  color: rgba(130, 155, 200, 0.6);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.deal-chat-report-btn {
  width: 32px;
  height: 32px;
  border: none;
  border-radius: 50%;
  background: transparent;
  color: rgba(200, 200, 220, 0.5);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  padding: 0;
  transition: color 0.15s ease, background 0.15s ease;
}

.deal-chat-report-btn:active {
  color: rgba(220, 220, 240, 0.8);
  background: rgba(255, 255, 255, 0.06);
}

.deal-chat-report-btn svg {
  width: 20px;
  height: 20px;
}

/* ── Pinned listing (glass card) ── */

.deal-chat-pinned {
  display: flex;
  gap: 8px;
  align-items: center;
  padding: 8px 12px;
  margin: 6px 6px 0;
  cursor: pointer;
  border-radius: 14px;
  background:
    linear-gradient(135deg, rgba(72, 118, 238, 0.12), rgba(68, 95, 214, 0.08)),
    rgba(30, 40, 80, 0.35);
  border: 1px solid rgba(140, 180, 255, 0.18);
  box-shadow:
    0 4px 12px rgba(4, 10, 28, 0.2),
    inset 0 1px 0 rgba(180, 210, 255, 0.08);
  backdrop-filter: blur(8px) saturate(120%);
  -webkit-backdrop-filter: blur(8px) saturate(120%);
  transition: transform 0.15s ease, border-color 0.18s ease;
}

.deal-chat-pinned:active {
  transform: scale(0.98);
  border-color: rgba(140, 180, 255, 0.28);
}

.deal-chat-pinned.hidden {
  display: none;
}

.deal-chat-pinned-accent {
  width: 3px;
  min-height: 26px;
  align-self: stretch;
  border-radius: 2px;
  background: linear-gradient(180deg, rgba(80, 160, 255, 0.8), rgba(100, 130, 255, 0.5));
  flex-shrink: 0;
}

.deal-chat-pinned-body {
  flex: 1;
  min-width: 0;
}

.deal-chat-pinned-label {
  font-size: 11px;
  font-weight: 600;
  color: rgba(120, 185, 255, 0.85);
  line-height: 1.3;
}

.deal-chat-pinned-text {
  font-size: 12px;
  color: rgba(210, 220, 245, 0.7);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  line-height: 1.35;
}

/* ── Messages stream ── */

.deal-chat-messages {
  flex: 1 1 auto;
  min-height: 0;
  max-height: none;
  overflow-y: auto;
  overscroll-behavior: contain;
  -webkit-overflow-scrolling: touch;
  padding: 10px 8px 12px;
  display: flex;
  flex-direction: column;
  gap: 3px;
  align-content: flex-start;
}

.deal-chat-stream {
  flex: 1 1 auto;
  min-height: 0;
  display: flex;
  flex-direction: column;
  gap: 0;
  overflow: hidden;
}

.deal-chat-empty {
  padding: 20px 24px;
  border-radius: 14px;
  background:
    linear-gradient(135deg, rgba(72, 118, 238, 0.06), rgba(68, 95, 214, 0.03)),
    rgba(25, 35, 70, 0.2);
  border: 1px solid rgba(140, 180, 255, 0.08);
  color: rgba(180, 190, 220, 0.5);
  font-size: 13px;
  line-height: 1.45;
  text-align: center;
  align-self: center;
  margin-top: 32px;
  max-width: 280px;
}

/* ── Support status ── */

.deal-chat-support-status {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
  align-content: flex-start;
  justify-content: flex-start;
}

.deal-chat-support-status-label {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 4px 10px;
  border-radius: 999px;
  border: 1px solid rgba(139, 92, 246, 0.35);
  color: rgba(196, 181, 253, 0.96);
  background: rgba(139, 92, 246, 0.12);
  font-size: 12px;
  font-weight: 700;
  line-height: 1.1;
}

.deal-chat-support-status-label::before {
  content: "";
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: rgba(167, 139, 250, 0.95);
  box-shadow: 0 0 8px rgba(167, 139, 250, 0.6);
  flex-shrink: 0;
}

.deal-chat-support-status-label.is-resolved {
  border-color: rgba(191, 181, 104, 0.35);
  color: rgba(248, 236, 182, 0.96);
  background: rgba(94, 84, 27, 0.28);
}

.deal-chat-support-status-label.is-resolved::before {
  background: rgba(246, 220, 120, 0.95);
  box-shadow: 0 0 8px rgba(246, 220, 120, 0.5);
}

.deal-chat-support-status-note {
  font-size: 12px;
  color: rgba(211, 196, 164, 0.95);
  line-height: 1.3;
  background: rgba(83, 63, 26, 0.24);
  border: 1px solid rgba(191, 166, 104, 0.26);
  border-radius: 10px;
  padding: 4px 9px;
}

.deal-chat-support-topics {
  flex: 0 0 auto;
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
}

.deal-chat-support-topics .pill {
  font-size: 12px;
  padding: 6px 10px;
}

/* ── Chat bubbles ── */

.deal-chat-msg-row {
  display: flex;
  gap: 6px;
  align-items: flex-end;
  align-self: flex-start;
  max-width: 80%;
  margin-bottom: 2px;
}

.deal-chat-msg-row.is-me {
  align-self: flex-end;
  flex-direction: row-reverse;
}

.deal-chat-msg-row.is-system {
  align-self: center;
  max-width: 96%;
  width: 100%;
  margin: 5px 0;
}

/* Small avatar for incoming messages */
.deal-chat-msg-ava {
  width: 24px;
  height: 24px;
  min-width: 24px;
  border-radius: 50%;
  overflow: hidden;
  background: rgba(255, 255, 255, 0.08);
  display: grid;
  place-items: center;
  flex-shrink: 0;
  margin-bottom: 2px;
}

.deal-chat-msg-ava img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}

.deal-chat-msg-ava-fallback {
  font-size: 11px;
  color: rgba(200, 190, 230, 0.75);
  font-weight: 700;
  text-transform: uppercase;
}

.deal-chat-msg-row.is-me .deal-chat-msg-ava,
.deal-chat-msg-row.is-system .deal-chat-msg-ava { display: none; }

/* Bubble — glass style */
.deal-chat-msg {
  max-width: 100%;
  padding: 8px 12px 6px;
  border-radius: 16px 16px 16px 4px;
  background:
    linear-gradient(135deg, rgba(80, 100, 160, 0.12), rgba(60, 75, 130, 0.08)),
    rgba(30, 38, 65, 0.45);
  border: 1px solid rgba(140, 170, 230, 0.12);
  box-shadow: inset 0 1px 0 rgba(180, 210, 255, 0.06);
  backdrop-filter: blur(6px);
  -webkit-backdrop-filter: blur(6px);
  position: relative;
}

.deal-chat-msg.is-me {
  border-radius: 16px 16px 4px 16px;
  background:
    linear-gradient(135deg, rgba(50, 120, 240, 0.22), rgba(40, 90, 200, 0.18)),
    rgba(20, 50, 120, 0.35);
  border-color: rgba(80, 150, 255, 0.2);
  box-shadow: inset 0 1px 0 rgba(120, 180, 255, 0.1);
}

/* System messages: glass info card */
.deal-chat-msg.is-system {
  border-radius: 12px;
  background:
    linear-gradient(135deg, rgba(72, 118, 238, 0.08), rgba(68, 95, 214, 0.05)),
    rgba(25, 35, 70, 0.3);
  border: 1px solid rgba(140, 180, 255, 0.12);
  box-shadow:
    0 2px 8px rgba(4, 10, 28, 0.15),
    inset 0 1px 0 rgba(180, 210, 255, 0.06);
  backdrop-filter: blur(6px);
  -webkit-backdrop-filter: blur(6px);
  padding: 9px 14px 8px;
  text-align: center;
  width: 100%;
}

.deal-chat-msg-text {
  font-size: 14px;
  line-height: 1.45;
  white-space: pre-wrap;
  word-break: break-word;
  color: rgba(235, 235, 255, 0.93);
}

.deal-chat-msg-reply {
  margin-bottom: 6px;
  padding: 6px 8px;
  border-radius: 10px;
  background: rgba(120, 150, 220, 0.12);
  border: 1px solid rgba(150, 180, 240, 0.24);
}

.deal-chat-msg-reply-name {
  font-size: 11px;
  font-weight: 700;
  line-height: 1.25;
  color: rgba(156, 197, 255, 0.95);
}

.deal-chat-msg-reply-text {
  margin-top: 2px;
  font-size: 12px;
  line-height: 1.3;
  color: rgba(206, 220, 255, 0.8);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.deal-chat-msg.is-system .deal-chat-msg-text {
  font-size: 12px;
  color: rgba(180, 185, 215, 0.65);
  font-style: italic;
}

.deal-chat-msg-meta {
  margin-top: 2px;
  font-size: 10px;
  color: rgba(160, 170, 200, 0.4);
  text-align: right;
  display: inline-flex;
  align-items: center;
  justify-content: flex-end;
  gap: 4px;
  width: 100%;
}

.deal-chat-msg-meta.is-link {
  cursor: pointer;
}

.deal-chat-msg.is-me .deal-chat-msg-meta {
  color: rgba(110, 170, 255, 0.4);
}

.deal-chat-msg.is-system .deal-chat-msg-meta {
  text-align: center;
  color: rgba(150, 150, 190, 0.35);
  justify-content: center;
}

.deal-chat-msg-status {
  font-size: 10px;
  line-height: 1;
  letter-spacing: -0.2px;
}

.deal-chat-msg-status--sent {
  color: rgba(170, 186, 224, 0.48);
}

.deal-chat-msg-status--read {
  color: rgba(119, 182, 255, 0.88);
}

/* Sender name (incoming only) */
.deal-chat-msg-sender {
  font-size: 11px;
  font-weight: 700;
  color: rgba(110, 165, 240, 0.7);
  margin-bottom: 2px;
}

.deal-chat-msg-sender.is-link {
  cursor: pointer;
}

/* ── Deal action card (glass, inside .deal-chat-stream) ── */
.deal-chat-actions {
  flex: 0 0 auto;
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 6px;
  padding: 10px 8px;
  margin: 4px 4px 0;
  border-radius: 14px;
  background:
    linear-gradient(135deg, rgba(72, 118, 238, 0.1), rgba(68, 95, 214, 0.06)),
    rgba(25, 35, 70, 0.35);
  border: 1px solid rgba(140, 180, 255, 0.14);
  box-shadow: inset 0 1px 0 rgba(180, 210, 255, 0.06);
  backdrop-filter: blur(6px);
  -webkit-backdrop-filter: blur(6px);
}

/* Hide when all buttons are hidden */
.deal-chat-actions:not(:has(button:not([hidden]))) {
  display: none;
}

.deal-chat-actions .action-btn {
  min-height: 36px;
  font-size: 12px;
  font-weight: 600;
  padding: 7px 6px;
  border-radius: 10px;
  border: 1px solid rgba(140, 180, 255, 0.15);
  background:
    linear-gradient(135deg, rgba(80, 120, 200, 0.12), rgba(60, 90, 170, 0.08)),
    rgba(30, 45, 90, 0.4);
  color: rgba(210, 220, 245, 0.88);
  transition: all 0.15s ease;
  letter-spacing: 0.1px;
}

.deal-chat-actions .action-btn:active:not(:disabled) {
  transform: scale(0.96);
}

.deal-chat-actions .action-btn.primary {
  background:
    linear-gradient(135deg, rgba(50, 120, 240, 0.25), rgba(40, 100, 220, 0.2)),
    rgba(20, 50, 120, 0.4);
  border-color: rgba(80, 160, 255, 0.25);
  color: rgba(170, 215, 255, 0.95);
}

.deal-chat-actions .action-btn:disabled {
  opacity: 0.35;
}

/* ── Inline action card (support/existing compatibility) ── */
.deal-chat-inline-actions {
  align-self: center;
  width: 100%;
  max-width: 320px;
  padding: 12px;
  border-radius: 12px;
  background: rgba(255, 255, 255, 0.04);
  border: 1px solid rgba(255, 255, 255, 0.08);
  margin-top: 4px;
}

.deal-chat-inline-actions-title {
  font-size: 13px;
  font-weight: 600;
  color: rgba(190, 190, 220, 0.8);
  text-align: center;
  margin-bottom: 10px;
}

.deal-chat-inline-actions-btns {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.deal-chat-inline-actions-btns .action-btn {
  width: 100%;
  min-height: 38px;
  font-size: 13px;
  font-weight: 600;
  padding: 8px 12px;
  border-radius: 10px;
  border: 1px solid rgba(255, 255, 255, 0.1);
  background: rgba(255, 255, 255, 0.06);
  color: rgba(210, 210, 240, 0.9);
  transition: all 0.15s ease;
}

.deal-chat-inline-actions-btns .action-btn:active:not(:disabled) {
  transform: scale(0.97);
}

.deal-chat-inline-actions-btns .action-btn.primary {
  background: rgba(0, 120, 240, 0.22);
  border-color: rgba(0, 140, 255, 0.28);
  color: rgba(170, 215, 255, 0.95);
}

.deal-chat-inline-actions-btns .action-btn:disabled {
  opacity: 0.35;
}

.deal-chat-inline-actions-btns .action-btn.danger {
  border-color: rgba(255, 100, 120, 0.2);
  color: rgba(255, 175, 185, 0.85);
  background: rgba(255, 80, 100, 0.06);
}

/* ── Compose ── */
.deal-chat-compose {
  margin-top: 0;
  display: grid;
  grid-template-columns: minmax(0, 1fr) 32px;
  gap: 6px;
  align-items: center;
  position: relative;
  z-index: 2;
}

.deal-chat-reply {
  display: flex;
  align-items: center;
  gap: 8px;
  margin: 0 0 8px;
  padding: 8px 10px;
  border-radius: 12px;
  background: rgba(20, 35, 75, 0.45);
  border: 1px solid rgba(122, 156, 231, 0.28);
}

.deal-chat-reply-accent {
  width: 3px;
  height: 30px;
  border-radius: 2px;
  background: linear-gradient(180deg, rgba(145, 181, 255, 0.95), rgba(103, 148, 255, 0.75));
  flex-shrink: 0;
}

.deal-chat-reply-body {
  min-width: 0;
  flex: 1 1 auto;
}

.deal-chat-reply-name {
  font-size: 11px;
  font-weight: 700;
  color: rgba(171, 204, 255, 0.95);
}

.deal-chat-reply-text {
  margin-top: 1px;
  font-size: 12px;
  line-height: 1.3;
  color: rgba(204, 217, 246, 0.8);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.deal-chat-reply-cancel {
  width: 26px;
  height: 26px;
  border-radius: 8px;
  border: 1px solid rgba(130, 160, 230, 0.25);
  background: rgba(41, 58, 106, 0.55);
  color: rgba(210, 223, 255, 0.85);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-size: 13px;
  cursor: pointer;
}

.deal-chat-reply-cancel:active {
  transform: scale(0.95);
}

.deal-chat-input {
  height: 36px !important;
  min-height: 36px !important;
  max-height: 36px !important;
  border-radius: 16px !important;
  padding: 9px 13px 8px !important;
  font-size: 14px;
  line-height: 18px !important;
  border: 1px solid rgba(140, 180, 255, 0.15) !important;
  background:
    linear-gradient(135deg, rgba(72, 100, 200, 0.08), rgba(60, 80, 160, 0.05)),
    rgba(25, 35, 65, 0.4) !important;
  backdrop-filter: blur(6px);
  -webkit-backdrop-filter: blur(6px);
  resize: none !important;
  overflow-y: hidden !important;
  outline: none !important;
  box-shadow: inset 0 1px 0 rgba(180, 210, 255, 0.05);
  -webkit-appearance: none;
  appearance: none;
  color: rgba(235, 235, 255, 0.93);
  transition: border-color 0.2s ease, box-shadow 0.2s ease;
}

.deal-chat-input::placeholder {
  color: rgba(160, 175, 220, 0.4);
}

.deal-chat-input:focus,
.deal-chat-input:focus-visible {
  outline: none !important;
  border-color: rgba(80, 160, 255, 0.35) !important;
  box-shadow:
    inset 0 1px 0 rgba(180, 210, 255, 0.08),
    0 0 0 3px rgba(60, 130, 255, 0.08);
}

.deal-chat-send-btn {
  width: 32px;
  min-width: 32px;
  height: 32px;
  padding: 0;
  border-radius: 50%;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  background:
    linear-gradient(135deg, rgba(50, 130, 255, 0.7), rgba(40, 100, 230, 0.6)) !important;
  border: 1px solid rgba(100, 170, 255, 0.3) !important;
  box-shadow:
    0 4px 12px rgba(30, 80, 200, 0.25),
    inset 0 1px 0 rgba(180, 220, 255, 0.15);
  color: #fff !important;
  transition: transform 0.15s ease, opacity 0.15s ease;
}

.deal-chat-send-btn:active:not(:disabled) {
  transform: scale(0.88);
  box-shadow:
    0 2px 6px rgba(30, 80, 200, 0.2),
    inset 0 1px 0 rgba(180, 220, 255, 0.15);
}

.deal-chat-send-btn:disabled {
  opacity: 0.3;
}

.deal-chat-send-btn svg {
  width: 12px;
  height: 12px;
}

.deal-chat-footer {
  flex: 0 0 auto;
  min-height: 0;
  display: grid;
