}

/* ── Animations ── */

/* Page slide-in from right (chat open) */
@keyframes chatSlideIn {
  from { opacity: 0; transform: translateX(40px); }
  to   { opacity: 1; transform: translateX(0); }
}

/* Page slide-out to right (chat close) */
@keyframes chatSlideOut {
  from { opacity: 1; transform: translateX(0); }
  to   { opacity: 0; transform: translateX(40px); }
}

/* Conversation item staggered entrance */
@keyframes convItemIn {
  from { opacity: 0; transform: translateY(10px); }
  to   { opacity: 1; transform: translateY(0); }
}

/* Message bubble appear */
@keyframes msgBubbleIn {
  from { opacity: 0; transform: translateY(8px) scale(0.97); }
  to   { opacity: 1; transform: translateY(0) scale(1); }
}

/* Empty state fade */
@keyframes fadeIn {
  from { opacity: 0; }
  to   { opacity: 1; }
}

/* Pinned block slide-down */
@keyframes slideDown {
  from { opacity: 0; transform: translateY(-6px); }
  to   { opacity: 1; transform: translateY(0); }
}

/* Animations only trigger via JS-added .anim-* classes — never on re-render / polling */

/* Chat page entrance — only when JS adds .anim-enter */
.page-deal-chat.anim-enter {
  animation: chatSlideIn 0.22s cubic-bezier(0.25, 0.46, 0.45, 0.94) both;
}

/* Conversation items stagger — only fresh render */
.conversations-item.anim-in {
  animation: convItemIn 0.25s cubic-bezier(0.25, 0.46, 0.45, 0.94) both;
  animation-delay: calc(var(--item-i, 0) * 35ms);
}

/* Cap stagger so large lists don't feel slow */
.conversations-item.anim-in:nth-child(n+15) {
  animation-delay: 0ms;
}

/* Message bubble appear — only new messages */
.deal-chat-msg-row.anim-in {
  animation: msgBubbleIn 0.2s cubic-bezier(0.25, 0.46, 0.45, 0.94) both;
  animation-delay: calc(var(--msg-i, 0) * 18ms);
}

/* Cap stagger */
.deal-chat-msg-row.anim-in:nth-child(n+20) {
  animation-delay: 0ms;
}

/* ── Scrollbar ── */
.deal-chat-messages {
  scrollbar-width: thin;
  scrollbar-color: rgba(140, 120, 200, 0.15) transparent;
}

.deal-chat-messages::-webkit-scrollbar {
  width: 3px;
}

.deal-chat-messages::-webkit-scrollbar-track {
  background: transparent;
}

.deal-chat-messages::-webkit-scrollbar-thumb {
  background: rgba(140, 120, 200, 0.18);
  border-radius: 4px;
}

.conversations-list {
  scrollbar-width: thin;
  scrollbar-color: rgba(140, 120, 200, 0.15) transparent;
}

/* ── Reduced motion ── */
@media (prefers-reduced-motion: reduce) {
  .page-deal-chat.anim-enter,
  .conversations-item.anim-in,
  .deal-chat-msg-row.anim-in {
    animation: none !important;
  }
}

