  border: 1px solid rgba(124, 92, 255, 0.22);
  background: rgba(124, 92, 255, 0.08);
}

.top-scope-label {
  font-size: 12px;
  color: rgba(214, 200, 255, 0.9);
  line-height: 1.25;
}

.top-scope-btn {
  white-space: nowrap;
}

.top-lists {
  display: grid;
  gap: 10px;
  margin-top: 12px;
}

.top-list-card {
  border-radius: 16px;
  border: 1px solid rgba(124, 92, 255, 0.2);
  background: rgba(10, 6, 22, 0.35);
  padding: 10px 12px;
}

.top-list-title {
  font-size: 12px;
  font-weight: 700;
  color: rgba(244, 237, 255, 0.92);
  margin-bottom: 8px;
}

.top-list {
  display: grid;
  gap: 8px;
}

.top-empty {
  font-size: 12px;
  color: rgba(198, 179, 255, 0.72);
  padding: 10px 8px;
  border-radius: 12px;
  border: 1px dashed rgba(124, 92, 255, 0.28);
  background: rgba(124, 92, 255, 0.06);
}

.top-row {
  display: grid;
  grid-template-columns: 26px 1fr auto;
  align-items: center;
  gap: 10px;
  padding: 10px 10px;
  border-radius: 14px;
  border: 1px solid rgba(124, 92, 255, 0.26);
  background: linear-gradient(135deg, rgba(124, 92, 255, 0.12), rgba(255, 205, 140, 0.06));
}

.top-row.is-queue {
  border-color: rgba(124, 92, 255, 0.25);
  background: rgba(124, 92, 255, 0.10);
}

.top-rank {
  width: 26px;
  height: 26px;
  border-radius: 10px;
  display: grid;
  place-items: center;
  font-size: 12px;
  font-weight: 800;
  color: rgba(244, 237, 255, 0.95);
  background: rgba(124, 92, 255, 0.14);
  border: 1px solid rgba(124, 92, 255, 0.28);
}

.top-row.is-queue .top-rank {
  color: rgba(214, 200, 255, 0.95);
  background: rgba(124, 92, 255, 0.14);
  border-color: rgba(124, 92, 255, 0.28);
}

.top-row-main {
  min-width: 0;
}

.top-row-title {
  font-size: 13px;
  font-weight: 650;
  color: rgba(244, 237, 255, 0.95);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.top-row-meta {
  margin-top: 3px;
  font-size: 11px;
  color: rgba(198, 179, 255, 0.78);
  font-variant-numeric: tabular-nums;
}

.top-open {
  border-radius: 12px;
  border: 1px solid rgba(124, 92, 255, 0.35);
  background: rgba(124, 92, 255, 0.12);
  color: rgba(244, 237, 255, 0.95);
  padding: 7px 10px;
  font-size: 12px;
  cursor: pointer;
}

.top-open:hover {
  background: rgba(124, 92, 255, 0.18);
}

.top-badge {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 2px 8px;
  border-radius: 999px;
  background: linear-gradient(135deg, rgba(255, 205, 140, 0.16), rgba(124, 92, 255, 0.12));
  border: 1px solid rgba(255, 205, 140, 0.28);
  color: rgba(255, 242, 220, 0.92);
  font-size: 11px;
  font-weight: 600;
  font-variant-numeric: tabular-nums;
  box-shadow: 0 0 12px rgba(124, 92, 255, 0.16);
}

.top-badge::before {
  content: "";
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: radial-gradient(circle, rgba(255, 245, 220, 0.95) 0%, rgba(255, 205, 140, 0.8) 60%, rgba(255, 205, 140, 0.1) 100%);
  box-shadow: 0 0 6px rgba(124, 92, 255, 0.45);
}

.top-scope-btn {
  border-radius: 14px;
  border: 1px solid rgba(124, 92, 255, 0.32);
  background: rgba(12, 7, 24, 0.55);
  color: rgba(244, 237, 255, 0.95);
}

.top-scope-btn:active {
  transform: scale(0.98);
}

.settings-list {
  display: grid;
  gap: 10px;
  margin-top: 16px;
}

.settings-item {
  position: relative;
  border: 1px solid rgba(255, 255, 255, 0.08);
  background: rgba(255, 255, 255, 0.04);
  color: #fff;
  border-radius: 16px;
  padding: 14px 18px;
  text-align: left;
  font-size: 14px;
  font-weight: 500;
  cursor: pointer;
  transition: all 180ms ease;
  overflow: hidden;
}

.settings-item::before {
  content: "";
  position: absolute;
  inset: 0;
  background: linear-gradient(135deg, rgba(124, 92, 255, 0.15) 0%, transparent 50%);
  opacity: 0;
  transition: opacity 200ms ease;
}

.settings-item:hover::before,
.settings-item:active::before {
  opacity: 1;
}

.settings-item:active {
  transform: scale(0.98);
  background: rgba(255, 255, 255, 0.06);
}

.settings-item--support {
  font-weight: 700;
  letter-spacing: 0.01em;
}

.settings-item--switch {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
}

.settings-item-state {
  min-width: 52px;
  text-align: center;
  padding: 5px 10px;
  border-radius: 999px;
  font-size: 12px;
  font-weight: 700;
  color: rgba(225, 213, 255, 0.95);
  border: 1px solid rgba(255, 255, 255, 0.14);
  background: rgba(255, 255, 255, 0.06);
}

.settings-item--switch.is-active .settings-item-state {
  color: rgba(233, 244, 255, 0.98);
  border-color: rgba(126, 176, 255, 0.44);
  background: linear-gradient(135deg, rgba(79, 140, 255, 0.30), rgba(35, 80, 170, 0.34));
  box-shadow: 0 0 0 2px rgba(79, 140, 255, 0.14);
}

#settingsModal .modal-card {
  padding: 24px;
  gap: 0;
}

#settingsModal .section-title {
  font-size: 18px;
  font-weight: 600;
  letter-spacing: -0.2px;
  margin-bottom: 4px;
}

.server-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 8px;
}

.server-grid.compact {
  grid-template-columns: repeat(3, minmax(0, 1fr));
}

#serverModal .modal-card {
  max-height: calc(100vh - 40px);
  display: flex;
  flex-direction: column;
}

#serverModal .server-grid {
  overflow-y: auto;
  padding-right: 4px;
  max-height: calc(100vh - 140px);
  -webkit-overflow-scrolling: touch;
}

.server-btn {
  padding: 8px 10px;
  border-radius: 12px;
  border: 1px solid rgba(122, 60, 255, 0.35);
  background: rgba(122, 60, 255, 0.12);
  color: #fff;
  font-size: 11px;
  cursor: pointer;
}

.server-btn.active {
  background: linear-gradient(135deg, #7a3cff, #a86bff);
  border-color: transparent;
}

@keyframes fadeUp {
  from {
    opacity: 0;
    transform: translateY(16px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@keyframes float {
  0%,
  100% {
    transform: translateY(0);
  }
  50% {
    transform: translateY(18px);
  }
}

@keyframes photoIn {
  from {
    opacity: 0;
    transform: scale(0.95);
  }
  to {
    opacity: 1;
    transform: scale(1);
  }
}

@keyframes photoOut {
  to {
    opacity: 0;
    transform: scale(0.95);
  }
}

@keyframes detailIn {
  from {
    opacity: 0;
    transform: translateY(12px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@media (max-width: 480px) {
  .card {
    padding: 16px;
  }

  .identity-card {
    grid-template-columns: 64px minmax(0, 1fr) auto;
    align-items: center;
    gap: 12px;
  }

  .avatar {
    width: 64px;
    height: 64px;
  }

  .identity-info .profile-name {
    font-size: 18px;
  }

  .handle {
    font-size: 12px;
  }

  .role-badge {
    padding: 6px 10px;
    font-size: 10px;
  }

  .report-btn {
    justify-self: end;
  }

  .identity-side {
    justify-items: end;
    gap: 8px;
    align-self: center;
  }

  .coin-wallet {
    gap: 10px;
  }

  .action-bar.action-bar--legacy {
    width: min(304px, calc(100% - 24px));
    gap: 8px;
    padding: 10px 8px;
    bottom: calc(16px + env(safe-area-inset-bottom));
  }

  .action-bar.action-bar--legacy.has-admin {
    width: min(352px, calc(100% - 24px));
  }

  .action-bar--legacy .nav-btn {
    width: 54px;
    height: 54px;
    border-radius: 18px;
  }

  .action-bar--legacy .nav-btn.active {
    transform: translateY(-6px) scale(1.08);
  }

  .action-bar--legacy .nav-btn.active::after {
    bottom: -12px;
    width: 5px;
    height: 5px;
  }

  .action-bar--legacy .nav-btn .nav-icon {
    width: 24px;
    height: 24px;
  }

  .action-bar--legacy .nav-btn .nav-icon--coin {
    width: 28px;
    height: 28px;
  }

  .filter-grid {
    grid-template-columns: 1fr;
  }

  .server-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }


  .shell {
    max-width: 520px;
    padding: 0;
  }

  .stats-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 10px;
  }

  .card {
    padding: 12px;
    border-radius: 16px;
  }

  .avatar {
    width: 56px;
    height: 56px;
    font-size: 18px;
    box-shadow: 0 0 14px rgba(122, 60, 255, 0.6);
  }

  .identity-info .profile-name {
    font-size: 16px;
  }

  .role-badge {
    padding: 6px 10px;
    font-size: 10px;
  }

  .pill-group {
    display: flex;
    gap: 8px;
    overflow-x: auto;
    -webkit-overflow-scrolling: touch;
    padding-bottom: 6px;
  }

  .pill {
    flex: 0 0 auto;
    padding: 8px 12px;
    font-size: 13px;
  }

  .stats-card .stat-item {
    padding: 12px;
  }

  .fab {
    right: 14px;
    bottom: calc(var(--bottom-nav-height) + 16px + env(safe-area-inset-bottom));
  }

  .leaderboard-fab {
    left: 10px;
    min-width: 112px;
    height: 42px;
    padding: 0 12px;
  }

  .leaderboard-fab-crown {
    font-size: 16px;
  }

  .leaderboard-fab-text {
    font-size: 10px;
  }

  .action-bar.action-bar--legacy {
    padding: 10px 8px;
    gap: 8px;
  }

  .action-bar--legacy .nav-btn {
    width: 54px;
    height: 54px;
    border-radius: 16px;
  }

  .action-bar--legacy .nav-btn.active {
    transform: translateY(-5px) scale(1.06);
  }

  .modal-card {
    padding: 14px;
    width: calc(100% - 32px);
  }

  #settingsModal .modal-actions {
    margin-top: 16px;
  }

  #settingsModal .modal-actions .action-btn {
    width: 100%;
    max-width: 320px;
    margin: 0 auto;
  }

}

