/* ===== Support chat, moderator side ===== */
.support-admin-bar {
  padding: 4px 0 2px;
}

.support-admin-bar[hidden],
.support-admin-templates[hidden] {
  display: none;
}

.support-admin-actions {
  display: grid;
  grid-template-columns: 1.3fr 1fr;
  gap: 8px;
}

.support-admin-actions .action-btn {
  min-height: 44px;
  border-radius: 14px;
  font-size: 14px;
  font-weight: 700;
}

.support-admin-actions .action-btn:not(.primary) {
  border: 1px solid rgba(255, 91, 143, 0.32);
  background: rgba(255, 91, 143, 0.12);
  color: #ff8fb0;
  box-shadow: none;
}

.support-admin-templates {
  display: flex;
  gap: 6px;
  padding: 6px 2px 8px;
