  scrollbar-width: none;
}

.support-admin-templates::-webkit-scrollbar {
  display: none;
}


/* ===== Support chat: no jumps on entering ===== */
/* breathing room between the avatar row and the request steps / status */
.deal-chat--support .deal-chat-support-status {
  margin-top: 10px;
}

.support-steps {
  padding-left: 2px;
}

/* the loading placeholder is a quiet line, not a boxed card */
.deal-chat--support .deal-chat-empty {
  border: 0;
  background-color: transparent;
  box-shadow: none;
}

/* whatever appears after the first answer fades in instead of popping */
@keyframes supportFadeIn {
  from { opacity: 0; transform: translateY(4px); }
  to { opacity: 1; transform: none; }
}

.deal-chat--support .support-steps:not([hidden]),
.deal-chat--support .deal-chat-support-topics:not(.hidden),
.deal-chat--support .support-admin-bar:not([hidden]) {
  animation: supportFadeIn 200ms ease-out both;
}

html.android-lite .deal-chat--support .support-steps:not([hidden]),
html.android-lite .deal-chat--support .deal-chat-support-topics:not(.hidden),
html.android-lite .deal-chat--support .support-admin-bar:not([hidden]) {
  animation: none;
}

/* ===== Chats, Telegram-style: doodle wallpaper, compact bubbles with inline time, tails, quote bar ===== */
/* The wallpaper belongs to the whole dialog page (edge to edge, behind header, messages and composer), not to the message stream */
.page-deal-chat.active {
  position: relative;
  background: radial-gradient(120% 60% at 50% 0%, rgba(36, 20, 71, 0.55) 0%, rgba(18, 10, 40, 0.45) 55%, rgba(10, 6, 24, 0.4) 100%);
