  background-image: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' width='120' height='120' viewBox='0 0 120 120' fill='none' stroke='%237c5cff' stroke-opacity='.18' stroke-width='1.6' stroke-linecap='round' stroke-linejoin='round'><path d='M10 16h7l5 22h26l5-16H20'/><circle cx='26' cy='47' r='3'/><circle cx='44' cy='47' r='3'/><path d='M74 12h20l14 14-20 20-20-20z'/><circle cx='85' cy='23' r='2.5'/><rect x='12' y='76' width='26' height='24' rx='5'/><path d='M19 76v-5a6 6 0 0 1 12 0v5'/><circle cx='84' cy='90' r='11'/><path d='M84 83v14M80 86h6a3 3 0 0 1 0 6h-6'/><path d='M56 58l2 5 5 2-5 2-2 5-2-5-5-2 5-2z'/><path d='M52 100q8-8 16 0'/></svg>");
  background-size: 120px 120px;
}

.page-deal-chat.active > .deal-chat-page {
