  border-radius: 21px !important;
  padding: 11px 16px 10px !important;
  border: 1px solid rgba(124, 92, 255, 0.22) !important;
  background: rgba(30, 18, 55, 0.8) !important;
  color: #f4eeff;
  backdrop-filter: none;
  -webkit-backdrop-filter: none;
  box-shadow: none;
}

.deal-chat-input:focus,
.deal-chat-input:focus-visible {
  border-color: rgba(167, 139, 250, 0.55) !important;
  box-shadow: 0 0 0 3px rgba(124, 92, 255, 0.14);
}

.deal-chat-send-btn,
.deal-chat--support .action-btn.primary.deal-chat-send-btn {
  width: 42px;
  min-width: 42px;
  height: 42px;
  background: linear-gradient(180deg, #8b5cf6, #6d28d9) !important;
  border: 0 !important;
  border-radius: 50%;
  box-shadow: 0 4px 12px rgba(109, 40, 217, 0.35);
}

.deal-chat-send-btn svg {
  width: 16px;
  height: 16px;
}

.deal-chat-reply {
  background: rgba(30, 18, 55, 0.8);
  border: 0;
  border-radius: 14px;
}

.deal-chat-reply-accent {
  background: linear-gradient(180deg, #c9b6ff, #8b5cf6);
}

.deal-chat-reply-name {
  color: #c9b6ff;
}

.deal-chat-reply-cancel {
  border-color: rgba(124, 92, 255, 0.3);
  background: rgba(124, 92, 255, 0.18);
}

/* "jump to latest" button with unread counter */
.deal-chat-stream > .deal-chat-jump {
  position: absolute;
  right: 12px;
  bottom: 12px;
  z-index: 3;
  width: 42px;
  height: 42px;
  padding: 0;
  border-radius: 50%;
  border: 1px solid rgba(124, 92, 255, 0.4);
  background: rgba(30, 18, 55, 0.94);
  color: #e6dbff;
  display: grid;
  place-items: center;
  box-shadow: 0 4px 14px rgba(0, 0, 0, 0.4);
  opacity: 0;
  transform: translateY(8px);
  pointer-events: none;
  transition: opacity 0.18s ease, transform 0.18s ease;
}

.deal-chat-stream > .deal-chat-jump[hidden] {
  display: none;
}

.deal-chat-stream > .deal-chat-jump.is-visible {
  opacity: 1;
  transform: none;
  pointer-events: auto;
}

.deal-chat-jump svg {
  width: 18px;
  height: 18px;
}

.deal-chat-jump-badge {
  position: absolute;
  top: -8px;
  right: -4px;
  min-width: 20px;
  height: 20px;
  padding: 0 5px;
  border-radius: 10px;
  background: linear-gradient(180deg, #8b5cf6, #6d28d9);
  color: #fff;
  font-size: 11px;
  font-weight: 700;
  line-height: 20px;
  text-align: center;
}

.deal-chat-jump-badge[hidden] {
  display: none;
}

/* support: same bubbles (the generic rules above already match the violet palette) */
.deal-chat--support .deal-chat-msg {
  background: rgba(40, 26, 76, 0.92);
  border: 0;
}

.deal-chat--support .deal-chat-msg.is-me {
  background: linear-gradient(180deg, #8b5cf6, #6d28d9);
}

.deal-chat--support .deal-chat-msg.is-system {
  background: rgba(124, 92, 255, 0.14);
  border: 0;
}

html.android-lite .page-deal-chat.active::before {
  opacity: 0.4;
}

html.android-lite .deal-chat-stream > .deal-chat-jump {
  transition: none;
}

/* few messages sit at the bottom, next to the composer (auto margin collapses once the list overflows) */
.deal-chat-messages > :first-child {
  margin-top: auto;
}

.deal-chat-messages > .deal-chat-empty:first-child {
  margin-top: 32px;
}


/* ===== Chats list, Telegram-style: flat rows, big avatar, accent listing line, badge on the message line ===== */
.conversations-item {
  gap: 12px;
  padding: 9px 16px;
}

.conversations-item-avatar {
  width: 56px;
  height: 56px;
  font-size: 21px;
}

.conversations-item-body {
  gap: 1px;
  padding: 2px 0 9px;
  border-bottom: 1px solid rgba(124, 92, 255, 0.12);
}

.conversations-item-top {
  align-items: center;
}

.conversations-item-title {
  display: flex;
  align-items: center;
  gap: 5px;
  font-size: 16.5px;
  font-weight: 700;
  color: #f4eeff;
}

.conversations-item-time {
  font-size: 13px;
  color: #8c80b3;
}

.conversations-item-time--unread {
  color: #a78bfa;
}

.conversations-item-context {
  font-size: 13.5px;
  color: #a78bfa;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.conversations-item-line {
  display: flex;
  align-items: flex-start;
  gap: 8px;
}

.conversations-item-message {
  flex: 1;
  min-width: 0;
  font-size: 15px;
  color: #a79bc9;
  -webkit-line-clamp: 2;
  max-height: 2.8em;
}

.conversations-item--unread .conversations-item-message {
  color: #d9ccff;
}

.conversations-item-unread {
  flex: none;
  min-width: 22px;
  height: 22px;
  padding: 0 7px;
  margin-top: 2px;
  border: 0;
  border-radius: 11px;
  background: linear-gradient(180deg, #8b5cf6, #6d28d9);
  color: #fff;
  font-size: 13px;
  font-weight: 700;
}

.conversations-item-pin {
  flex: none;
  width: 16px;
  height: 16px;
  margin-top: 4px;
  color: #7d70a8;
}

.conversations-item-pin svg {
  width: 100%;
  height: 100%;
}

.conversations-item-verified {
  display: inline-flex;
  flex: none;
  width: 18px;
  height: 18px;
  color: #8b5cf6;
}

.conversations-item-verified svg {
  width: 100%;
  height: 100%;
}

.conversations-item-avatar--system {
  background: linear-gradient(135deg, #8b5cf6, #5b21b6);
  font-size: 19px;
  font-weight: 800;
  letter-spacing: 0.02em;
}

.conversations-item.conversations-item--system .conversations-item-title,
.conversations-item.conversations-item--support .conversations-item-title,
.conversations-item.conversations-item--server .conversations-item-title {
  color: #f4eeff;
}

.conversations-item.conversations-item--system .conversations-item-message,
.conversations-item.conversations-item--support .conversations-item-message,
.conversations-item.conversations-item--server .conversations-item-message {
  color: #a79bc9;
}

/* notifications live in the «RP Market» row of the list now; the bell stays only in the desktop top bar */
body:not(.web-desktop) .conversations-inbox-btn {
  display: none;
}

/* delivery marks: thin Telegram-like checks instead of text glyphs (one = sent, two = read) */
.deal-chat-msg-status {
  display: inline-flex;
  align-items: center;
  width: 17px;
  height: 11px;
  letter-spacing: 0;
}

.deal-chat-msg-status svg {
  width: 100%;
  height: 100%;
}

.deal-chat-msg-status--sent {
  color: rgba(255, 255, 255, 0.6);
}

.deal-chat-msg-status--read {
  color: #fff;
}

/* RP Market system dialog: the cart logo fills the round avatar (header, chat list, bubbles) */
.deal-chat-avatar.deal-chat-avatar--market { background: #140b30; }
.deal-chat-avatar.deal-chat-avatar--market img { object-fit: cover; padding: 0; border-radius: 50%; }
.conversations-item-avatar--system { background: #140b30 !important; padding: 0; overflow: hidden; }
.conversations-item-avatar--system img { width: 100%; height: 100%; display: block; object-fit: cover; }
.deal-chat-msg-ava.deal-chat-msg-ava--market { background: #140b30 url("/assets/logo/market-cart.png") center / cover no-repeat; font-size: 0; }


/* server chat: bigger avatar with the player level in a small badge, role chip next to the name */
.deal-chat-msg-ava.deal-chat-msg-ava--lg {
  width: 30px;
  height: 30px;
  min-width: 30px;
  overflow: visible;
}
.deal-chat-msg-ava[data-level]::after {
  content: attr(data-level);
  position: absolute;
  right: -4px;
  bottom: -4px;
  min-width: 15px;
  height: 15px;
  padding: 0 3px;
  box-sizing: border-box;
  border-radius: 8px;
  border: 1.5px solid #150f2a;
  background: #3b2f78;
  color: #fff;
  font-size: 9px;
  font-weight: 800;
  line-height: 12px;
  text-align: center;
  text-transform: none;
}
.deal-chat-msg-ava[data-tier="teal"]::after { background: #0f8f86; }
.deal-chat-msg-ava[data-tier="violet"]::after { background: #6d4ae0; }
.deal-chat-msg-ava[data-tier="gold"]::after { background: #c98a12; }
.deal-chat-msg-ava.deal-chat-msg-ava--lg { position: relative; }

.deal-chat-msg-staff {
  display: inline-block;
  margin-left: 6px;
  padding: 1px 5px;
  border-radius: 5px;
  font-size: 8.5px;
  font-weight: 800;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  vertical-align: 1px;
  color: #fff;
  background: #0f8f86;
}
.deal-chat-msg-staff[data-role="moderator"] { background: #1f8fd6; }
.deal-chat-msg-staff[data-role="head_moderator"] { background: #3a5fe0; }
.deal-chat-msg-staff[data-role="cofounder"] { background: #d0453a; }
.deal-chat-msg-staff[data-role="developer"] { background: #6d4ae0; }


/* moderators: «Сервер NN ▾» in the chat header and the side drawer with every server chat */
.deal-chat-server-switch {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  height: 32px;
  margin-right: 6px;
  padding: 0 10px;
  border: none;
  border-radius: 16px;
  background: rgba(124, 92, 255, 0.28);
  color: #fff;
  font-size: 13px;
  font-weight: 800;
  flex-shrink: 0;
}
.deal-chat-server-switch:active { transform: scale(0.96); }

.server-drawer-backdrop {
  position: fixed;
  inset: 0;
  z-index: 1210;
  background: rgba(8, 5, 22, 0.5);
  -webkit-backdrop-filter: blur(4px);
  backdrop-filter: blur(4px);
  opacity: 0;
  transition: opacity 0.22s ease;
}
.server-drawer-backdrop.is-open { opacity: 1; }
.server-drawer {
  position: fixed;
  top: 0;
  bottom: 0;
  left: 0;
  z-index: 1211;
  width: min(330px, 86vw);
  display: flex;
  flex-direction: column;
  /* below the Telegram header (Назад / ⌄ / ⋯ are drawn over the web view) */
  padding: calc(var(--tg-safe-top-offset, env(safe-area-inset-top, 0px)) + 14px) 12px calc(env(safe-area-inset-bottom, 0px) + 12px);
  background: linear-gradient(180deg, #1d1540 0%, #140e2e 100%);
  border-right: 1px solid rgba(160, 140, 255, 0.2);
  box-shadow: 10px 0 40px rgba(4, 2, 16, 0.55);
  transform: translateX(-102%);
  transition: transform 0.26s cubic-bezier(0.2, 0.85, 0.3, 1);
}
.server-drawer.is-open { transform: none; }
.server-drawer-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 2px 4px 10px;
}
.server-drawer-title { font-size: 17px; font-weight: 800; color: #fff; }
.server-drawer-close {
  width: 32px;
  height: 32px;
  border: none;
  border-radius: 16px;
  background: rgba(255, 255, 255, 0.08);
  color: #fff;
  font-size: 20px;
  line-height: 1;
}
.server-drawer-search {
  width: 100%;
  box-sizing: border-box;
  margin-bottom: 10px;
  padding: 10px 14px;
  border: none;
  border-radius: 12px;
  background: rgba(255, 255, 255, 0.07);
  color: #fff;
  font-size: 14px;
}
.server-drawer-list {
  flex: 1;
  overflow-y: auto;
  -webkit-overflow-scrolling: touch;
  display: flex;
  flex-direction: column;
  gap: 4px;
}
.server-drawer-row {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 8px 8px;
  border: none;
  border-radius: 14px;
  background: transparent;
  text-align: left;
  color: inherit;
  transition: background 0.14s ease;
}
.server-drawer-row:hover { background: rgba(255, 255, 255, 0.05); }
.server-drawer-row.is-current { background: rgba(124, 92, 255, 0.26); }
.server-drawer-cover {
  position: relative;
  width: 46px;
  height: 46px;
  flex-shrink: 0;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  container-type: size;
  background: linear-gradient(145deg, hsl(var(--server-hue, 170) 68% 56%), hsl(calc(var(--server-hue, 170) + 28) 60% 32%));
}
.server-drawer-body { min-width: 0; flex: 1; }
.server-drawer-name { font-size: 15px; font-weight: 700; color: #fff; display: flex; align-items: center; gap: 6px; }
.server-drawer-mine {
  padding: 1px 6px;
  border-radius: 6px;
  background: rgba(124, 92, 255, 0.5);
  font-size: 9px;
  font-weight: 800;
  letter-spacing: 0.05em;
  text-transform: uppercase;
}
.server-drawer-last {
  margin-top: 2px;
  font-size: 12.5px;
  color: rgba(200, 192, 235, 0.65);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.server-drawer-empty { padding: 24px 8px; text-align: center; color: rgba(200, 192, 235, 0.55); font-size: 14px; }


/* own confirm dialog */
.rp-confirm-overlay {
  position: fixed;
  inset: 0;
  z-index: 1300;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 24px;
  background: rgba(8, 5, 22, 0.55);
  -webkit-backdrop-filter: blur(5px);
  backdrop-filter: blur(5px);
  opacity: 0;
  transition: opacity 0.18s ease;
}
.rp-confirm-overlay.is-open { opacity: 1; }
.rp-confirm {
  width: min(320px, 100%);
  padding: 20px 18px 14px;
  border-radius: 20px;
  background: #221a4a;
  border: 1px solid rgba(160, 140, 255, 0.22);
  box-shadow: 0 18px 50px rgba(4, 2, 16, 0.6);
  transform: scale(0.94);
  transition: transform 0.2s cubic-bezier(0.2, 0.9, 0.3, 1.15);
}
.rp-confirm-overlay.is-open .rp-confirm { transform: none; }
.rp-confirm-title { font-size: 17px; font-weight: 800; color: #fff; }
.rp-confirm-text { margin-top: 6px; font-size: 14px; line-height: 1.35; color: rgba(215, 208, 245, 0.8); }
.rp-confirm-actions { display: flex; gap: 8px; margin-top: 16px; }
.rp-confirm-actions button {
  flex: 1;
  height: 44px;
  border: none;
  border-radius: 12px;
  font-size: 15px;
  font-weight: 700;
}
.rp-confirm-cancel { background: rgba(255, 255, 255, 0.09); color: #fff; }
.rp-confirm-ok { background: #e5484d; color: #fff; }


/* server chat header: avatar left, name and subtitle centred (the moderator switch floats on the right and does not shift the centre) */
.deal-chat-header.deal-chat-header--server {
  position: relative;
  grid-template-columns: 46px minmax(0, 1fr) 46px;
}
.deal-chat-header--server .deal-chat-header-media { display: contents; }
.deal-chat-header--server .deal-chat-header-main { text-align: center; justify-items: center; grid-column: 2; }
.deal-chat-header--server .deal-chat-avatar { grid-column: 1; }
.deal-chat-header--server .deal-chat-title { max-width: 100%; }
.deal-chat-header--server .deal-chat-server-switch {
  position: absolute;
  right: 0;
  top: 50%;
  margin: 0;
  transform: translateY(-50%);
}
.deal-chat-header--server .deal-chat-server-switch:active { transform: translateY(-50%) scale(0.96); }
.deal-chat-header--server .deal-chat-report-btn { display: none; }

.deal-chat-msg-ava.is-link { cursor: pointer; -webkit-tap-highlight-color: transparent; }
.deal-chat-msg-ava.is-link:active { transform: scale(0.92); }


/* paperclip next to the input of a server chat */
.deal-chat-compose.deal-chat-compose--attach { grid-template-columns: 42px minmax(0, 1fr) 42px; }
.deal-chat-attach-btn {
  width: 42px;
  height: 42px;
  padding: 0;
  border: 1px solid rgba(124, 92, 255, 0.22);
  border-radius: 50%;
  background: rgba(30, 18, 55, 0.8);
  color: rgba(225, 215, 255, 0.92);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  transition: transform 0.12s ease, background 0.12s ease;
}
.deal-chat-attach-btn:active { transform: scale(0.92); background: rgba(124, 92, 255, 0.3); }
.deal-chat-attach-btn.hidden { display: none; }

/* listing card inside a message */
.deal-chat-listing-card {
  display: flex;
  gap: 10px;
  align-items: stretch;
  min-width: 220px;
  padding: 6px;
  border-radius: 14px;
  background: rgba(255, 255, 255, 0.07);
  cursor: pointer;
}
.deal-chat-listing-card.is-gone { min-width: 0; padding: 10px 12px; cursor: default; color: rgba(215, 208, 245, 0.55); font-size: 14px; font-style: italic; }
.deal-chat-listing-card-thumb {
  width: 64px;
  min-height: 64px;
  flex-shrink: 0;
  border-radius: 10px;
  background: rgba(255, 255, 255, 0.06) center / cover no-repeat;
}
.deal-chat-listing-card-body { min-width: 0; display: flex; flex-direction: column; justify-content: center; gap: 2px; }
.deal-chat-listing-card-title { font-size: 14px; font-weight: 700; line-height: 1.25; color: #fff; display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden; }
.deal-chat-listing-card-meta { font-size: 12.5px; color: rgba(225, 215, 255, 0.75); }
.deal-chat-listing-card-open { margin-top: 3px; font-size: 12px; font-weight: 800; color: #b9a6ff; }

/* listing picker */
.listing-pick-overlay {
  position: fixed;
  inset: 0;
  z-index: 1250;
  display: flex;
  align-items: flex-end;
  background: rgba(8, 5, 22, 0.55);
  -webkit-backdrop-filter: blur(4px);
  backdrop-filter: blur(4px);
  opacity: 0;
  transition: opacity 0.2s ease;
}
.listing-pick-overlay.is-open { opacity: 1; }
.listing-pick-sheet {
  width: 100%;
  max-height: 70vh;
  display: flex;
  flex-direction: column;
  padding: 14px 12px calc(env(safe-area-inset-bottom, 0px) + 12px);
  border-radius: 22px 22px 0 0;
  background: linear-gradient(180deg, #1f1745 0%, #150f31 100%);
  border-top: 1px solid rgba(160, 140, 255, 0.22);
  transform: translateY(28px);
  transition: transform 0.26s cubic-bezier(0.2, 0.85, 0.3, 1);
}
.listing-pick-overlay.is-open .listing-pick-sheet { transform: none; }
.listing-pick-head { display: flex; align-items: center; justify-content: space-between; padding: 0 4px 10px; }
.listing-pick-title { font-size: 17px; font-weight: 800; color: #fff; }
.listing-pick-close { width: 32px; height: 32px; border: none; border-radius: 16px; background: rgba(255, 255, 255, 0.08); color: #fff; font-size: 20px; line-height: 1; }
.listing-pick-list { overflow-y: auto; -webkit-overflow-scrolling: touch; display: flex; flex-direction: column; gap: 6px; }
.listing-pick-row {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 8px;
  border: none;
  border-radius: 14px;
  background: rgba(255, 255, 255, 0.05);
  text-align: left;
  color: inherit;
}
.listing-pick-row:active { background: rgba(124, 92, 255, 0.25); }
.listing-pick-thumb { width: 54px; height: 54px; flex-shrink: 0; border-radius: 10px; background: rgba(255, 255, 255, 0.06) center / cover no-repeat; }
.listing-pick-body { min-width: 0; display: flex; flex-direction: column; gap: 3px; }
.listing-pick-name { font-size: 15px; font-weight: 700; color: #fff; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.listing-pick-meta { font-size: 13px; color: rgba(225, 215, 255, 0.7); }
.listing-pick-empty { padding: 28px 12px; text-align: center; color: rgba(215, 208, 245, 0.6); font-size: 14px; line-height: 1.45; }


/* cards that open a floating menu on hold: no native image / text callout */
.market-card[data-listing-id] {
  -webkit-touch-callout: none;
  -webkit-user-select: none;
  user-select: none;
}
.market-card[data-listing-id] img { -webkit-user-drag: none; }

.deal-chat-listing-card-thumb.is-cover,
.listing-pick-thumb.is-cover { background-size: 78%; background-repeat: no-repeat; }


/* a long quoted text in the reply bar must never widen the footer / push the input off screen */
.deal-chat-footer,
.deal-chat-reply,
.deal-chat-compose {
  min-width: 0;
  max-width: 100%;
  box-sizing: border-box;
}
.deal-chat-reply-body { overflow: hidden; }
.deal-chat-reply-name,
.deal-chat-reply-text { max-width: 100%; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }


/* dice duel card in the chat */
.deal-chat-duel-card {
  min-width: 250px;
  padding: 10px 12px 12px;
  border-radius: 16px;
  background: linear-gradient(160deg, rgba(124, 92, 255, 0.28), rgba(32, 20, 70, 0.55));
  border: 1px solid rgba(160, 140, 255, 0.28);
}
.deal-chat-duel-card.is-cancelled,
.deal-chat-duel-card.is-expired { opacity: 0.65; }
.deal-chat-duel-head { display: flex; align-items: center; justify-content: space-between; gap: 10px; margin-bottom: 8px; }
.deal-chat-duel-title { font-size: 13px; font-weight: 800; letter-spacing: 0.02em; color: #d8ccff; }
.deal-chat-duel-stake { font-size: 14px; font-weight: 800; color: #fff; padding: 2px 9px; border-radius: 10px; background: rgba(255, 255, 255, 0.1); }
.deal-chat-duel-players { display: flex; align-items: center; justify-content: space-between; gap: 6px; }
.deal-chat-duel-name { max-width: 100%; font-size: 12.5px; font-weight: 700; color: rgba(235, 230, 255, 0.9); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.deal-chat-duel-vs { font-size: 12px; font-weight: 800; color: rgba(215, 205, 255, 0.6); }
.deal-chat-duel-foot { margin-top: 8px; display: flex; flex-direction: column; gap: 8px; }
.deal-chat-duel-info,
.deal-chat-duel-result { font-size: 13px; font-weight: 600; text-align: center; color: rgba(235, 230, 255, 0.85); }
.deal-chat-duel-btn { height: 40px; border: 0; border-radius: 12px; background: rgba(255, 255, 255, 0.1); color: #fff; font-size: 14px; font-weight: 700; }
.deal-chat-duel-btn.is-primary { background: linear-gradient(180deg, #8b5cf6, #6d28d9); }
.deal-chat-duel-btn:active { transform: scale(0.97); }
.deal-chat-duel-btn:disabled { opacity: 0.6; }

/* duel sheet (bottom sheet reuses the listing picker shell) */
.duel-sheet-note { padding: 0 4px 10px; font-size: 13px; line-height: 1.4; color: rgba(215, 208, 245, 0.75); }
.duel-sheet-chips { display: flex; gap: 8px; flex-wrap: wrap; padding: 0 4px 10px; }
.duel-chip { height: 38px; padding: 0 16px; border: 0; border-radius: 19px; background: rgba(255, 255, 255, 0.08); color: #fff; font-size: 15px; font-weight: 700; }
.duel-chip.is-active { background: rgba(124, 92, 255, 0.55); box-shadow: inset 0 0 0 1.5px rgba(190, 170, 255, 0.8); }
.duel-sheet-input { width: calc(100% - 8px); margin: 0 4px 8px; box-sizing: border-box; height: 46px; padding: 0 14px; border: 0; border-radius: 14px; background: rgba(255, 255, 255, 0.07); color: #fff; font-size: 18px; font-weight: 700; }
.duel-sheet-win { padding: 0 4px 12px; font-size: 13.5px; font-weight: 600; color: #b9a6ff; }
