/* dice duel: the 2D die, calm landing, no layout jumps */
.deal-chat-duel-players { align-items: flex-start; gap: 4px; padding-top: 6px; }
.deal-chat-duel-vs { align-self: flex-start; margin-top: 35px; }
.deal-chat-duel-side { position: relative; flex: 1; min-width: 0; display: flex; flex-direction: column; align-items: center; gap: 10px; padding: 0; }
.deal-chat-duel-name { margin-top: 2px; }
.deal-chat-duel-foot { min-height: 66px; justify-content: center; margin-top: 12px; }  /* open and finished cards have the same height: nothing jumps when the dice land */
.deal-chat-duel-result {
  align-self: center;
  max-width: 100%;
  box-sizing: border-box;
  padding: 8px 12px;
  border-radius: 14px;
  background: rgba(255, 255, 255, 0.09);
  font-size: 13px;
  font-weight: 800;
  color: #fff;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  opacity: 1;
  transform: none;
  transition: opacity 0.4s ease, transform 0.4s ease;
}
.deal-chat-duel-result { display: flex; align-items: center; justify-content: center; gap: 6px; }
.deal-chat-duel-result .dcdr-name { min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.deal-chat-duel-result .dcdr-amt { flex: none; color: #ffd66b; }
.deal-chat-duel-btn { width: 100%; }
.deal-chat-duel-card.is-rolling .deal-chat-duel-result { opacity: 0; transform: translateY(6px); }
.deal-chat-duel-card.is-landed .deal-chat-duel-result.is-revealed { opacity: 1; transform: none; }

.die3d-unknown {
  width: 58px;
  height: 58px;
  margin: 6px 0 6px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 16px;
  background: rgba(255, 255, 255, 0.07);
  border: 1.5px dashed rgba(200, 190, 255, 0.35);
  font-size: 22px;
  font-weight: 800;
  color: rgba(225, 215, 255, 0.55);
}

/* the die: warm ivory, a glossy top edge, a soft table shadow */
.die { position: relative; width: 84px; height: 70px; display: flex; align-items: flex-start; justify-content: center; padding-top: 6px; box-sizing: border-box; }
.die-face {
  position: relative;
  width: 58px;
  height: 58px;
  display: grid;
  grid-template: repeat(3, 1fr) / repeat(3, 1fr);
  padding: 10px;
  box-sizing: border-box;
  border-radius: 16px;
  background: linear-gradient(165deg, #ffffff 0%, #f6efe0 55%, #e9dfca 100%);
  box-shadow: inset 0 -4px 0 rgba(120, 90, 40, 0.16), inset 0 2px 0 rgba(255, 255, 255, 0.95), inset 0 0 0 1px rgba(255, 255, 255, 0.5);
  transition: transform 0.25s cubic-bezier(0.2, 0.9, 0.3, 1.2), filter 0.25s ease;
  z-index: 1;
}
.die-face::after {  /* a soft gloss on the upper half */
  content: "";
  position: absolute;
  inset: 3px 3px 52% 3px;
  border-radius: 13px 13px 40% 40%;
  background: linear-gradient(180deg, rgba(255, 255, 255, 0.75), rgba(255, 255, 255, 0));
  pointer-events: none;
}
.die-face i {
  width: 11px;
  height: 11px;
  margin: auto;
  border-radius: 50%;
  background: radial-gradient(circle at 35% 30%, #4a3a86, #1b1240 72%);
  box-shadow: inset 0 1px 2px rgba(0, 0, 0, 0.55), 0 1px 0 rgba(255, 255, 255, 0.6);
}
.die-face i.is-one { width: 16px; height: 16px; background: radial-gradient(circle at 35% 30%, #ff6a7e, #c8142f 72%); }
/* the hop: fading bounces, the shadow shrinks while the die is in the air */
.die.is-tossed .die-face { animation: rp-die-toss var(--toss, 2000ms) linear both; }
@keyframes rp-die-toss {
  0% { transform: translateY(0); }
  14% { transform: translateY(-20px); }
  30% { transform: translateY(0); }
  44% { transform: translateY(-12px); }
  58% { transform: translateY(0); }
  70% { transform: translateY(-6px); }
  82% { transform: translateY(0); }
  91% { transform: translateY(-2px); }
  100% { transform: translateY(0); }
}
.die.is-landed .die-face { animation: rp-die-land 0.42s cubic-bezier(0.25, 0.9, 0.35, 1.5); }
@keyframes rp-die-land { 0% { transform: translateY(-9px) scale(1.1); } 55% { transform: translateY(2px) scale(0.97); } 100% { transform: none; } }

.deal-chat-duel-side.is-loser .die { opacity: 1; }
.deal-chat-duel-card.is-finished:not(.is-rolling) .deal-chat-duel-side.is-loser .die-face { filter: brightness(0.8) saturate(0.9); }
.die-crown { position: absolute; top: -10px; left: 50%; margin-left: -11px; z-index: 3; display: none; filter: drop-shadow(0 2px 3px rgba(0, 0, 0, 0.35)); }
.deal-chat-duel-card.is-finished:not(.is-rolling) .die-crown { display: block; }
.deal-chat-duel-card.is-landed .die-crown { animation: rp-crown-pop 0.5s cubic-bezier(0.25, 0.9, 0.35, 1.6) both; }
@keyframes rp-crown-pop { 0% { transform: translateY(8px) scale(0); opacity: 0; } 100% { transform: none; opacity: 1; } }


/* Бухгалтерия */
