/* One chevron for the whole app: a rounded SVG instead of the font glyphs «›» / «‹» (they looked crooked and different everywhere) */
.level-row-chev,
.reputation-stats-chev,
.shop-customize-fold summary i,
.promo-pick-go,
.report-month-btn,
.shop-style-arrow,
.shop-nav,
.iv-nav,
.gallery-arrow {
  font-size: 0 !important;
  line-height: 0 !important;
  display: inline-flex;
  align-items: center;
  justify-content: center;
}
.level-row-chev::before,
.reputation-stats-chev::before,
.shop-customize-fold summary i::before,
.promo-pick-go::before,
.report-month-btn::before,
.shop-style-arrow::before,
.shop-nav::before,
.iv-nav::before,
.gallery-arrow::before {
  content: "";
  flex: none;
  width: 16px;
  height: 16px;
  background: currentColor;
  -webkit-mask: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='none' stroke='black' stroke-width='2.6' stroke-linecap='round' stroke-linejoin='round'><path d='M9 5l7 7-7 7'/></svg>") center / contain no-repeat;
  mask: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='none' stroke='black' stroke-width='2.6' stroke-linecap='round' stroke-linejoin='round'><path d='M9 5l7 7-7 7'/></svg>") center / contain no-repeat;
}
.promo-pick-go:empty::before { display: none; }
.report-month-btn::before,
.shop-style-arrow::before,
.shop-nav::before,
