@keyframes ref-pulse { 0%, 100% { box-shadow: 0 0 0 3px rgba(var(--rf), 0.2), 0 0 14px rgba(var(--rf), 0.45); } 50% { box-shadow: 0 0 0 6px rgba(var(--rf), 0.12), 0 0 28px rgba(var(--rf), 0.8); } }
.ref-claim-btn {
