.ref-tile-prize { display: flex; flex-direction: column; align-items: center; gap: 1px; overflow-wrap: normal; word-break: normal; }
.ref-tile-prize .ref-tile-num { font-size: 17px; line-height: 1.1; font-weight: 900; color: #fcd34d; }
.ref-tile-prize small { font-size: 10px; line-height: 1.15; font-weight: 700; letter-spacing: -0.1px; color: rgba(255, 255, 255, 0.85); }
.ref-tile .ref-claim-btn { padding: 5px 8px !important; font-size: 10.5px !important; line-height: 1.2; border-radius: 9px !important; }

/* referrals: the final order (invite plate / three numbers / 50% line / prizes / my referrals) */
.ref-hero { padding: 18px 16px 16px; }
.ref-hero-title { font-size: 20px; margin-bottom: 6px; }
.ref-hero-text { margin-bottom: 14px; font-size: 13.5px; }
.ref-link-row { position: relative; display: flex; gap: 8px; margin-bottom: 10px; }
.ref-link-input {
  flex: 1;
  min-width: 0;
