}
.ref-copy-btn { flex: none; display: flex; align-items: center; gap: 6px; height: 46px; padding: 0 14px; border-radius: 14px; font-size: 13px; font-weight: 700; }
.ref-copy-btn svg { width: 18px; height: 18px; }
