.ref-stat { display: flex; flex-direction: column; align-items: center; justify-content: flex-start; gap: 4px; padding: 12px 6px 10px; border-radius: 16px; background: rgba(255, 255, 255, 0.05); border: 1px solid rgba(var(--rf), 0.26); text-align: center; }
.ref-stat-label { font-size: 11.5px; font-weight: 600; color: rgba(255, 255, 255, 0.62); line-height: 1.2; }
.ref-stat-value { display: flex; align-items: center; justify-content: center; gap: 5px; font-size: 19px; font-weight: 900; color: #fff; line-height: 1.1; }
