.ref-stat-coin { width: 16px; height: 16px; }
.ref-stat-claim { margin-top: auto; padding: 6px 12px; border: 0; border-radius: 10px; font-size: 12px; font-weight: 900; color: #2a1a08 !important; background: linear-gradient(180deg, #fbbf24, #f59e0b) !important; box-shadow: 0 3px 0 rgba(180, 100, 0, 0.55); }
