.ref-fifty { margin: 0 0 14px; padding: 12px 14px; border-radius: 14px; background: rgba(255, 255, 255, 0.05); border: 1px solid rgba(var(--rf), 0.2); font-size: 14px; color: rgba(255, 255, 255, 0.88); text-align: center; }
.ref-fifty b { color: #fcd34d; }
