.ref-link-row .ref-copy-btn svg { flex: none; width: 18px !important; height: 18px !important; }
.ref-link-row .ref-copy-btn span { font-size: 13px; font-weight: 800; }

/* ── награды как в макете: плитки с «хвостиком» вниз к узлам полосы, открытая светится рамкой ── */
.ref-ladder-card { padding: 16px 12px 14px; border-radius: 20px; background: rgba(255, 255, 255, 0.05); border: 1px solid rgba(var(--rf), 0.28); }
.ref-ladder { gap: 8px; padding-bottom: 8px; }
.ref-tile { min-height: 102px; padding: 12px 2px 10px; border: 1.5px solid rgba(255, 255, 255, 0.1); border-radius: 16px; background: rgba(255, 255, 255, 0.07); box-shadow: none; animation: none; gap: 5px; }
.ref-tile::after {  /* the tail pointing at the node of the track */
  content: "";
  position: absolute;
  left: 50%;
  top: 100%;
  width: 14px;
  height: 8px;
  margin-left: -7px;
  background: rgba(255, 255, 255, 0.07);
  -webkit-clip-path: polygon(0 0, 100% 0, 50% 100%);
  clip-path: polygon(0 0, 100% 0, 50% 100%);
}
.ref-tile.is-locked { opacity: 0.7; }
.ref-tile.is-claimed { border-color: rgba(255, 255, 255, 0.1); background: rgba(255, 255, 255, 0.07); }
.ref-tile.is-claimed .ref-tile-icon { opacity: 0.55; }
.ref-tile-state { position: absolute; top: 6px; right: 6px; min-height: 0; margin: 0; }
.ref-tile-state.is-done svg { width: 18px; height: 18px; padding: 3px; }
.ref-tile.is-available {
  border: 2px solid transparent;
  background: linear-gradient(rgba(34, 20, 70, 0.96), rgba(34, 20, 70, 0.96)) padding-box, linear-gradient(135deg, rgb(var(--rf)), #fbbf24) border-box;
  box-shadow: 0 0 0 3px rgba(var(--rf), 0.18), 0 0 22px rgba(var(--rf), 0.55);
  animation: ref-pulse 1.8s ease-in-out infinite;
}
.ref-tile.is-available::after { background: rgb(var(--rf)); }
.ref-tile.is-available .ref-tile-icon svg { filter: drop-shadow(0 0 6px rgba(255, 214, 120, 0.6)); }
.ref-track { height: 52px; margin-top: 12px; }
.ref-track-line { top: 7px; height: 6px; }
.ref-track-node { top: 2px; width: 16px; height: 16px; margin-left: -8px; }
.ref-track-node.is-reached { background: #fbbf24; border-color: #fbbf24; }
.ref-track-label { top: 27px; font-size: 11px; }
.ref-claim-bar {
  display: block;
  width: 100%;
  margin-top: 4px;
  padding: 13px 16px;
  border: 0;
  border-radius: 14px;
  font-size: 15px;
  font-weight: 900;
  color: #fff;
  background: linear-gradient(90deg, rgb(var(--rf)), rgba(var(--rf), 0.72));
  box-shadow: 0 4px 0 rgba(var(--rf), 0.4);
}
.ref-claim-bar:active { transform: translateY(2px); box-shadow: 0 2px 0 rgba(var(--rf), 0.4); }
.ref-claim-bar[hidden] { display: none !important; }

/* ── правки: первая плашка спокойная, как остальные; ничего не растягивается; без кнопки «Забрать» ── */
.ref-hero { background: rgba(255, 255, 255, 0.05) !important; border: 1px solid rgba(var(--rf), 0.28) !important; box-shadow: none !important; }
.ref-hero-glow { display: none; }
.ref-stats { align-items: start; }
.ref-stat { min-height: 0; padding: 12px 6px 12px; }
.ref-stat-claim { margin-top: 6px; }
.ref-stat-claim[disabled] { display: none !important; }
.ref-ladder { align-items: start; grid-auto-rows: auto; }
.ref-tile { min-height: 0; height: auto; align-self: start; padding: 12px 2px 12px; }
.ref-tile-state { display: contents; }
.ref-tile-state.is-done { display: flex; position: absolute; top: 6px; right: 6px; }
.ref-claim-bar { display: none !important; }
.ref-open-hint { margin: 2px 4px 0; font-size: 12.5px; text-align: center; color: rgba(255, 255, 255, 0.62); }
.ref-open-hint[hidden] { display: none !important; }
.ref-stat-claim { color: #fff !important; background: linear-gradient(90deg, rgb(var(--rf)), rgba(var(--rf), 0.72)) !important; box-shadow: 0 3px 0 rgba(var(--rf), 0.4) !important; }

/* the «Доступно» tile: no button, it glows and credits when tapped (like the prizes) */
.ref-stat--claim { position: relative; cursor: default; }
.ref-stat-cta { display: none; font-size: 10.5px; font-weight: 700; line-height: 1.2; color: rgba(255, 255, 255, 0.8); }
.ref-stat--claim.is-ready { cursor: pointer; border: 2px solid transparent; background: linear-gradient(rgba(34, 20, 70, 0.96), rgba(34, 20, 70, 0.96)) padding-box, linear-gradient(135deg, rgb(var(--rf)), #fbbf24) border-box; box-shadow: 0 0 0 3px rgba(var(--rf), 0.18), 0 0 22px rgba(var(--rf), 0.5); animation: ref-pulse 1.8s ease-in-out infinite; }
.ref-stat--claim.is-ready .ref-stat-cta { display: block; }
.ref-stat-claim { display: none !important; }

/* no tails under the prize tiles; a long label (продвижений) never leaves its tile */
