.ref-tile { overflow: hidden; }
.ref-tile-prize small.is-long { font-size: 8.5px; letter-spacing: -0.3px; max-width: 100%; }
.ref-tile-prize { max-width: 100%; }

/* the three numbers keep one height; the tap hint is a line under them */
