.ref-stat { justify-content: center; min-height: 66px; }
.ref-stat-cta { display: none !important; }
.ref-stats-hint { margin: 0 4px 12px; font-size: 12.5px; text-align: center; color: rgba(255, 255, 255, 0.62); }
