  border: 1px solid rgba(255, 255, 255, 0.08);
  background: rgba(255, 255, 255, 0.04);
  box-shadow: none;
  overflow: hidden;
}

body.tournament-active .leaderboard-header {
  position: relative;
  min-height: 300px;
  padding: 0;
  border-radius: 22px;
  border-color: rgba(255, 255, 255, 0.08);
  background: linear-gradient(180deg, #0d1224, #060912);
  box-shadow: 0 12px 28px rgba(0, 0, 0, 0.32);
  overflow: hidden;
}

.leaderboard-header::before,
.leaderboard-header::after {
  display: none;
}

.leaderboard-header-sparkles {
  display: none;
}

.leaderboard-header-sparkle::before {
  display: none;
}

.leaderboard-header-sparkle:nth-child(1),
.leaderboard-header-sparkle:nth-child(2),
.leaderboard-header-sparkle:nth-child(3),
.leaderboard-header-sparkle:nth-child(4) {
  display: none;
}

.leaderboard-hero-top {
  width: 100%;
  min-height: 80px;
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  gap: 0;
  align-items: center;
  position: relative;
  z-index: 2;
}

body.tournament-active .leaderboard-hero-top {
  position: relative;
  z-index: 2;
  min-height: 300px;
  align-items: end;
  padding: 12px 14px 16px;
}

.leaderboard-hero-main {
  min-width: 0;
  display: grid;
  gap: 0;
  justify-items: center;
  text-align: center;
  width: 100%;
  padding: 0;
  align-self: center;
}

body.tournament-active .leaderboard-hero-main {
  align-self: end;
  justify-self: stretch;
  /* grid container: push rows to the bottom (align-content), keep
     items horizontally centered (justify-items). The previous
     `justify-content: end` was shifting the whole content right,
     hence the "crooked" title. */
  align-content: end;
  justify-items: center;
  align-items: center;
  text-align: center;
  width: 100%;
  padding-top: 0;
  gap: 6px;
  position: relative;
  z-index: 2;
}

.leaderboard-tournament-visual {
  display: none;
}

/* Tournament hero — real PNG fills the card; text sits in the bottom
   safe zone with a soft gradient mask for legibility. The character
   in the image stays visually clear because the gradient only ramps
   up over the lower 40% of the card. */
body.tournament-active .leaderboard-tournament-visual {
  display: block;
  position: absolute;
  inset: 0;
  z-index: 1;
  pointer-events: none;
  overflow: hidden;
  width: auto;
  height: auto;
  transform: none;
  top: 0;
  left: 0;
}

body.tournament-active .leaderboard-tournament-hero {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  max-width: none;
  transform: none;
  top: 0;
  left: 0;
  object-fit: cover;
  object-position: center 28%;
  display: block;
  user-select: none;
  -webkit-user-drag: none;
}

body.tournament-active .leaderboard-tournament-visual::after {
  content: "";
  position: absolute;
  inset: 0;
  pointer-events: none;
  background: linear-gradient(
    180deg,
    transparent 0%,
    transparent 55%,
    rgba(6, 9, 18, 0.32) 68%,
    rgba(6, 9, 18, 0.82) 86%,
    rgba(6, 9, 18, 0.96) 100%
  );
}

