}

[data-mine-theme="glass"] .mine-balance-top-unit {
  color: #bcd2ff;
}

[data-mine-theme="glass"] .mine-wardrobe-btn {
  background:
    linear-gradient(180deg, rgba(72, 118, 238, 0.18), rgba(34, 48, 108, 0.18) 100%);
  border-color: rgba(168, 205, 255, 0.22);
  box-shadow:
    0 6px 16px rgba(4, 10, 28, 0.25),
    inset 0 1px 0 rgba(186, 218, 255, 0.1);
  backdrop-filter: blur(10px) saturate(130%);
  -webkit-backdrop-filter: blur(10px) saturate(130%);
}

[data-mine-theme="glass"] .mine-rules-btn {
  width: 32px;
  height: 32px;
  background:
    linear-gradient(180deg, rgba(72, 118, 238, 0.1), rgba(34, 48, 108, 0.12) 100%);
