/* === MAIN M-COIN HERO === */
.page-coins {
  padding-bottom: 8px;
}

.page-coins.active {
  gap: 14px;
}

.mcoin-hero {
  position: relative;
  padding: 12px 12px 14px;
  border-radius: 18px;
  background:
    radial-gradient(160px 120px at 88% 14%, rgba(255, 212, 118, 0.22), transparent 72%),
    radial-gradient(180px 130px at 14% 78%, rgba(92, 152, 255, 0.14), transparent 74%),
    linear-gradient(160deg, rgba(45, 34, 80, 0.92), rgba(17, 14, 38, 0.96));
  border: 1px solid rgba(255, 214, 130, 0.24);
  overflow: hidden;
  box-shadow:
    0 16px 32px rgba(7, 9, 20, 0.34),
    inset 0 1px 0 rgba(255, 255, 255, 0.09),
    inset 0 -1px 0 rgba(255, 215, 134, 0.1);
}

.mcoin-hero-glow {
  position: absolute;
  top: -28%;
  left: 50%;
  transform: translateX(-50%) scale(1);
  width: 220%;
  height: 190%;
  background: radial-gradient(circle, rgba(255, 204, 96, 0.18) 0%, transparent 52%);
  pointer-events: none;
  animation: mcoinPulse 5.2s ease-in-out infinite;
}

@keyframes mcoinPulse {
  0%, 100% { opacity: 0.46; transform: translateX(-50%) scale(1); }
  50% { opacity: 0.8; transform: translateX(-50%) scale(1.08); }
}

.mcoin-hero-stars {
  position: absolute;
  inset: 0;
  pointer-events: none;
}

.mcoin-star {
  position: absolute;
  width: 4px;
  height: 4px;
  border-radius: 50%;
  background: rgba(255, 223, 147, 0.92);
  box-shadow: 0 0 10px rgba(255, 213, 120, 0.44);
  animation: mcoinStarTwinkle 2.8s ease-in-out infinite;
}

.mcoin-star--1 { top: 14%; left: 9%; animation-delay: 0s; }
.mcoin-star--2 { top: 20%; left: 30%; animation-delay: 1s; width: 3px; height: 3px; }
.mcoin-star--3 { top: 11%; right: 18%; animation-delay: 1.8s; }
.mcoin-star--4 { top: 48%; right: 10%; animation-delay: 0.6s; width: 3px; height: 3px; }
.mcoin-star--5 { bottom: 19%; left: 20%; animation-delay: 2.1s; width: 3px; height: 3px; }
.mcoin-star--6 { bottom: 27%; right: 24%; animation-delay: 1.3s; width: 2px; height: 2px; }
.mcoin-star--7 { top: 35%; left: 74%; animation-delay: 2.5s; width: 2px; height: 2px; }

/* Keep the topbar clean: upper sparkles conflict with the balance pill. */
.mcoin-star--1,
.mcoin-star--2,
.mcoin-star--3 {
  display: none;
}

@keyframes mcoinStarTwinkle {
  0%, 100% { opacity: 0.35; transform: scale(0.8); }
  50% { opacity: 1; transform: scale(1.2); }
}

.mcoin-hero-content {
  position: relative;
  z-index: 1;
  display: grid;
  gap: 10px;
}

.mcoin-hero-topbar {
  position: absolute;
  top: 2px;
  left: 2px;
  right: 2px;
  z-index: 3;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 6px;
  pointer-events: none;
}

.mcoin-hero-center {
  min-height: 128px;
  padding-top: 40px;
  display: grid;
  justify-items: center;
  align-content: center;
  gap: 7px;
  text-align: center;
}

.mcoin-rocket-wrap {
  position: relative;
  width: 166px;
  height: 108px;
  margin-top: 10px;
  animation: mcoinRocketFloat 4.4s ease-in-out infinite;
}

.mcoin-rocket-wrap::before {
  content: "";
  position: absolute;
  inset: 24% 18% 22% 18%;
  border-radius: 50%;
  pointer-events: none;
  background: radial-gradient(circle, rgba(255, 210, 106, 0.36), rgba(255, 210, 106, 0));
  filter: blur(4px);
  animation: mcoinCoinAura 3.2s ease-in-out infinite;
}

.mcoin-rocket {
  width: 100%;
  height: 100%;
  filter: drop-shadow(0 12px 28px rgba(255, 184, 84, 0.44));
  position: relative;
  z-index: 1;
}

.mcoin-coin-spec {
  transform-origin: center;
  animation: mcoinCoinSpecPulse 3.8s ease-in-out infinite;
}

.mcoin-rocket-trail {
  display: none;
}

@keyframes mcoinRocketFloat {
  0%, 100% { transform: translateY(0); }
  50% { transform: translateY(-6px) rotate(-1deg); }
}

@keyframes mcoinCoinAura {
  0%, 100% { opacity: 0.45; transform: scale(0.96); }
  50% { opacity: 0.82; transform: scale(1.08); }
}

@keyframes mcoinCoinSpecPulse {
  0%, 100% {
    opacity: 0.68;
    transform: scale(0.94);
  }
  50% {
    opacity: 1;
    transform: scale(1.06);
  }
}

@keyframes mcoinTrailPulse {
  0%, 100% { opacity: 0.46; transform: rotate(-20deg) scaleX(0.9); }
  50% { opacity: 0.9; transform: rotate(-20deg) scaleX(1.05); }
}

@media (prefers-reduced-motion: reduce) {
  .mcoin-hero-glow,
  .mcoin-star,
  .mcoin-rocket-wrap,
  .mcoin-rocket-wrap::before,
  .mcoin-coin-spec,
  .mcoin-rocket-trail {
    animation: none !important;
  }
}

