}

.inventory-panel {
  width: min(100%, 760px);
  min-height: calc(100svh - var(--bottom-nav-height, 108px) - var(--tg-safe-bottom-offset) - 26px);
  margin-inline: auto;
  border-radius: 0;
  border: 0;
  background: transparent;
  box-shadow: none;
  display: grid;
  align-content: start;
  justify-items: center;
  gap: 14px;
  padding: 10px 14px 18px;
  overflow: visible;
  position: relative;
  z-index: 1;
}

.inventory-panel::before {
  content: "";
  position: absolute;
  inset: 94px 10px 14px;
  pointer-events: none;
  border-radius: 24px;
  background:
    radial-gradient(300px 210px at 16% 86%, rgba(72, 51, 166, 0.1), transparent 72%),
    radial-gradient(240px 180px at 84% 82%, rgba(101, 74, 199, 0.09), transparent 72%);
