  border: 1px solid rgba(155, 242, 177, 0.28);
  color: #9bf2b1;
  box-shadow: none;
}

/* === CHESTS PANEL === */
.page.page-coins-detail[data-page="coins-chests"] {
  min-width: 0;
}

.cases-home {
  width: 100%;
  min-width: 0;
  max-width: 100%;
  margin-bottom: 14px;
  padding: 4px 0 2px;
  border-radius: 0;
  background: transparent;
  border: 0;
  box-shadow: none;
}

.cases-home-strip {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  align-items: center;
  gap: 10px;
  width: min(100%, 340px);
  overflow: visible;
  padding: 0;
  margin: 2px auto 14px;
  border-radius: 0;
  background: transparent;
  border: 0;
  box-shadow: none;
  scrollbar-width: none;
}

.cases-home-strip::-webkit-scrollbar {
  display: none;
}

.cases-chip {
  position: relative;
  min-height: 46px;
  border: 1px solid rgba(160, 132, 246, 0.22);
  background:
    linear-gradient(145deg, rgba(52, 34, 112, 0.28), rgba(25, 17, 58, 0.34));
  color: rgba(231, 221, 255, 0.8);
  border-radius: 999px;
  padding: 10px 16px;
  font-size: 15px;
  font-weight: 800;
  letter-spacing: -0.01em;
  white-space: nowrap;
  text-align: center;
  backdrop-filter: blur(10px) saturate(116%);
  -webkit-backdrop-filter: blur(10px) saturate(116%);
  transition: color 180ms ease, background 180ms ease, border-color 180ms ease, transform 180ms ease, box-shadow 180ms ease;
}

.cases-chip.active {
  border-color: rgba(180, 155, 255, 0.24);
  color: rgba(247, 241, 255, 0.98);
  background:
    radial-gradient(100% 130% at 50% -10%, rgba(185, 145, 255, 0.2), transparent 60%),
    linear-gradient(145deg, rgba(120, 92, 235, 0.34), rgba(78, 56, 170, 0.34));
  box-shadow:
    inset 0 1px 0 rgba(240, 230, 255, 0.22),
    0 8px 16px rgba(0, 0, 0, 0.2);
}

.cases-chip:not(.active):active {
  transform: translateY(1px);
  color: rgba(245, 238, 255, 0.94);
  background: rgba(103, 70, 186, 0.18);
}

.cases-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 14px;
  width: 100%;
  min-width: 0;
}

.case-entry-card {
  width: 100%;
  min-width: 0;
  border-radius: 24px;
  border: 1px solid rgba(180, 142, 255, 0.18);
  background:
    radial-gradient(120% 90% at 16% 0%, rgba(168, 108, 255, 0.13), transparent 52%),
    linear-gradient(180deg, rgba(31, 20, 66, 0.88), rgba(17, 12, 40, 0.96));
  padding: 14px;
  text-align: left;
  color: #fff;
  display: grid;
  gap: 10px;
  box-shadow:
    0 12px 28px rgba(6, 3, 20, 0.3),
    inset 0 1px 0 rgba(255, 255, 255, 0.05);
  transition: transform 180ms ease, border-color 180ms ease, box-shadow 180ms ease, background 180ms ease;
}

.case-entry-card.is-filter-hidden {
  display: none !important;
}

.case-entry-card.active {
  border-color: rgba(215, 180, 255, 0.52);
  box-shadow:
    0 0 0 1px rgba(188, 131, 255, 0.2),
    0 14px 30px rgba(12, 6, 32, 0.34),
    inset 0 1px 0 rgba(255, 255, 255, 0.07);
  background:
    radial-gradient(130% 100% at 15% 2%, rgba(220, 156, 255, 0.2), transparent 56%),
    linear-gradient(180deg, rgba(41, 26, 85, 0.92), rgba(23, 15, 53, 0.98));
  transform: translateY(-1px);
}

.case-entry-art {
  position: relative;
  border-radius: 18px;
  min-height: 170px;
  background:
    radial-gradient(110% 100% at 20% 0%, rgba(160, 119, 255, 0.14), transparent 60%),
    linear-gradient(180deg, rgba(63, 56, 93, 0.48), rgba(34, 28, 62, 0.62));
  display: grid;
  place-items: center;
  overflow: hidden;
  border: 1px solid rgba(204, 181, 255, 0.1);
}

.case-entry-art::after {
  content: "";
  position: absolute;
  inset: 0;
  background:
    radial-gradient(circle at 50% 0%, rgba(255, 255, 255, 0.12), transparent 62%),
    linear-gradient(180deg, transparent 45%, rgba(20, 11, 49, 0.18));
  pointer-events: none;
}

.case-entry-art img {
  width: 86%;
  max-width: 220px;
  max-height: 160px;
  object-fit: contain;
  filter: drop-shadow(0 10px 22px rgba(0, 0, 0, 0.44));
}

.case-entry-title {
  font-size: 19px;
  line-height: 1.15;
  font-weight: 900;
  letter-spacing: -0.01em;
}

.case-entry-price {
  margin-top: -1px;
  font-size: 15px;
  font-weight: 800;
  color: rgba(231, 220, 255, 0.88);
}

/* === NEW CASE OPEN VIEW (separate page) === */
.page-case-open {
  background: transparent;
}

/* Page: full-height fixed container for reel + sheet overlay */
.page.page-case-open.active {
  --case-sheet-collapsed-h: 368px;
  --case-sheet-expanded-h: min(680px, 76dvh);
  --case-vpad-top: 96px;
  --case-vpad-bottom: calc(var(--case-sheet-collapsed-h) - 10px);
  --case-topbar-pad-top: 5px;
  --case-topbar-pad-x: clamp(10px, 3.2vw, 12px);
  --case-sheet-handle-mt: 10px;
  --case-sheet-handle-mb: 9px;
  --case-sheet-header-px: clamp(14px, 3.8vw, 16px);
  --case-sheet-header-pb: 3px;
  --case-sheet-prizes-pb: 7px;
  --case-sheet-cta-pt: 5px;
  --case-sheet-cta-px: clamp(12px, 3.5vw, 14px);
  --case-reel-wrap-mt: 7px;
  --case-reel-wrap-pt: 11px;
  padding-top: 0;
  padding-bottom: 0;
  display: block;
  position: relative;
  height: calc(
    100dvh
    - (18px + var(--tg-safe-top-offset) + var(--app-brand-top-height) + 4px)
    - (16px + var(--tg-safe-bottom-offset))
  );
  min-height: unset;
  overflow: hidden;
  gap: 0;
}

/* Top reel area: balance pill + reel + win banner */
.case-reel-area {
  position: relative;
  width: 100%;
  height: 100%;
  display: flex;
  flex-direction: column;
  justify-content: center;
  /* Reserve fixed lanes: topbar above, sheet below — reel centers in remaining space */
  padding-top: var(--case-vpad-top);
  padding-bottom: var(--case-vpad-bottom);
  box-sizing: border-box;
  z-index: 1;
}

.case-open-topbar {
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  z-index: 2;
  padding: var(--case-topbar-pad-top) var(--case-topbar-pad-x) 0;
  display: flex;
  flex-direction: column;
  gap: 5px;
}

/* ── HUD: two separate rows ── */

/* Row 1: balance (left) + online (right) */
.case-hud-stats-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
}

.case-hud-balance-pill {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 5px 13px 5px 6px;
  border-radius: 999px;
  background: rgba(14, 9, 32, 0.78);
  border: 1px solid rgba(255, 255, 255, 0.1);
  backdrop-filter: blur(18px) saturate(140%);
  -webkit-backdrop-filter: blur(18px) saturate(140%);
  box-shadow: inset 0 1px 0 rgba(255,255,255,0.07), 0 4px 14px rgba(0,0,0,0.28);
  font-size: 13px;
  font-weight: 900;
  color: #fff;
  letter-spacing: 0.01em;
}

.case-hud-mcoin-logo {
  width: 26px;
  height: 26px;
  margin: -2px 0;
  border-radius: 50%;
  object-fit: contain;
  flex-shrink: 0;
  filter: drop-shadow(0 0 4px rgba(255, 200, 80, 0.45));
}

.case-hud-online-pill {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 5px 13px 5px 10px;
  border-radius: 999px;
  background: rgba(14, 9, 32, 0.78);
  border: 1px solid rgba(255, 255, 255, 0.1);
  backdrop-filter: blur(18px) saturate(140%);
  -webkit-backdrop-filter: blur(18px) saturate(140%);
  box-shadow: inset 0 1px 0 rgba(255,255,255,0.07), 0 4px 14px rgba(0,0,0,0.28);
  font-size: 13px;
  font-weight: 900;
  color: rgba(255, 255, 255, 0.88);
}

/* Pulsing green online dot */
.case-hud-online-dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: #4ee88a;
  box-shadow: 0 0 6px rgba(78, 232, 138, 0.85), 0 0 14px rgba(78, 232, 138, 0.35);
  animation: hudOnlineDot 2.4s ease-in-out infinite;
  flex-shrink: 0;
}

@keyframes hudOnlineDot {
  0%, 100% { box-shadow: 0 0 6px rgba(78, 232, 138, 0.85), 0 0 14px rgba(78, 232, 138, 0.35); }
  50%       { box-shadow: 0 0 10px rgba(78, 232, 138, 1.0), 0 0 22px rgba(78, 232, 138, 0.55); }
}

/* Row 2: live wins strip */
.case-live-strip {
  display: flex;
  align-items: center;
  gap: 7px;
  overflow: hidden;
  padding: 3px 4px;
  border-radius: 14px;
  background: rgba(14, 9, 32, 0.65);
  border: 1px solid rgba(255, 255, 255, 0.07);
  backdrop-filter: blur(14px);
  -webkit-backdrop-filter: blur(14px);
  min-height: 32px;
}

.case-live-strip[hidden] {
  display: none;
}

/* Pulsing red LIVE dot */
.case-live-strip-dot {
  width: 6px;
  height: 6px;
  min-width: 6px;
  border-radius: 50%;
  background: #ff4c4c;
  box-shadow: 0 0 6px rgba(255, 76, 76, 0.9), 0 0 12px rgba(255, 76, 76, 0.4);
  animation: hudLiveDot 1.5s ease-in-out infinite;
  margin-left: 4px;
}

@keyframes hudLiveDot {
  0%, 100% { opacity: 1; }
  50%       { opacity: 0.3; }
}

.case-live-strip-track {
  display: flex;
  gap: 5px;
  overflow-x: auto;
  overflow-y: hidden;
  scrollbar-width: none;
  -ms-overflow-style: none;
  overscroll-behavior-x: contain;
}

.case-live-strip-track::-webkit-scrollbar {
  display: none;
}

/* Winner chips */
.case-live-chip {
  flex: 0 0 auto;
  display: inline-flex;
  align-items: center;
  justify-content: flex-start;
  gap: 6px;
  padding: 3px 10px 3px 4px;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.06);
  border: 1px solid rgba(255, 255, 255, 0.1);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.05);
}

.case-live-chip-avatar.avatar {
  width: 20px;
  height: 20px;
  font-size: 8px;
  flex-shrink: 0;
  box-shadow: 0 0 8px rgba(140, 80, 255, 0.3);
}

.case-live-chip-reward {
  width: 14px;
  height: 14px;
  border-radius: 50%;
  display: grid;
  place-items: center;
  font-size: 9px;
  line-height: 1;
  flex-shrink: 0;
}

.reward-visual-img {
  width: 100%;
  height: 100%;
  object-fit: contain;
  display: block;
}

.case-live-chip-name {
  max-width: 86px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: 11px;
  font-weight: 700;
  color: rgba(255, 255, 255, 0.85);
}

/* === BOTTOM SHEET === */
.case-sheet {
  position: absolute;
  left: 0;
  right: 0;
  bottom: 0;
  /* Height controls visibility — bottom is always anchored to page bottom */
  height: var(--case-sheet-collapsed-h);
  /* Hard cap: sheet can never overflow the viewport */
  max-height: calc(100dvh - env(safe-area-inset-top, 0px) - 4px);
  border-radius: 28px 28px 0 0;
  background:
    radial-gradient(circle at 24px 22px, rgba(255,255,255,0.22) 0 1.15px, transparent 1.95px),
    radial-gradient(circle at 88px 54px, rgba(255,255,255,0.15) 0 0.95px, transparent 1.7px),
    radial-gradient(circle at 146px 30px, rgba(216,195,255,0.22) 0 1.2px, transparent 2px),
    radial-gradient(circle at 42px 88px, rgba(255,255,255,0.11) 0 0.85px, transparent 1.45px),
    radial-gradient(circle at 132px 96px, rgba(195,170,255,0.16) 0 1px, transparent 1.7px),
    radial-gradient(circle at 176px 68px, rgba(255,255,255,0.09) 0 0.8px, transparent 1.35px),
    radial-gradient(circle at 116px 14px, rgba(255,255,255,0.16) 0 0.75px, transparent 1.3px),
    radial-gradient(circle at 16px 74px, rgba(190,160,255,0.16) 0 0.8px, transparent 1.35px),
    radial-gradient(circle at 62px 16px, rgba(255,255,255,0.28) 0 0.7px, transparent 1.1px),
    radial-gradient(circle at 152px 82px, rgba(255,255,255,0.20) 0 0.65px, transparent 1.05px),
    linear-gradient(180deg, rgba(20, 14, 46, 0.97) 0%, rgba(10, 6, 24, 0.99) 100%);
  background-size:
    174px 112px,
    174px 112px,
    174px 112px,
    174px 112px,
    174px 112px,
    174px 112px,
    174px 112px,
    174px 112px,
    174px 112px,
    174px 112px,
    auto;
  background-repeat: repeat, repeat, repeat, repeat, repeat, repeat, repeat, repeat, repeat, repeat, no-repeat;
  backdrop-filter: blur(24px) saturate(150%);
  -webkit-backdrop-filter: blur(24px) saturate(150%);
  border: 1px solid rgba(255, 255, 255, 0.1);
  border-bottom: none;
  box-shadow:
    0 -6px 40px rgba(0, 0, 0, 0.55),
    0 -1px 0 rgba(255, 255, 255, 0.06);
  z-index: 20;
  touch-action: pan-y;
  display: grid;
  grid-template-rows: auto auto minmax(0, 1fr) auto;
  overflow: hidden;
  transition: height 380ms cubic-bezier(0.22, 0.68, 0, 1.05);
  will-change: height;
}

.case-sheet::before {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: inherit;
  pointer-events: none;
  border: 1px solid rgba(146, 104, 255, 0.34);
  box-shadow:
    inset 0 1px 0 rgba(210, 186, 255, 0.18),
    inset 0 0 0 1px rgba(104, 66, 220, 0.10),
    0 0 0 1px rgba(120, 78, 235, 0.08),
    0 -10px 30px rgba(118, 72, 255, 0.12);
  z-index: 0;
}

.case-sheet::after {
  content: "";
  position: absolute;
  left: 18px;
  right: 18px;
  top: 0;
  height: 1px;
  background: linear-gradient(90deg, rgba(0,0,0,0), rgba(186, 142, 255, 0.65), rgba(0,0,0,0));
  pointer-events: none;
  z-index: 0;
}

.case-sheet > * {
  position: relative;
  z-index: 1;
}

.case-sheet.is-dragging {
  transition: none;
  /* Kill the expensive blur/saturate during drag — restored instantly on release */
  backdrop-filter: none;
  -webkit-backdrop-filter: none;
}

.case-sheet.is-expanded {
  height: var(--case-sheet-expanded-h);
}

/* Drag handle */
.case-sheet-handle {
  width: 36px;
  height: 4px;
  border-radius: 2px;
  background: rgba(255, 255, 255, 0.25);
  margin: var(--case-sheet-handle-mt) auto var(--case-sheet-handle-mb);
  flex-shrink: 0;
  cursor: grab;
}

/* Sheet header: title + thumb */
.case-sheet-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  padding: 2px var(--case-sheet-header-px) var(--case-sheet-header-pb);
  flex-shrink: 0;
}

.case-sheet-info {
  display: flex;
  flex-direction: column;
  gap: 1px;
  min-width: 0;
}

.case-sheet-name {
  font-size: 22px;
  font-weight: 900;
  color: #fff;
  letter-spacing: -0.02em;
  line-height: 1.1;
}

.case-sheet-sub {
  font-size: 13px;
  font-weight: 600;
  color: rgba(190, 170, 255, 0.72);
}

.case-sheet-thumb {
  width: clamp(58px, 16vw, 72px);
  height: clamp(58px, 16vw, 72px);
  object-fit: contain;
  border-radius: 12px;
  filter: drop-shadow(0 6px 16px rgba(130, 70, 240, 0.42));
  flex-shrink: 0;
  transform: translateX(-8px);
}

/* Prizes section: fills middle, clips below visible area in collapsed */
.case-sheet-prizes {
  min-height: 0;
  overflow: hidden;
  padding: 0 12px var(--case-sheet-prizes-pb);
}

.case-sheet.is-expanded .case-sheet-prizes {
  overflow-y: auto;
  overscroll-behavior: contain;
}

.case-sheet-prizes-head {
  font-size: 11px;
  font-weight: 800;
  color: rgba(190, 170, 255, 0.65);
  text-transform: uppercase;
  letter-spacing: 0.07em;
  margin-bottom: 8px;
}

/* CTA — always at the bottom, never moves */
.case-sheet-cta {
  position: relative;
  padding: calc(var(--case-sheet-cta-pt) + 4px) var(--case-sheet-cta-px) calc(2px + env(safe-area-inset-bottom, 0px));
  background: transparent;
  display: grid;
  gap: 8px;
}

.case-sheet-cta::before {
  content: none;
}

.case-sheet-cta > * {
  position: relative;
  z-index: 1;
}

.case-open-reel-wrap {
  position: relative;
  flex: 0 0 auto;
  min-width: 0;
  margin-top: var(--case-reel-wrap-mt);
  padding: var(--case-reel-wrap-pt) 0 2px;
  z-index: 1;
}

.case-open-pointer {
  position: absolute;
  left: 50%;
  top: 0;
  transform: translateX(-50%);
  z-index: 5;
  pointer-events: none;
  display: flex;
  flex-direction: column;
  align-items: center;
}

/* Purple diamond indicator */
.case-open-pointer::before {
  content: "";
  display: block;
  width: 18px;
  height: 18px;
  background: linear-gradient(145deg, #c998ff 0%, #8b3cf7 45%, #4c11b0 100%);
  transform: rotate(45deg);
  border-radius: 4px;
  box-shadow:
    0 0 10px rgba(190, 130, 255, 0.78),
    0 0 26px rgba(125, 70, 255, 0.5),
    inset 0 1px 0 rgba(255, 255, 255, 0.5);
  animation: reelDiamondGlow 1.8s ease-in-out infinite;
}

@keyframes reelDiamondGlow {
  0%, 100% {
    box-shadow: 0 0 10px rgba(190, 130, 255, 0.78), 0 0 26px rgba(125, 70, 255, 0.5), inset 0 1px 0 rgba(255, 255, 255, 0.5);
  }
  50% {
    box-shadow: 0 0 18px rgba(220, 165, 255, 1), 0 0 40px rgba(150, 90, 255, 0.72), inset 0 1px 0 rgba(255, 255, 255, 0.5);
  }
}

/* Sparkle particles around the pointer */
.reel-sparkle {
  position: absolute;
  width: 5px;
  height: 5px;
  border-radius: 50%;
  background: radial-gradient(circle, #e5bcff 0%, #9b5cff 60%, transparent 100%);
  pointer-events: none;
}

.reel-sparkle.sp1 { top: -14px; left: -20px;  animation: reelSparkle 2.2s ease-in-out infinite 0.0s; }
.reel-sparkle.sp2 { top:   6px; left: -28px;  animation: reelSparkle 1.9s ease-in-out infinite 0.7s; }
.reel-sparkle.sp3 { top: -14px; right: -20px; animation: reelSparkle 2.5s ease-in-out infinite 0.3s; }
.reel-sparkle.sp4 { top:   6px; right: -28px; animation: reelSparkle 2.0s ease-in-out infinite 1.1s; }
.reel-sparkle.sp5 { top: -22px; left: -4px;   animation: reelSparkle 2.8s ease-in-out infinite 1.5s; }

@keyframes reelSparkle {
  0%, 100% { opacity: 0; transform: translateY(0) scale(0.4); }
  40%, 60% { opacity: 0.85; transform: translateY(-5px) scale(1); }
}

/* ── Full-screen win overlay ── */
.case-win-overlay {
  position: fixed;
  inset: 0;
  z-index: 9999;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  background:
    radial-gradient(ellipse 82% 62% at 50% 40%, rgba(126, 76, 255, 0.34) 0%, rgba(126, 76, 255, 0.10) 38%, rgba(126, 76, 255, 0) 62%),
    linear-gradient(180deg, #18073d 0%, #11062d 46%, #0a031a 100%);
  padding: 12px 22px calc(18px + env(safe-area-inset-bottom, 0px));
  overflow: hidden;
  animation: caseWinOverlayIn 420ms cubic-bezier(0.22, 0.68, 0, 1) both;
}

body.case-win-open .app-brand-top {
  opacity: 0;
  visibility: hidden;
  pointer-events: none;
}

.case-win-overlay[hidden] {
  display: none;
}

@keyframes caseWinOverlayIn {
  from { opacity: 0; transform: scale(1.03); }
  to   { opacity: 1; transform: scale(1); }
}

/* ── Wide soft rays ── */
.case-win-rays {
  position: absolute;
  inset: -100%;
  background: conic-gradient(
    from 0deg,
    transparent 0deg 26deg,   rgba(210,180,255,0.07) 26deg 44deg,
    transparent 44deg 71deg,  rgba(210,180,255,0.07) 71deg 89deg,
    transparent 89deg 116deg, rgba(210,180,255,0.07) 116deg 134deg,
    transparent 134deg 161deg,rgba(210,180,255,0.07) 161deg 179deg,
    transparent 179deg 206deg,rgba(210,180,255,0.07) 206deg 224deg,
    transparent 224deg 251deg,rgba(210,180,255,0.07) 251deg 269deg,
    transparent 269deg 296deg,rgba(210,180,255,0.07) 296deg 314deg,
    transparent 314deg 341deg,rgba(210,180,255,0.07) 341deg 359deg,
    transparent 359deg 360deg
  );
  animation: caseWinRaysSpin 22s linear infinite;
  pointer-events: none;
  -webkit-mask: radial-gradient(ellipse 62% 52% at center, black 0%, black 18%, transparent 64%);
          mask: radial-gradient(ellipse 62% 52% at center, black 0%, black 18%, transparent 64%);
}

@keyframes caseWinRaysSpin {
  from { transform: rotate(0deg); }
  to   { transform: rotate(360deg); }
}

/* ── Content ── */
.case-win-body {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 8px;
  flex: 0 0 auto;
  justify-content: center;
  position: relative;
  z-index: 1;
  margin-top: 0;
  margin-bottom: 16px;
  width: 100%;
}

/* "Вы выиграли!" */
.case-win-label {
  font-size: 32px;
  font-weight: 900;
  color: #fff;
  text-align: center;
  line-height: 1.1;
  letter-spacing: -0.01em;
  text-shadow: 0 2px 20px rgba(0, 0, 0, 0.32);
  margin-bottom: 2px;
  animation: caseWinSlideDown 500ms cubic-bezier(0.22, 0.68, 0, 1.2) 120ms both;
}

@keyframes caseWinSlideDown {
  from { opacity: 0; transform: translateY(-18px); }
  to   { opacity: 1; transform: translateY(0); }
}

/* Prize wrapper: glow + icon stacked */
.case-win-prize-wrap {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
  margin-top: 0;
  animation: caseWinIconPopIn 600ms cubic-bezier(0.34, 1.3, 0.64, 1) 240ms both;
}

/* Soft radial glow behind the prize */
.case-win-glow {
  position: absolute;
  width: 286px;
  height: 286px;
  border-radius: 50%;
  background: radial-gradient(circle, rgba(168, 118, 255, 0.34) 0%, rgba(124, 74, 238, 0.16) 44%, transparent 70%);
  pointer-events: none;
  animation: caseWinGlowPulse 4s ease-in-out infinite;
}

@keyframes caseWinGlowPulse {
  0%, 100% { transform: scale(1);    opacity: 0.82; }
  50%       { transform: scale(1.10); opacity: 1; }
}

/* Prize icon — large */
.case-win-icon {
  font-size: 156px;
  line-height: 1;
  display: block;
  position: relative;
  filter: drop-shadow(0 10px 36px rgba(0, 0, 0, 0.28));
}

.case-win-icon .reward-visual-img {
  width: 156px;
  height: 156px;
  object-fit: contain;
}

@keyframes caseWinIconPopIn {
  0%   { transform: scale(0.9); opacity: 0; }
  100% { transform: scale(1);   opacity: 1; }
}

/* Prize name */
.case-win-name {
  font-size: 22px;
  font-weight: 800;
  color: rgba(255, 255, 255, 0.95);
  text-align: center;
  line-height: 1.14;
  text-shadow: 0 1px 12px rgba(0, 0, 0, 0.28);
  animation: caseWinFadeUp 500ms ease 400ms both;
  margin-top: 4px;
}

/* Rarity badge */
.case-win-rarity {
  font-size: 12px;
  font-weight: 700;
  padding: 3px 10px;
  border-radius: 20px;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  background: rgba(255, 255, 255, 0.11);
  border: 1px solid rgba(255, 255, 255, 0.20);
  color: rgba(255, 255, 255, 0.68);
  animation: caseWinFadeUp 500ms ease 470ms both;
  margin-top: 2px;
}

.case-win-rarity:empty { display: none; }

.case-win-rarity.is-rare   { background: rgba(140, 100, 255, 0.18); border-color: rgba(180, 140, 255, 0.34); color: #c8a6ff; }
.case-win-rarity.is-epic   { background: rgba(200,  70, 255, 0.18); border-color: rgba(220, 130, 255, 0.38); color: #dfa8ff; }
.case-win-rarity.is-legend { background: rgba(255, 175,  28, 0.18); border-color: rgba(255, 210,  80, 0.42); color: #ffd668; }

@keyframes caseWinFadeUp {
  from { opacity: 0; transform: translateY(12px); }
  to   { opacity: 1; transform: translateY(0); }
}

/* ── Footer ── */
.case-win-footer {
  width: 100%;
  position: relative;
  z-index: 1;
  margin-top: 8px;
  margin-bottom: 0;
  animation: caseWinFadeUp 500ms ease 540ms both;
  display: flex;
  justify-content: center;
}

.case-win-continue-btn {
  width: auto;
  min-width: 240px;
  max-width: min(72vw, 320px);
  margin: 0;
  padding: 11px 20px;
  border-radius: 16px;
  border: 1px solid rgba(255, 255, 255, 0.22);
  background: rgba(255, 255, 255, 0.12);
  backdrop-filter: blur(18px) saturate(140%);
  -webkit-backdrop-filter: blur(18px) saturate(140%);
  box-shadow: 0 8px 22px rgba(10, 2, 30, 0.28), inset 0 1px 0 rgba(255, 255, 255, 0.18);
  color: #fff;
  font-size: 15px;
  font-weight: 900;
  letter-spacing: 0.01em;
  cursor: pointer;
  transition: transform 120ms ease, box-shadow 120ms ease;
}

@media (max-height: 760px) {
  .case-win-body {
    margin-top: 0;
    margin-bottom: 10px;
    gap: 6px;
  }

  .case-win-label {
    font-size: 28px;
    margin-bottom: 2px;
  }

  .case-win-icon {
    font-size: 132px;
  }

