    radial-gradient(circle at 40px 34px, rgba(255,255,255,0.05) 0 1px, transparent 1.5px),
    radial-gradient(circle at 68px 18px, rgba(255,255,255,0.06) 0 1px, transparent 1.5px);
  background-size: 84px 64px;
  opacity: 0.22;
}

.case-open-prize-card > *,
.case-reel-item > * {
  position: relative;
  z-index: 1;
}

.case-open-prize-card.is-common {
