    0 0 12px rgba(96, 126, 224, 0.12);
  background:
    radial-gradient(circle at 52% 16%, rgba(184,198,245,0.16), rgba(255,255,255,0) 48%),
    linear-gradient(180deg, rgba(255,255,255,0.05), rgba(255,255,255,0.02)),
