/* Edge fade-out — match body background #080410 */
.case-reel-viewport::before,
.case-reel-viewport::after {
  content: "";
  display: block;
  position: absolute;
  top: 0;
  bottom: 0;
  width: 72px;
  z-index: 10;
  pointer-events: none;
}

.case-reel-viewport::before {
  left: 0;
  background: linear-gradient(to right, rgba(8, 4, 16, 0.95) 0%, transparent 100%);
}

.case-reel-viewport::after {
  right: 0;
  background: linear-gradient(to left, rgba(8, 4, 16, 0.95) 0%, transparent 100%);
}

.case-reel-track {
  position: relative;
  z-index: 1;
  display: flex;
  align-items: flex-start;
  gap: 10px;
  height: 100%;
  padding: 10px 0 0;
  box-sizing: border-box;
  transform: translateX(0);
  will-change: transform;
}

.case-reel-item {
  --reel-arc: 0px;
  --reel-scale: 1;
  --reel-alpha: 1;
  --reel-z: 1;
  width: 194px;
  min-width: 194px;
  height: 244px;
  padding: 13px 10px 17px;
  position: relative;
  z-index: var(--reel-z);
  border-radius: 28px;
  border: 1px solid rgba(200, 220, 255, 0.12);
  background:
    linear-gradient(160deg, rgba(255, 255, 255, 0.08) 0%, rgba(255, 255, 255, 0.02) 100%),
    rgba(16, 10, 34, 0.95);
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.14),
    inset 0 -1px 0 rgba(0, 0, 0, 0.2),
    0 14px 36px rgba(0, 0, 0, 0.45);
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 6px;
  text-align: center;
  flex-shrink: 0;
  transform: translateY(var(--reel-arc)) scale(var(--reel-scale));
  transition: transform 55ms linear, opacity 55ms linear, box-shadow 100ms ease, border-color 100ms ease;
  transform-origin: center center;
  opacity: var(--reel-alpha);
  overflow: hidden;
  contain: layout style;
}

/* Telegram Android performance tiers. The reward and server result stay the
   same; only expensive reel cosmetics are reduced on weaker WebViews. */
html.android-perf-low .case-reel-item,
html.android-perf-average .case-reel-item {
  transition-property: transform, opacity;
}

html.android-perf-low .case-reel-item {
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.12), 0 6px 14px rgba(0, 0, 0, 0.30) !important;
}

html.android-perf-low .case-reel-item::after {
  display: none;
}

html.android-perf-low .case-reel-icon .reward-visual-img {
  filter: drop-shadow(0 5px 9px rgba(0, 0, 0, 0.28));
}

html.android-perf-average .case-reel-item {
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.14), 0 8px 20px rgba(0, 0, 0, 0.34) !important;
}

html.android-perf-average .case-reel-item::after {
  opacity: 0.10;
}

@media (max-height: 740px) {
