  box-shadow: 0 0 0 1px rgba(255, 214, 126, 0.55), 0 0 20px rgba(255, 190, 101, 0.5), 0 12px 28px rgba(255, 157, 68, 0.45);
  animation: bloggerClaimPulse 1.8s ease-in-out infinite;
}

.blogger-event-card.is-ready {
  border-color: rgba(255, 228, 161, 0.72);
  box-shadow: 0 0 0 1px rgba(255, 220, 145, 0.3), 0 20px 40px rgba(53, 30, 6, 0.5), inset 0 1px 0 rgba(255, 237, 191, 0.36);
  animation: bloggerCardReadyPulse 2.4s ease-in-out infinite;
}

.blogger-event-card.is-submitted {
  border-color: rgba(133, 243, 182, 0.55);
  background:
    radial-gradient(130% 120% at 100% 0%, rgba(102, 245, 190, 0.24), transparent 62%),
    radial-gradient(120% 100% at 0% 100%, rgba(255, 152, 72, 0.18), transparent 64%),
    linear-gradient(140deg, rgba(26, 32, 18, 0.92), rgba(13, 18, 11, 0.96));
}

.blogger-event-card.is-ended {
  filter: saturate(0.65);
}

@keyframes bloggerClaimPulse {
  0%, 100% {
    transform: translateY(0);
    box-shadow: 0 0 0 1px rgba(255, 214, 126, 0.55), 0 0 20px rgba(255, 190, 101, 0.42), 0 12px 28px rgba(255, 157, 68, 0.42);
  }
  50% {
    transform: translateY(-1px);
    box-shadow: 0 0 0 1px rgba(255, 214, 126, 0.72), 0 0 28px rgba(255, 203, 126, 0.62), 0 14px 30px rgba(255, 162, 73, 0.56);
  }
}

@keyframes bloggerProgressScan {
  0% {
    left: -28%;
    opacity: 0;
  }
  18% {
    opacity: 0.95;
  }
  82% {
    opacity: 0.9;
  }
  100% {
    left: 106%;
    opacity: 0;
  }
}

@keyframes bloggerCardReadyPulse {
  0%, 100% {
    box-shadow: 0 0 0 1px rgba(255, 220, 145, 0.28), 0 20px 40px rgba(53, 30, 6, 0.48), inset 0 1px 0 rgba(255, 237, 191, 0.34);
  }
  50% {
    box-shadow: 0 0 0 1px rgba(255, 232, 170, 0.5), 0 0 26px rgba(255, 205, 123, 0.38), 0 22px 44px rgba(53, 30, 6, 0.58), inset 0 1px 0 rgba(255, 244, 210, 0.55);
  }
}

@media (prefers-reduced-motion: reduce) {
  .blogger-event-progress-track::after,
  .blogger-event-card.is-ready,
  .blogger-event-claim-btn.is-glow:not(:disabled) {
    animation: none;
  }
}

.daily-login-card {
  position: relative;
  overflow: hidden;
  padding: 18px 16px 16px;
  border-radius: 22px;
  border: 1px solid rgba(139, 92, 246, 0.3);
  background:
    radial-gradient(120% 90% at 92% -8%, rgba(139, 92, 246, 0.2), transparent 56%),
    radial-gradient(88% 100% at 12% 100%, rgba(59, 130, 246, 0.12), transparent 58%),
    linear-gradient(165deg, rgba(26, 20, 40, 0.95), rgba(12, 10, 24, 0.98));
  box-shadow: 0 16px 34px rgba(20, 12, 36, 0.5);
  display: grid;
  gap: 11px;
}

.daily-login-head {
  display: grid;
  gap: 4px;
}

.daily-login-title {
  font-size: 17px;
  font-weight: 900;
  color: rgba(224, 212, 255, 0.98);
}

.daily-login-subtitle {
  font-size: 12px;
  color: rgba(196, 181, 253, 0.76);
  line-height: 1.35;
}

.daily-login-streak {
  display: grid;
  justify-items: center;
  gap: 2px;
  margin-top: 2px;
}

.dlm-planet--sm {
  filter: drop-shadow(0 0 12px rgba(139, 92, 246, 0.4));
  animation: dlm-float 5s ease-in-out infinite;
}

.dlm-stars--inline {
  position: absolute;
  inset: 0;
  background-image:
    radial-gradient(1px 1px at 15% 20%, rgba(255, 255, 255, 0.6), transparent),
    radial-gradient(1px 1px at 35% 70%, rgba(196, 181, 253, 0.5), transparent),
    radial-gradient(1px 1px at 60% 12%, rgba(255, 255, 255, 0.5), transparent),
    radial-gradient(1px 1px at 80% 55%, rgba(167, 139, 250, 0.5), transparent),
    radial-gradient(1px 1px at 92% 82%, rgba(255, 255, 255, 0.4), transparent),
    radial-gradient(1px 1px at 48% 40%, rgba(196, 181, 253, 0.4), transparent);
  pointer-events: none;
  animation: dlm-twinkle 4s ease-in-out infinite alternate;
}

.daily-login-streak-value {
  font-size: 44px;
  font-weight: 900;
  line-height: 0.95;
  background: linear-gradient(135deg, #e0d4ff 0%, #a78bfa 40%, #7c3aed 100%);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
  filter: drop-shadow(0 4px 14px rgba(139, 92, 246, 0.35));
}

.daily-login-streak-label {
  font-size: 14px;
  font-weight: 700;
  color: rgba(196, 181, 253, 0.8);
  letter-spacing: 0.3px;
}

.daily-login-week-labels {
  display: grid;
  grid-template-columns: repeat(7, minmax(0, 1fr));
  gap: 8px;
  font-size: 11px;
  color: rgba(196, 181, 253, 0.55);
  text-align: center;
  margin-top: -2px;
}

.daily-login-days {
  display: grid;
  grid-template-columns: repeat(7, minmax(0, 1fr));
  gap: 6px;
  padding: 8px;
  border-radius: 16px;
  border: 1px solid rgba(139, 92, 246, 0.25);
  background: rgba(139, 92, 246, 0.06);
  box-shadow: none;
}

.daily-login-day {
  border-radius: 12px;
  border: 1.5px solid rgba(139, 92, 246, 0.2);
  background: rgba(139, 92, 246, 0.06);
  min-height: 42px;
  display: grid;
  align-content: center;
  justify-items: center;
  gap: 0;
  padding: 4px 2px;
  transition: all 0.25s ease;
}

.daily-login-day-index {
  font-size: 9px;
  font-weight: 700;
  color: rgba(196, 181, 253, 0.5);
}

.daily-login-day-value {
  font-size: 18px;
  font-weight: 800;
  color: rgba(196, 181, 253, 0.4);
  line-height: 1.1;
  text-align: center;
}

.daily-login-day.is-label .daily-login-day-value {
  font-size: 17px;
}

.daily-login-day.is-done {
  border-color: rgba(139, 92, 246, 0.45);
  background: rgba(139, 92, 246, 0.18);
  box-shadow: 0 0 10px rgba(139, 92, 246, 0.12);
}

.daily-login-day.is-done .daily-login-day-value {
  color: #c4b5fd;
  text-shadow: 0 0 6px rgba(139, 92, 246, 0.35);
}

.daily-login-day.is-done .daily-login-day-index {
  color: rgba(196, 181, 253, 0.7);
}

.daily-login-day.is-current {
  border-color: rgba(167, 139, 250, 0.6);
  box-shadow: 0 0 0 2px rgba(139, 92, 246, 0.18), 0 0 16px rgba(139, 92, 246, 0.15);
  transform: translateY(-1px) scale(1.04);
}

.daily-login-day.is-current .daily-login-day-value {
  color: #e0d4ff;
  text-shadow: 0 0 8px rgba(167, 139, 250, 0.4);
}

.daily-login-day.is-current .daily-login-day-index {
  color: rgba(224, 212, 255, 0.8);
}

.daily-login-empty {
  grid-column: 1 / -1;
  text-align: center;
  font-size: 12px;
  color: rgba(196, 181, 253, 0.5);
  padding: 10px 0;
}

.daily-login-foot {
  display: grid;
  gap: 10px;
}

.daily-login-hint {
  font-size: 13px;
  color: rgba(196, 181, 253, 0.85);
  line-height: 1.35;
}

.daily-login-note {
  font-size: 11px;
  color: rgba(167, 139, 250, 0.65);
  line-height: 1.35;
}

.daily-login-claim-btn {
  width: 100%;
  border: 1px solid rgba(139, 92, 246, 0.45);
  border-radius: 14px;
  background: linear-gradient(135deg, #7c3aed, #6d28d9, #5b21b6);
  color: #f0e8ff;
  font-size: 14px;
  font-weight: 800;
  padding: 12px 14px;
  box-shadow: 0 8px 20px rgba(124, 58, 237, 0.25);
  letter-spacing: 0.3px;
}

.daily-login-claim-btn:active:not(:disabled) {
  transform: scale(0.97);
}

.daily-login-claim-btn:disabled {
  opacity: 0.5;
  background: rgba(139, 92, 246, 0.2);
  border-color: rgba(139, 92, 246, 0.2);
  box-shadow: none;
  color: rgba(196, 181, 253, 0.6);
}

/* ── Daily Login Modal — Cosmic Redesign ── */

.daily-login-modal-card {
  position: relative;
  overflow: hidden;
  border-color: rgba(139, 92, 246, 0.35);
  background:
    radial-gradient(ellipse 130% 80% at 50% -10%, rgba(139, 92, 246, 0.22), transparent 60%),
    radial-gradient(ellipse 100% 90% at 80% 110%, rgba(59, 130, 246, 0.14), transparent 55%),
