  padding: 28px 20px 22px;
  text-align: center;
}

/* star-field layer */
.dlm-stars {
  position: absolute;
  inset: 0;
  background-image:
    radial-gradient(1px 1px at 12% 18%, rgba(255, 255, 255, 0.7), transparent),
    radial-gradient(1px 1px at 28% 62%, rgba(255, 255, 255, 0.5), transparent),
    radial-gradient(1.2px 1.2px at 55% 8%, rgba(196, 181, 253, 0.8), transparent),
    radial-gradient(1px 1px at 72% 42%, rgba(255, 255, 255, 0.6), transparent),
    radial-gradient(1px 1px at 88% 78%, rgba(255, 255, 255, 0.45), transparent),
    radial-gradient(1.5px 1.5px at 40% 88%, rgba(147, 197, 253, 0.7), transparent),
    radial-gradient(1px 1px at 65% 30%, rgba(255, 255, 255, 0.5), transparent),
    radial-gradient(1px 1px at 18% 75%, rgba(196, 181, 253, 0.55), transparent),
    radial-gradient(1px 1px at 92% 15%, rgba(255, 255, 255, 0.6), transparent),
    radial-gradient(1.3px 1.3px at 5% 45%, rgba(167, 139, 250, 0.65), transparent),
