.shop-sets-content {
  display: flex;
  flex-direction: column;
  gap: 12px;
  margin-bottom: 16px;
}
.shop-sets-content[hidden] { display: none; }

.set-card {
  position: relative;
  border-radius: 16px;
  padding: 16px;
  overflow: hidden;
  cursor: pointer;
  transition: transform 0.15s ease;
}
.set-card:active { transform: scale(0.98); }

.set-card::before {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: 16px;
  opacity: 0.18;
  z-index: 0;
}
.set-card-inner {
  position: relative;
  z-index: 1;
  display: flex;
  align-items: center;
  gap: 14px;
}

