  min-width: 0;
}
.set-card-title {
  font-size: 16px;
  font-weight: 700;
  color: #fff;
  margin-bottom: 2px;
}
.set-card-subtitle {
  font-size: 12px;
  color: rgba(255,255,255,0.55);
}

.set-card-action {
  flex-shrink: 0;
}
.set-card-price {
