/* ===== Case opening: calmer rendering, no clipped edges, no double frames (2026-10) ===== */

/* the page reaches the bottom edge; the call-to-action carries the safe-area padding itself */
.page.page-case-open.active {
  height: var(--case-page-h, calc(100dvh - (18px + var(--tg-safe-top-offset) + var(--app-brand-top-height) + 4px)));
}

/* one frame on the sheet instead of two (the ::before used to add a second outline whose bottom got clipped) */
.case-sheet {
  border: 1px solid rgba(146, 104, 255, 0.3);
  border-bottom: 0;
}

.case-sheet::before {
  border: 0;
  box-shadow: inset 0 1px 0 rgba(210, 186, 255, 0.18);
}

/* prizes fade out under the button instead of being cut by it */
.page.page-case-open.active {
  --case-sheet-prizes-pb: 22px;
}

.case-sheet-cta {
  padding-bottom: calc(14px + env(safe-area-inset-bottom, 0px));
}

.case-sheet-cta::before {
  content: "";
  position: absolute;
  left: 0;
  right: 0;
  top: -26px;
  height: 26px;
  z-index: 0;
  pointer-events: none;
  background: linear-gradient(to top, rgba(14, 9, 33, 0.96), rgba(14, 9, 33, 0));
}

/* reel: fade the edges with a mask (side + top/bottom) so card shadows are not cut into a visible rectangle */
.case-reel-viewport {
  -webkit-mask-image:
    linear-gradient(to right, transparent 0, #000 56px, #000 calc(100% - 56px), transparent 100%),
    linear-gradient(to bottom, transparent 0, #000 14px, #000 calc(100% - 30px), transparent 100%);
  -webkit-mask-composite: source-in;
  mask-image:
    linear-gradient(to right, transparent 0, #000 56px, #000 calc(100% - 56px), transparent 100%),
    linear-gradient(to bottom, transparent 0, #000 14px, #000 calc(100% - 30px), transparent 100%);
  mask-composite: intersect;
}

.case-reel-viewport::before,
.case-reel-viewport::after {
  content: none;
}

/* a blurred card inside an already blurred sheet adds cost and no look */
.case-open-prize-card,
.case-open-reel-wrap {
  -webkit-backdrop-filter: none;
  backdrop-filter: none;
}

/* weak devices (every Android runs html.android-lite): no blur, no endless glow/box-shadow animation, no height animation */
html.android-lite .page-case-open .case-sheet,
html.android-lite .page-case-open .case-open-topbar *,
html.android-lite .page-case-open .case-live-strip,
html.android-lite .page-case-open .case-open-prize-card {
  -webkit-backdrop-filter: none !important;
  backdrop-filter: none !important;
}

html.android-lite .page-case-open .case-sheet {
  background: linear-gradient(180deg, rgba(20, 14, 46, 1) 0%, rgba(10, 6, 24, 1) 100%);
  transition: none;
  will-change: auto;
}

/* endless pulses (online dot, live dot, pointer glow, sparkles, win rays/glow) play once on weak devices instead of looping forever */
html.android-lite .page-case-open,
html.android-lite .page-case-open *,
html.android-lite .page-case-open *::before,
html.android-lite .page-case-open *::after {
  animation-iteration-count: 1 !important;
}

@media (prefers-reduced-motion: reduce) {
  .page-case-open,
  .page-case-open *,
  .page-case-open *::before,
  .page-case-open *::after {
    animation-iteration-count: 1 !important;
  }
}

