.coin-shop .store-cta { position: fixed; left: 50%; transform: translateX(-50%); bottom: calc(var(--bottom-nav-height, 76px) + env(safe-area-inset-bottom, 0px) + 12px); z-index: 45; display: flex; align-items: center; gap: 6px; padding: 5px; border-radius: 999px; background: rgba(20, 11, 44, 0.86); backdrop-filter: blur(14px); -webkit-backdrop-filter: blur(14px); border: 1px solid rgba(255, 255, 255, 0.14); box-shadow: 0 8px 22px rgba(0, 0, 0, 0.45); animation: storeCtaIn 0.2s ease both; max-width: calc(100% - 24px); }
