/* Waves */
.profile-hero[data-seller-bg="seller_bg_waves"] {
  background:
    radial-gradient(120% 95% at 14% 6%, rgba(82, 118, 162, 0.2) 0%, rgba(82, 118, 162, 0.08) 44%, transparent 74%),
    radial-gradient(100% 80% at 86% 86%, rgba(47, 166, 177, 0.12) 0%, rgba(47, 166, 177, 0.06) 35%, transparent 74%),
