@media (prefers-reduced-motion: reduce) {
  .seller-card[data-seller-bg="seller_bg_waves"],
  .profile-hero[data-seller-bg="seller_bg_waves"] {
    animation: none;
  }
}

/* Particles */
.profile-hero[data-seller-bg="seller_bg_particles"] {
  background:
    radial-gradient(2px 2px at 15% 25%, rgba(255, 215, 0, 0.8), transparent),
    radial-gradient(2px 2px at 85% 75%, rgba(255, 215, 0, 0.6), transparent),
    radial-gradient(1.5px 1.5px at 45% 15%, rgba(255, 255, 255, 0.9), transparent),
    radial-gradient(2px 2px at 25% 85%, rgba(124, 92, 255, 0.8), transparent),
    radial-gradient(1.5px 1.5px at 75% 35%, rgba(31, 230, 209, 0.7), transparent),
    radial-gradient(2px 2px at 55% 65%, rgba(255, 77, 141, 0.6), transparent),
    radial-gradient(1px 1px at 35% 45%, rgba(255, 255, 255, 0.5), transparent),
    radial-gradient(1.5px 1.5px at 65% 95%, rgba(255, 215, 0, 0.7), transparent),
    linear-gradient(165deg, rgba(16, 12, 35, 0.95), rgba(26, 18, 52, 0.98));
}

/* Ambient background motion: same behavior in listing card, private and public profile */
.seller-card[data-seller-bg="seller_bg_stars"],
.profile-hero[data-seller-bg="seller_bg_stars"],
