/* =====================================================
   PROFILE HERO EFFECTS (animations from shop)
   ===================================================== */

/* Scan-line effect */
.profile-hero[data-seller-effect="seller_effect_pulse"] {
  position: relative;
  overflow: hidden;
}

.profile-hero[data-seller-effect="seller_effect_pulse"]::after {
  content: "";
  position: absolute;
  inset: -38% -62%;
  border-radius: inherit;
  background: linear-gradient(
    105deg,
    transparent 44%,
    rgba(170, 230, 255, 0.08) 48%,
    rgba(255, 255, 255, 0.24) 50%,
    rgba(170, 230, 255, 0.08) 52%,
    transparent 56%
  );
  transform: translateX(-58%) rotate(9deg);
  animation: sellerScanLine 4.6s ease-in-out infinite;
  pointer-events: none;
  z-index: 0;
}

@keyframes profile-pulse {
  0%, 100% {
    box-shadow: 0 0 0 0 rgba(124, 92, 255, 0.35), 0 8px 24px rgba(124, 92, 255, 0.1);
  }
  50% {
    box-shadow: 0 0 0 6px rgba(124, 92, 255, 0), 0 8px 24px rgba(124, 92, 255, 0.2);
  }
}

/* Parallax mist effect */
.profile-hero[data-seller-effect="seller_effect_rainbow"] {
  position: relative;
  overflow: hidden;
  isolation: isolate;
  contain: paint;
  border-radius: 24px;
  clip-path: inset(0 round 24px);
}

.profile-hero[data-seller-effect="seller_effect_rainbow"]::after {
  content: "";
  position: absolute;
  inset: -14%;
  border-radius: inherit;
  background:
    radial-gradient(58% 52% at 18% 18%, rgba(129, 114, 255, 0.28), transparent 76%),
    radial-gradient(54% 48% at 82% 82%, rgba(77, 205, 255, 0.22), transparent 74%),
    radial-gradient(46% 40% at 56% 26%, rgba(255, 132, 205, 0.2), transparent 72%),
    radial-gradient(34% 32% at 70% 40%, rgba(122, 233, 255, 0.15), transparent 75%);
  filter: saturate(128%) contrast(1.06);
  mix-blend-mode: screen;
  animation: sellerMistDrift 9.2s cubic-bezier(0.42, 0, 0.24, 1) infinite alternate;
  opacity: 1;
  pointer-events: none;
  z-index: 1;
  will-change: transform, opacity, filter;
  transform: translateZ(0);
}

/* Neon frame effect */
.profile-hero[data-seller-effect="seller_effect_glow"]::before {
  content: "";
  position: absolute;
  inset: -1px;
  border-radius: inherit;
  border: 1px solid rgba(132, 210, 255, 0.55);
  box-shadow:
    0 0 0 1px rgba(124, 92, 255, 0.25),
    0 0 16px rgba(98, 177, 255, 0.25),
    0 0 30px rgba(124, 92, 255, 0.2);
  animation: sellerNeonFrame 3.8s ease-in-out infinite;
  pointer-events: none;
  z-index: 1;
}

.profile-hero[data-seller-effect="seller_effect_glow"] .profile-avatar-ring {
  box-shadow: 0 0 12px rgba(132, 210, 255, 0.24), 0 0 22px rgba(124, 92, 255, 0.18);
}

@keyframes profile-avatar-glow {
  0% { box-shadow: 0 0 18px rgba(124, 92, 255, 0.5), 0 0 35px rgba(124, 92, 255, 0.25); }
  100% { box-shadow: 0 0 25px rgba(124, 92, 255, 0.7), 0 0 50px rgba(124, 92, 255, 0.4); }
}

/* Sparkle effect for profile hero */
.profile-hero[data-seller-effect="seller_effect_sparkle"] {
  position: relative;
}

.profile-hero[data-seller-effect="seller_effect_sparkle"]::after {
  display: none;
}

.profile-hero[data-seller-effect="seller_effect_sparkle"]::before {
  display: none;
}

.profile-hero[data-seller-effect="seller_effect_hologram"] {
  position: relative;
  overflow: hidden;
}

.profile-hero[data-seller-effect="seller_effect_hologram"]::before {
  content: "";
