}

.profile-badges .uni-label,
.profile-badges .family-inline-badge,
.public-label-row .uni-label,
.public-label-row .family-inline-badge,
.seller-badges .uni-label,
.seller-badges .family-inline-badge {
  height: 38px;
  min-height: 38px;
