  overflow: hidden;
}

.profile-promo-card::before {
  content: "";
  position: absolute;
  inset: -1px;
  border-radius: 17px;
  padding: 1px;
  background: conic-gradient(
    from var(--promo-shimmer-angle, 0deg),
    rgba(124, 92, 255, 0.15) 0%,
