/* ============================================
   UNIVERSAL LABEL COMPONENT
   Единый стиль лейбла для всего приложения
   ============================================ */

.uni-label {
  --label-grad: linear-gradient(135deg, #6f4cff 0%, #9a7bff 100%);
  --label-glow: rgba(124, 92, 255, 0.42);
  --label-text: #fff;

  position: relative;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 8px 16px;
  border-radius: 50px;
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.7px;
  text-transform: uppercase;
  color: var(--label-text);
  background: var(--label-grad);
  border: none;
  box-shadow:
    0 4px 15px var(--label-glow),
    inset 0 1px 0 rgba(255, 255, 255, 0.2);
  overflow: hidden; /* FIX: prevent shine from overflowing */
  isolation: isolate;
  transition: all 0.3s ease;
}

/* Shine effect - subtle shimmer */
.uni-label::before {
  content: '';
  position: absolute;
  top: 0;
  left: -100%;
  width: 60%;
  height: 100%;
  background: linear-gradient(
    90deg,
    transparent,
    rgba(255, 255, 255, 0.25),
    transparent
  );
  border-radius: 50px;
  animation: label-shine 4s ease-in-out infinite;
}

@keyframes label-shine {
  0% { left: -60%; }
  50%, 100% { left: 160%; }
}

/* Remove sparkle by default */
.uni-label::after {
  display: none;
}

/* Profile badge variant — uniform size */
.uni-label--badge {
  padding: 6px 14px;
  font-size: 10px;
  letter-spacing: 0.6px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

/* Compact variant */
.uni-label--sm {
  padding: 6px 14px;
  font-size: 9px;
  letter-spacing: 0.8px;
}

/* Extra small for tight spaces */
.uni-label--xs {
  padding: 4px 10px;
  font-size: 8px;
  letter-spacing: 0.5px;
}

.uni-label--xs::before {
  display: none;
}

/* No shine variant */
.uni-label--static::before {
  display: none;
}

/* ============================================
   Label Color Styles (магазин косметики)
   ============================================ */

/* Default / Amethyst */
.uni-label[data-style="default"],
.uni-label[data-style="label_style_amethyst"] {
  --label-grad: linear-gradient(135deg, #6f4cff 0%, #9a7bff 100%);
  --label-glow: rgba(124, 92, 255, 0.42);
  --label-text: #fff;
}

/* Aurora - Cyan to Purple */
.uni-label[data-style="label_style_aurora"] {
  --label-grad: linear-gradient(135deg, #1FE6D1 0%, #7C5CFF 100%);
  --label-glow: rgba(31, 230, 209, 0.4);
  --label-text: #fff;
}

/* Sunset - Pink to Orange */
.uni-label[data-style="label_style_sunset"] {
  --label-grad: linear-gradient(135deg, #FF4D8D 0%, #FFB340 100%);
  --label-glow: rgba(255, 77, 141, 0.4);
  --label-text: #fff;
}

/* Ice - Light blue gradient */
.uni-label[data-style="label_style_ice"] {
  --label-grad: linear-gradient(135deg, #E0F7FF 0%, #B8E0FF 100%);
  --label-glow: rgba(184, 224, 255, 0.35);
  --label-text: #1a2040;
}

/* Lime - Green to Cyan */
.uni-label[data-style="label_style_lime"] {
  --label-grad: linear-gradient(135deg, #B6FF3B 0%, #1FE6D1 100%);
  --label-glow: rgba(182, 255, 59, 0.35);
  --label-text: #1a2040;
}

/* Goldrush - Gold gradient */
.uni-label[data-style="label_style_goldrush"] {
  --label-grad: linear-gradient(135deg, #FFD56A 0%, #FFB340 100%);
  --label-glow: rgba(255, 179, 64, 0.4);
  --label-text: #2a1a00;
}

/* Ruby - Red to Pink */
.uni-label[data-style="label_style_ruby"] {
  --label-grad: linear-gradient(135deg, #FF4FA3 0%, #FF89D6 100%);
  --label-glow: rgba(255, 79, 163, 0.42);
  --label-text: #fff;
}

/* Ocean - Deep blue */
.uni-label[data-style="label_style_ocean"] {
  --label-grad: linear-gradient(135deg, #4DA3FF 0%, #667EEA 100%);
  --label-glow: rgba(77, 163, 255, 0.4);
  --label-text: #fff;
}

/* Midnight - Dark elegant */
.uni-label[data-style="label_style_midnight"] {
  --label-grad: linear-gradient(135deg, #2D1B69 0%, #11998E 100%);
  --label-glow: rgba(45, 27, 105, 0.4);
  --label-text: #fff;
}

/* Custom two-color gradient (shop picker) */
.uni-label[data-style="custom"] {
  --label-grad: linear-gradient(
    135deg,
    var(--label-custom-c1, #6f4cff) 0%,
    var(--label-custom-c2, #9a7bff) 100%
  );
  --label-glow: rgba(124, 92, 255, 0.42);
  --label-text: #fff;
}

/* No sparkle variant */
.uni-label--no-sparkle::after {
  display: none;
}

/* No shine variant */
.uni-label--no-shine::before {
  display: none;
}

/* Static - no animations */
.uni-label--static::before,
.uni-label--static::after {
  animation: none;
  display: none;
}

