.image-viewer {
  background: transparent;
  align-items: center;
  padding: 0;
}

.image-viewer .modal-card {
  display: none;
}

.image-viewer-backdrop {
  position: absolute;
  inset: 0;
  background: rgba(5, 3, 12, 0.95);
  backdrop-filter: blur(20px);
  -webkit-backdrop-filter: blur(20px);
}

.image-viewer-container {
  position: relative;
  width: 100%;
  height: 100%;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 60px 16px 100px;
}

.image-viewer-close {
  position: absolute;
  top: max(16px, env(safe-area-inset-top));
  right: 16px;
  width: 44px;
  height: 44px;
  border-radius: 50%;
  border: 1px solid rgba(255, 255, 255, 0.15);
  background: rgba(255, 255, 255, 0.08);
  color: #fff;
  display: grid;
  place-items: center;
  cursor: pointer;
  transition: all 0.2s ease;
  z-index: 10;
}

.image-viewer-close:hover {
  background: rgba(255, 255, 255, 0.15);
  border-color: rgba(255, 255, 255, 0.25);
}

.image-viewer-counter {
  position: absolute;
  top: max(24px, env(safe-area-inset-top));
  left: 50%;
  transform: translateX(-50%);
  padding: 8px 16px;
  border-radius: 20px;
  background: rgba(255, 255, 255, 0.1);
  color: rgba(255, 255, 255, 0.9);
  font-size: 13px;
  font-weight: 500;
  z-index: 10;
}

.image-viewer-wrapper {
  position: relative;
  width: 100%;
  max-width: 800px;
  height: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  overflow: hidden;
  touch-action: none;
}

.image-viewer-wrapper img {
  max-width: 100%;
  max-height: 100%;
  object-fit: contain;
  border-radius: 8px;
  transition: transform 0.15s ease-out;
  user-select: none;
  -webkit-user-drag: none;
  touch-action: none;
}

.image-viewer-controls {
  position: absolute;
  bottom: max(24px, env(safe-area-inset-bottom));
  left: 50%;
  transform: translateX(-50%);
  display: flex;
  gap: 8px;
  padding: 8px;
  border-radius: 20px;
  background: rgba(20, 15, 40, 0.9);
  border: 1px solid rgba(124, 92, 255, 0.25);
  z-index: 10;
}

.image-viewer-btn {
  width: 48px;
  height: 40px;
  border-radius: 12px;
  border: none;
  background: rgba(124, 92, 255, 0.15);
  color: rgba(220, 200, 255, 0.9);
  display: grid;
  place-items: center;
  cursor: pointer;
  transition: all 0.2s ease;
  font-size: 13px;
  font-weight: 600;
}

.image-viewer-btn:hover {
  background: rgba(124, 92, 255, 0.3);
}

.image-viewer-btn svg {
  width: 20px;
  height: 20px;
  stroke: currentColor;
}

.image-viewer-hint {
  position: absolute;
  bottom: max(80px, calc(env(safe-area-inset-bottom) + 56px));
  left: 50%;
  transform: translateX(-50%);
  font-size: 12px;
  color: rgba(180, 160, 220, 0.5);
  z-index: 10;
  white-space: nowrap;
}

