/* Global UI loader (market style) */
.ui-loader-overlay {
  position: fixed;
  inset: 0;
  z-index: 2600;
  display: grid;
  place-items: center;
  background:
    radial-gradient(120% 80% at 50% 100%, rgba(124, 92, 255, 0.2), rgba(10, 6, 20, 0.72) 60%),
    rgba(8, 5, 16, 0.62);
  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
  opacity: 0;
  pointer-events: none;
  transition: opacity 220ms ease;
}

.ui-loader-overlay.show {
  opacity: 1;
  pointer-events: auto;
}

body.ui-loading .action-bar,
body.ui-loading #createFab,
body.ui-loading #marketScrollTop {
  opacity: 0 !important;
  pointer-events: none !important;
}

/* While the init overlay fades out, the navbar is already complete beneath it.
   Its own 220ms opacity fade would otherwise run after the page is revealed. */
body.ui-loading-exit .action-bar {
  transition:
    transform 260ms cubic-bezier(0.2, 0.8, 0.2, 1),
    opacity 0s !important;
}

.ui-loader-card {
  width: min(280px, calc(100% - 40px));
  padding: 18px 16px;
  border-radius: 20px;
  border: 1px solid rgba(150, 117, 255, 0.4);
  background:
    radial-gradient(130% 90% at 90% 100%, rgba(31, 230, 209, 0.12), transparent 60%),
    linear-gradient(155deg, rgba(39, 21, 79, 0.9), rgba(15, 9, 33, 0.94));
  box-shadow:
    0 20px 44px rgba(0, 0, 0, 0.42),
    0 0 34px rgba(124, 92, 255, 0.2),
    inset 0 1px 0 rgba(255, 255, 255, 0.07);
  text-align: center;
}

.ui-loader-spinner {
  width: 54px;
  height: 54px;
  margin: 2px auto 12px;
  border-radius: 999px;
  border: 2px solid rgba(255, 255, 255, 0.16);
  border-top-color: rgba(141, 220, 255, 0.95);
  border-right-color: rgba(124, 92, 255, 0.95);
  box-shadow:
    0 0 22px rgba(124, 92, 255, 0.35),
    inset 0 0 12px rgba(124, 92, 255, 0.22);
  animation: uiLoaderSpin 1.1s linear infinite;
}

.ui-loader-title {
  font-size: 16px;
  font-weight: 800;
  color: rgba(247, 242, 255, 0.97);
  line-height: 1.2;
}

.ui-loader-sub {
  margin-top: 4px;
  font-size: 12px;
  color: rgba(198, 179, 255, 0.8);
}

@keyframes uiLoaderSpin {
  to {
    transform: rotate(360deg);
  }
}

