/* Activity tab: list-style rows */
.page-coins {
  position: relative;
  overflow: visible;
  padding-bottom: calc(12px + env(safe-area-inset-bottom)) !important;
}

.page-coins::before,
.page-coins::after {
  content: "";
  position: absolute;
  pointer-events: none;
  z-index: 0;
  filter: blur(8px);
}

.page-coins::before {
  inset: 2% auto auto -24%;
  width: 124vw;
  height: 42vh;
  background: radial-gradient(circle, rgba(126, 92, 248, 0.22) 0%, rgba(126, 92, 248, 0) 74%);
}

.page-coins::after {
  inset: auto -22% 10% auto;
  width: 112vw;
  height: 54vh;
  background: radial-gradient(circle, rgba(172, 124, 255, 0.17) 0%, rgba(172, 124, 255, 0) 76%);
}

.page-coins.active {
  gap: 10px !important;
  min-height: 0;
}

.page-coins .mcoin-page-shell {
  position: relative;
  z-index: 1;
  border-radius: 0;
  overflow: visible;
  border: 0;
  background: transparent;
  backdrop-filter: none;
  -webkit-backdrop-filter: none;
  box-shadow: none;
}

/* === Compact hero header === */
.page-coins .mcoin-hero {
  padding: 12px 14px 10px;
  border-radius: 0;
  border: 0;
  background: transparent;
  box-shadow: none;
}

.page-coins .mcoin-hero-glow,
.page-coins .mcoin-hero-stars {
  display: none;
}

.page-coins .mcoin-hero-center,
.page-coins .mcoin-rocket-wrap,
.page-coins .mcoin-hero-subtitle {
  display: none !important;
}

.page-coins .mcoin-hero-topbar {
  position: static;
  top: auto;
  left: auto;
  right: auto;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
}

.page-coins .mcoin-hero-title {
  font-size: 18px;
  font-weight: 800;
  color: rgba(255, 255, 255, 0.95);
  line-height: 1;
  letter-spacing: -0.01em;
  text-shadow: none;
  flex: 1;
  text-align: center;
}

.page-coins .mcoin-balance-wrap {
  background: rgba(255, 255, 255, 0.08);
  border-color: rgba(255, 255, 255, 0.12);
  box-shadow: none;
}

.page-coins .mcoin-balance-wrap::before {
  background: #ffd271;
  box-shadow: 0 0 6px rgba(255, 210, 113, 0.4);
}

.page-coins .mcoin-history-btn {
  background: rgba(255, 255, 255, 0.08);
  border-color: rgba(255, 255, 255, 0.12);
  color: rgba(255, 255, 255, 0.88);
  box-shadow: none;
}

.page-coins .mcoin-history-btn:hover {
  background: linear-gradient(145deg, rgba(138, 114, 236, 0.5), rgba(94, 76, 188, 0.4));
  border-color: rgba(190, 174, 255, 0.46);
}

/* ===== ACTIVITY TAB — TILE GRID (reference design) ===== */

.page-coins .mcoin-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 10px;
  margin-top: 0;
  padding: 0 2px;
  background: transparent;
  border: 0;
  box-shadow: none;
  backdrop-filter: none;
  -webkit-backdrop-filter: none;
}

/* --- Base tile card --- */
.page-coins .mcoin-card,
.page-coins .mcoin-card--promo,
.page-coins .mcoin-card--tasks,
.page-coins .mcoin-card--inventory,
.page-coins .mcoin-card--referrals,
.page-coins .mcoin-card--favorites,
.page-coins .mcoin-card--chests,
.page-coins .mcoin-card--shop,
.page-coins .mcoin-card--vip,
.page-coins .mcoin-card--promocodes {
  position: relative;
  display: flex !important;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  min-height: 118px;
  padding: 20px 12px 16px;
  border-radius: 18px;
  background: rgba(16, 12, 28, 0.88) !important;
  border: 1.5px solid rgba(255, 255, 255, 0.07) !important;
  box-shadow: none !important;
  cursor: pointer;
  transition: transform 0.18s ease, box-shadow 0.18s ease;
  grid-template-columns: unset !important;
  gap: 0 !important;
}

.page-coins .mcoin-card:active {
  transform: scale(0.95);
}

.page-coins .mcoin-card::before {
  display: none !important;
}

/* --- Circular icon --- */
.page-coins .mcoin-card-icon,
.page-coins .mcoin-card--promo .mcoin-card-icon,
.page-coins .mcoin-card--tasks .mcoin-card-icon,
.page-coins .mcoin-card--inventory .mcoin-card-icon,
