  height: 52px !important;
  border-radius: 50% !important;
  background: rgba(255, 255, 255, 0.04) !important;
  border: 2px solid rgba(255, 255, 255, 0.12) !important;
  display: grid !important;
  place-items: center;
  margin-bottom: 10px;
  padding: 0;
  flex-shrink: 0;
}

.page-coins .mcoin-card-icon svg {
  width: 26px;
  height: 26px;
