/* ============================================
   UNIFIED PROFILE — single-screen theme
   ============================================ */

/* Full-bleed: fixed pseudo-element covers entire viewport behind body bg */
.page-profile,
.page-public {
  position: relative;
  margin-left: 0;
  margin-right: 0;
  padding-left: 16px;
  padding-right: 16px;
}

.page-profile::before,
.page-public::before {
  display: none !important;
}

/* Override page-profile.active gap/padding that creates card spacing */
.page-profile.active,
.page-public.active {
  gap: 0 !important;
  padding-inline: 0 !important;
  padding-top: 0 !important;
}

/* Tabs: breathing room + align width with hero photo */
.page-profile .profile-sections-tabs {
  margin-top: 14px;
  margin-left: 18px;
  margin-right: 18px;
  width: auto;
  /* See "Section cards": no backdrop-filter inside the fading profile layer. */
  backdrop-filter: none !important;
  -webkit-backdrop-filter: none !important;
}

/* Only profile content fades. The root page and fixed gradient layer never
   receive animation, opacity, or transform. */
.page-profile.active .profile-content-layer.swipe-enter-left,
.page-profile.active .profile-content-layer.swipe-enter-right {
  animation: pageEnter 240ms cubic-bezier(0.22, 0.8, 0.3, 1) backwards !important;
}

html.android-lite .page-profile.active .profile-content-layer.swipe-enter-left,
html.android-lite .page-profile.active .profile-content-layer.swipe-enter-right {
  animation: profileFadeIn 160ms ease !important;
}

html.android-lite .page-profile.active .profile-content-layer.swipe-enter-left > *,
html.android-lite .page-profile.active .profile-content-layer.swipe-enter-right > * {
  animation: none;
}

.profile-content-layer {
  display: grid;
  align-content: start;
  gap: 0;
  width: 100%;
  min-width: 0;
  transform: none;
}

@keyframes profileFadeIn {
  from { opacity: 0; }
  to { opacity: 1; }
}

/* Hero: full-width, NO card, NO overflow clip */
.page-profile .profile-hero,
.page-public .profile-hero {
  border-radius: 0 !important;
  border: none !important;
  background: transparent !important;
  box-shadow: none !important;
  overflow: visible !important;
  isolation: auto !important;
  margin-bottom: 0;
  padding-top: 0;
  width: calc(100% - 4px) !important;
  margin-left: auto !important;
  margin-right: auto !important;
  padding-left: 16px;
  padding-right: 16px;
}

/* Hero ::after and hero-bg hidden — clean background */
.page-profile .profile-hero::after,
.page-public .profile-hero::after {
  display: none !important;
}

.page-profile .profile-hero::before,
.page-public .profile-hero::before {
  display: none !important;
}

.page-profile .profile-hero-bg,
.page-public .profile-hero-bg {
  display: none !important;
}

.page-profile .profile-hero-effect,
.page-public .profile-hero-effect {
  display: none !important;
}

/* FAB on profile: same glass style as base */

/* Action buttons (bell, chat, settings): transparent, no visible box */
.page-profile .profile-action-btn {
  background: transparent !important;
  border: none !important;
  box-shadow: none !important;
}

.page-profile .profile-action-btn:hover,
.page-profile .profile-action-btn:active {
  background: rgba(var(--pc1), 0.10) !important;
}

/* Label-only hero variant also loses card styling */
.page-profile .profile-hero.profile-hero--label-only .profile-action-btn {
  background: transparent !important;
  border: none !important;
}

/* No separator — elements flow as one surface */
.page-profile .profile-reputation-card {
  margin-top: 0 !important;
  padding-top: 12px;
  border: none !important;
}

/* Section cards: glass style.
   No backdrop-filter here on purpose: these cards sit on the smooth profile
   gradient (nothing to frost), and every backdrop-filter element inside the
   fading profile layer is a compositing dependency that showed a one-frame
   white backdrop on Telegram WebView at first entry. The translucent fill and
   border carry the glass look. */
.page-profile .profile-promo-card {
