.level-row-title { color: #fff; }
.level-row-bar { background: rgba(255, 255, 255, 0.1); }
.level-row-bar i { background: linear-gradient(90deg, rgba(var(--pc1, 124, 92, 255), 0.7), rgb(var(--pc1, 124, 92, 255))); }
