/* ===== «Путь уровней» (Duolingo structure, our brand): pinned section banner, the path, one plate at the bottom ===== */
.level-path-screen { position: fixed; inset: 0; z-index: 3000; display: none; flex-direction: column; background: radial-gradient(circle 1400px at 50% 0%, #2a1757, #080410); color: #f4eeff; --lp: var(--pc1, 124, 92, 255); }
.level-path-screen.show { display: flex; }
body.level-path-open { overflow: hidden; }
.level-path-banner { flex: none; margin: calc(18px + var(--tg-safe-top-offset, 0px) + var(--app-brand-top-height, 44px) + 4px) 16px 0; padding: 12px 16px 14px; border-radius: 18px; color: #fff; background: linear-gradient(180deg, rgb(var(--lp)), rgba(var(--lp), 0.78)); box-shadow: 0 5px 0 rgba(var(--lp), 0.45), 0 10px 24px rgba(0, 0, 0, 0.35); z-index: 2; }
.level-path-banner small { display: block; font-size: 11.5px; font-weight: 800; letter-spacing: 0.1em; text-transform: uppercase; opacity: 0.8; }
.level-path-banner-name { margin-top: 2px; font-size: 20px; font-weight: 800; }
.level-path-scroll { flex: 1; min-height: 0; overflow-y: auto; scrollbar-width: none; padding: 14px 0 250px; }
.level-path-scroll::-webkit-scrollbar { display: none; }
.level-path-nodes { display: flex; flex-direction: column; align-items: center; padding: 6px 0 14px; }
/* a section divider like Duolingo's: line, the section name, line */
.level-path-sep { display: flex; align-items: center; gap: 14px; margin: 26px 24px 8px; }
.level-path-sep::before, .level-path-sep::after { content: ""; flex: 1; height: 2px; border-radius: 1px; background: rgba(255, 255, 255, 0.14); }
.level-path-sep span { font-size: 15px; font-weight: 800; color: rgba(255, 255, 255, 0.5); white-space: nowrap; }
.level-path-row { position: relative; height: 84px; width: 100%; max-width: 440px; display: flex; justify-content: center; align-items: center; }
.level-path-node { position: relative; width: 58px; height: 58px; border-radius: 50%; display: grid; place-items: center; font-weight: 800; font-size: 19px; background: #2a1a52; color: #a79bc9; border: 3px solid rgba(124, 92, 255, 0.4); box-shadow: 0 6px 0 rgba(20, 10, 45, 0.9); cursor: pointer; -webkit-tap-highlight-color: transparent; }
.level-path-node.done { background: linear-gradient(180deg, rgba(var(--lp), 0.95), rgba(var(--lp), 0.7)); color: #fff; border-color: rgba(255, 255, 255, 0.45); box-shadow: 0 6px 0 rgba(var(--lp), 0.4); }
.level-path-node.cur { width: 72px; height: 72px; font-size: 24px; background: linear-gradient(180deg, #fff, #e3d9ff); color: rgb(var(--lp)); border: 0; box-shadow: 0 7px 0 rgba(var(--lp), 0.5), 0 0 0 8px rgba(var(--lp), 0.3); }
.level-path-node.is-picked { box-shadow: 0 6px 0 rgba(20, 10, 45, 0.9), 0 0 0 5px rgba(var(--lp), 0.45); }
.level-path-jump { position: absolute; right: 18px; bottom: 214px; z-index: 3; width: 46px; height: 46px; border-radius: 14px; border: 1px solid rgba(255, 255, 255, 0.14); background: rgba(30, 18, 55, 0.85); color: #fff; font-size: 20px; }
.level-path-jump[hidden] { display: none; }
.level-path-jump[data-dir="up"] { transform: rotate(180deg); }
.level-path-dock { position: absolute; left: 12px; right: 12px; bottom: calc(env(safe-area-inset-bottom, 0px) + 14px); z-index: 2; display: flex; flex-direction: column; gap: 10px; padding: 14px; border-radius: 22px; background: rgba(30, 18, 55, 0.72); backdrop-filter: blur(22px) saturate(1.3); -webkit-backdrop-filter: blur(22px) saturate(1.3); border: 1px solid rgba(255, 255, 255, 0.12); box-shadow: 0 14px 40px rgba(0, 0, 0, 0.45); }
.level-path-dock-top { display: flex; align-items: center; gap: 14px; }
.level-path-dock-info { flex: 1; min-width: 0; display: flex; flex-direction: column; gap: 3px; }
.level-path-dock-info b { font-size: 17px; }
.level-path-dock-info small { font-size: 13px; opacity: 0.75; }
.level-path-prize { padding: 9px 12px; border-radius: 12px; background: rgba(255, 255, 255, 0.06); font-size: 13.5px; font-weight: 600; color: #d9ccff; }
.level-path-prize.is-here { background: rgba(var(--lp), 0.22); color: #fff; }
.level-path-custom { width: 100%; }
#customLabelModal .input { width: 100%; margin-top: 10px; }
#customLabelModal { z-index: 3100; }

/* figures in the empty side space of the path (Duolingo-style), tinted towards the brand violet */
.level-path-char { position: absolute; top: -34px; max-width: 112px; max-height: 150px; width: auto; height: auto; object-fit: contain; pointer-events: none; opacity: 0.92; filter: hue-rotate(62deg) saturate(0.8) brightness(0.95); }
