@keyframes levelCartPulse { 50% { transform: scale(1.08); filter: grayscale(0.2) brightness(1); } }
.level-row-gift { flex: none; padding: 3px 9px; border-radius: 999px; font-size: 12px; font-weight: 800; color: #fff; background: rgba(var(--pc1, 124, 92, 255), 0.35); }


/* Prize opening: the same full-screen win scene as the cases (rays, glow, prize), one tidy centred group */
.lr-overlay { justify-content: center; }
.lr-overlay .lr-body { gap: 10px; margin: 0; max-width: 340px; }
