.lr-cart { position: relative; width: 128px; height: 116px; object-fit: contain; cursor: pointer; filter: grayscale(0.55) brightness(0.92) drop-shadow(0 8px 24px rgba(0, 0, 0, 0.4)); animation: lrIdle 2.2s ease-in-out infinite; }
.lr-flash { position: absolute; width: 50px; height: 50px; border-radius: 50%; background: radial-gradient(circle, #fff, rgba(255, 255, 255, 0) 70%); opacity: 0; pointer-events: none; }
.lr-bit { position: absolute; left: 50%; top: 52%; width: 9px; height: 9px; border-radius: 3px; background: hsl(var(--h), 85%, 70%); opacity: 0; pointer-events: none; animation: lrBit 1.05s ease-out 0.42s both; }
.lr-hint { font-size: 16px; font-weight: 700; margin: 0; color: rgba(255, 255, 255, 0.78); }
