.lr-prize { display: flex; align-items: center; justify-content: center; gap: 10px; padding: 10px 14px; border-radius: 14px; font-size: 16px; font-weight: 800; color: #fff; background: rgba(255, 255, 255, 0.1); border: 1px solid rgba(255, 255, 255, 0.2); opacity: 0; }
.lr-prize span { font-size: 22px; }
.lr-btn { margin-top: 8px; }
.lr-overlay.is-opening .lr-cart { animation: lrShake 0.5s ease; }
.lr-overlay.is-opening .lr-flash { animation: lrFlash 0.9s ease-out 0.4s both; }
.lr-overlay.is-revealed .lr-cart { filter: drop-shadow(0 8px 28px rgba(0, 0, 0, 0.35)); animation: lrPop 0.65s cubic-bezier(0.34, 1.5, 0.64, 1); cursor: default; }
.lr-overlay.is-revealed .lr-prize { animation: lrPrize 0.55s cubic-bezier(0.2, 1.3, 0.4, 1) both; animation-delay: calc(0.45s + var(--i) * 0.16s); }
.lr-overlay .lr-reveal-in { animation: caseWinSlideDown 500ms cubic-bezier(0.22, 0.68, 0, 1.2) both; }
.level-path-claimall { width: 100%; height: 44px; border: 0; border-radius: 14px; font-size: 15px; font-weight: 800; color: #fff; background: linear-gradient(180deg, #8b5cf6, #6d28d9); box-shadow: 0 8px 18px rgba(109, 40, 217, 0.4); }
@keyframes lrIdle { 0%, 100% { transform: translateY(0) rotate(0); } 50% { transform: translateY(-9px) rotate(-2.5deg); } }
@keyframes lrShake { 12% { transform: translateX(-9px) rotate(-6deg); } 30% { transform: translateX(9px) rotate(6deg); } 48% { transform: translateX(-7px) rotate(-4deg) scale(1.04); } 66% { transform: translateX(6px) rotate(3deg) scale(1.08); } 85% { transform: scale(1.14); } }
@keyframes lrFlash { 0% { opacity: 0.95; transform: scale(0.4); } 100% { opacity: 0; transform: scale(7); } }
@keyframes lrPop { 0% { transform: scale(0.82); } 100% { transform: scale(1); } }
@keyframes lrPrize { 0% { opacity: 0; transform: translateY(18px) scale(0.85); } 100% { opacity: 1; transform: none; } }
@keyframes lrBit { 0% { opacity: 1; transform: translate(0, 0) rotate(0) scale(1); } 100% { opacity: 0; transform: translate(var(--dx), var(--dy)) rotate(var(--r)) scale(0.6); } }
@media (prefers-reduced-motion: reduce) { .lr-overlay *, .level-path-cart img { animation: none !important; } .lr-overlay.is-revealed .lr-prize { opacity: 1; } }

