}

.capture-confetti-piece.is-star {
  width: 13px;
  height: 13px;
  clip-path: polygon(50% 0%, 62% 38%, 100% 38%, 69% 60%, 80% 100%, 50% 75%, 20% 100%, 31% 60%, 0 38%, 38% 38%);
