.capture-business-node::before {
  display: none;
}

.capture-business-node.active::before,
.capture-business-node:hover::before {
  opacity: 0;
}

.capture-business-node-name {
  position: absolute;
  left: 50%;
  top: 116px;
  transform: translateX(-50%);
  width: 170px;
  max-width: 170px;
  font-size: 13px;
  font-weight: 800;
  line-height: 1.12;
  color: #fff;
