  max-width: 170px;
  font-size: 12px;
  font-weight: 700;
  line-height: 1.12;
  color: rgba(200, 190, 240, 0.86);
  text-align: center;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  text-shadow: 0 1px 4px rgba(0, 0, 0, 0.35);
}

.capture-business-node.active .capture-business-node-core {
  box-shadow:
    0 0 0 3px rgba(140, 100, 240, 0.2),
    0 0 32px rgba(120, 80, 230, 0.35),
    0 10px 36px rgba(79, 70, 229, 0.4),
    0 4px 12px rgba(0, 0, 0, 0.25),
    inset 0 -6px 16px rgba(55, 48, 163, 0.45);
}
.capture-business-node.is-mine .capture-business-node-core {
