/* ── Attack Case Overlay — Glassmorphism ── */

.capture-case-overlay {
  position: fixed;
  inset: 0;
  z-index: 1300;
  background: radial-gradient(ellipse at 50% 30%, rgba(88, 40, 180, 0.22) 0%, rgba(5, 3, 18, 0.94) 70%);
  display: flex;
  align-items: center;
  justify-content: center;
  padding: max(10px, env(safe-area-inset-top)) 10px max(10px, env(safe-area-inset-bottom));
  transform: translateZ(0);
}

.capture-case-overlay.leaving {
  opacity: 0;
  transition: opacity 0.25s ease;
}

/* ── Glass Window ── */
.capture-case-window {
  position: relative;
  width: 100%;
  max-width: 420px;
  max-height: min(84vh, 640px);
  border-radius: 28px;
  border: 1px solid rgba(160, 130, 255, 0.22);
  background:
    linear-gradient(168deg,
      rgba(40, 24, 85, 0.97) 0%,
      rgba(18, 10, 45, 0.98) 50%,
      rgba(8, 4, 24, 0.99) 100%);
  box-shadow:
    0 8px 32px rgba(0, 0, 0, 0.5),
    0 32px 80px rgba(0, 0, 0, 0.35),
    inset 0 1px 0 rgba(255, 255, 255, 0.12),
    inset 0 -1px 0 rgba(255, 255, 255, 0.03);
  padding: 22px 18px max(18px, calc(14px + env(safe-area-inset-bottom)));
  display: grid;
  gap: 10px;
  overflow-x: hidden;
  overflow-y: auto;
  -webkit-overflow-scrolling: touch;
  animation: captureCasePopIn 0.32s cubic-bezier(0.34, 1.56, 0.64, 1);
}

/* Glass shimmer highlight on top */
.capture-case-window::before {
  content: "";
  position: absolute;
  top: 0;
  left: 10%;
  right: 10%;
  height: 1px;
  background: linear-gradient(90deg, transparent, rgba(200, 180, 255, 0.5), transparent);
  border-radius: 999px;
}

/* Ambient glow behind window */
.capture-case-window::after {
  content: "";
  position: absolute;
  top: -40%;
  left: -20%;
  width: 140%;
  height: 120%;
  background: radial-gradient(ellipse at 50% 20%, rgba(120, 80, 220, 0.12) 0%, transparent 60%);
  pointer-events: none;
  z-index: -1;
}

/* ── Title & Subtitle ── */
.capture-case-title {
  color: #fff;
  font-size: 20px;
  font-weight: 900;
  text-align: center;
  text-shadow: 0 2px 12px rgba(120, 80, 220, 0.3);
  letter-spacing: 0.02em;
}

.capture-case-sub {
  text-align: center;
  font-size: 12px;
  color: rgba(200, 190, 240, 0.85);
  letter-spacing: 0.01em;
}

/* ── Skip Button — pill glass ── */
.capture-case-skip {
  justify-self: center;
  border: 1px solid rgba(160, 140, 240, 0.3);
  background: rgba(80, 55, 160, 0.55);
  color: rgba(220, 215, 255, 0.95);
  font-size: 11px;
  font-weight: 700;
  padding: 7px 16px;
  border-radius: 999px;
  transition: background 0.2s ease, border-color 0.2s ease;
}

.capture-case-skip:active {
  background: rgba(100, 70, 190, 0.35);
}

.capture-case-skip.hidden {
  display: none;
}

/* ── Wheel Container ── */
.capture-case-wheel-wrap {
  position: relative;
  padding: 14px 6px 10px;
  display: grid;
  place-items: center;
}

.capture-case-wheel {
  width: min(280px, 70vw);
  aspect-ratio: 1 / 1;
  border-radius: 50%;
  position: relative;
  display: grid;
  place-items: center;
  transform: translateZ(0);
}

/* ── Wheel Rail — glass ring ── */
.capture-case-wheel-rail {
  position: absolute;
  inset: 0;
  border-radius: 50%;
  border: 14px solid rgba(30, 22, 55, 0.9);
  box-shadow:
    inset 0 0 0 1px rgba(180, 160, 240, 0.1),
    inset 0 8px 20px rgba(0, 0, 0, 0.4),
    0 0 0 1px rgba(140, 110, 230, 0.12),
    0 12px 36px rgba(0, 0, 0, 0.35);
}

/* ── Wheel Orbit (donut gauge) ── */
.capture-case-wheel-orbit {
  --capture-win-span: 80deg;
  position: absolute;
  inset: 8px;
  border-radius: 50%;
  background: conic-gradient(
    from 0deg,
    #34d97a 0deg,
    #2bc96d var(--capture-win-span),
    #c44468 var(--capture-win-span),
    #a83858 360deg
  );
  -webkit-mask: radial-gradient(
    farthest-side,
    transparent calc(100% - 38px),
    #000 calc(100% - 37px),
    #000 calc(100% - 14px),
    transparent calc(100% - 13px)
  );
  mask: radial-gradient(
    farthest-side,
    transparent calc(100% - 38px),
    #000 calc(100% - 37px),
    #000 calc(100% - 14px),
    transparent calc(100% - 13px)
  );
}

/* ── Threshold Pointer ── */
.capture-case-threshold-pointer {
  position: absolute;
  inset: 8px;
  border-radius: 50%;
  transform: rotate(0deg);
  transform-origin: 50% 50%;
  z-index: 5;
  pointer-events: none;
  opacity: 0;
  transition: opacity 0.2s ease;
}

.capture-case-threshold-pointer.is-visible {
  opacity: 1;
}

.capture-case-threshold-pointer::after {
  content: "";
  position: absolute;
  left: 50%;
  top: -2px;
  width: 4px;
  height: 16px;
  border-radius: 999px;
  background: #f3f7ff;
  transform: translateX(-50%);
  box-shadow: 0 0 10px rgba(255, 255, 255, 0.7), 0 0 20px rgba(200, 180, 255, 0.3);
}

/* ── Roll Info ── */
.capture-case-roll {
  margin-top: 0;
  font-size: 12.5px;
  text-align: center;
  color: rgba(210, 205, 240, 0.85);
  letter-spacing: 0.01em;
}

.capture-case-roll b {
  color: #fff;
  font-weight: 900;
}

.capture-case-roll.is-win b {
  color: #7efcbb;
  text-shadow: 0 0 8px rgba(126, 252, 187, 0.3);
}

.capture-case-roll.is-fail b {
  color: #ff8faa;
  text-shadow: 0 0 8px rgba(255, 143, 170, 0.3);
}

/* ── Roll Pointer (spinning ball) ── */
.capture-case-roll-pointer {
  position: absolute;
  inset: 8px;
  border-radius: 50%;
  z-index: 6;
  transform: rotate(0deg) translateZ(0);
  transform-origin: 50% 50%;
  will-change: transform;
  -webkit-backface-visibility: hidden;
  backface-visibility: hidden;
  pointer-events: none;
}

.capture-case-roll-pointer::after {
  content: "";
  position: absolute;
  left: 50%;
  top: 2px;
  width: 12px;
  height: 12px;
  border-radius: 50%;
  background: radial-gradient(circle at 35% 35%, #fff, #d0c8f0);
  transform: translate(-50%, -50%);
  box-shadow:
    0 0 0 2px rgba(6, 10, 26, 0.7),
    0 0 16px rgba(255, 255, 255, 0.8),
    0 0 30px rgba(160, 130, 255, 0.3);
}

.capture-case-roll-pointer.is-finished::after {
  background: radial-gradient(circle at 35% 35%, #f0f4ff, #c8bef0);
  box-shadow:
    0 0 0 2px rgba(6, 10, 26, 0.6),
    0 0 20px rgba(255, 255, 255, 0.6),
    0 0 40px rgba(160, 130, 255, 0.25);
}

/* ── Wheel Core — frosted glass center ── */
.capture-case-wheel-core {
  position: relative;
  width: 60%;
  aspect-ratio: 1 / 1;
  border-radius: 50%;
  display: grid;
  place-items: center;
  gap: 2px;
  background:
    radial-gradient(circle at 30% 20%, rgba(255, 255, 255, 0.12), transparent 50%),
    linear-gradient(160deg, rgba(28, 18, 52, 0.9) 0%, rgba(16, 10, 34, 0.95) 100%);
  border: 1px solid rgba(160, 130, 240, 0.25);
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.08),
    inset 0 0 20px rgba(100, 70, 200, 0.08),
    0 8px 24px rgba(0, 0, 0, 0.4);
  z-index: 3;
}

.capture-case-wheel-percent {
  color: #fff;
  font-size: clamp(30px, 8.5vw, 44px);
  font-weight: 900;
  letter-spacing: 0.02em;
  line-height: 1;
  text-shadow: 0 2px 16px rgba(140, 110, 240, 0.25);
}

.capture-case-wheel-note {
  color: rgba(190, 180, 235, 0.85);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

/* ── Result Card — frosted glass ── */
.capture-case-result {
  margin-top: 4px;
  border-radius: 18px;
  padding: 16px 14px;
  border: 1px solid rgba(140, 110, 240, 0.2);
  background:
    linear-gradient(160deg,
      rgba(60, 35, 120, 0.3) 0%,
      rgba(30, 18, 70, 0.35) 100%);
  backdrop-filter: blur(16px);
  -webkit-backdrop-filter: blur(16px);
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.08),
    0 4px 20px rgba(0, 0, 0, 0.2);
  display: grid;
  gap: 10px;
  animation: captureCaseResultReveal 0.35s cubic-bezier(0.34, 1.4, 0.64, 1);
}

.capture-case-result.hidden {
  display: none;
}

.capture-case-result-title {
  font-size: 24px;
  font-weight: 900;
  letter-spacing: 0.05em;
  color: #fff;
  text-align: center;
}

.capture-case-result-text {
  color: rgba(215, 210, 245, 0.9);
  font-size: 13px;
  text-align: center;
  line-height: 1.45;
}

.capture-case-result.is-fail .capture-case-result-title {
  color: #ff7da0;
  text-shadow: 0 0 20px rgba(255, 125, 160, 0.35), 0 2px 8px rgba(255, 125, 160, 0.15);
}
.capture-case-result.is-close .capture-case-result-title {
  color: #ffc96e;
  text-shadow: 0 0 20px rgba(255, 201, 110, 0.35), 0 2px 8px rgba(255, 201, 110, 0.15);
}
.capture-case-result.is-win .capture-case-result-title {
  color: #6fffb8;
  text-shadow: 0 0 20px rgba(111, 255, 184, 0.35), 0 2px 8px rgba(111, 255, 184, 0.15);
}
.capture-case-result.is-crit .capture-case-result-title {
  color: #c99dff;
  text-shadow: 0 0 20px rgba(201, 157, 255, 0.35), 0 2px 8px rgba(201, 157, 255, 0.15);
}

/* ── OK Button — gradient glass ── */
.capture-case-ok {
  width: 100%;
  min-height: 48px;
  border-radius: 14px;
  font-weight: 800;
  font-size: 15px;
  border: 1px solid rgba(160, 130, 255, 0.25);
  background: linear-gradient(135deg, rgba(110, 70, 220, 0.45) 0%, rgba(80, 40, 180, 0.35) 100%);
  backdrop-filter: blur(10px);
  -webkit-backdrop-filter: blur(10px);
  color: #fff;
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.12),
    0 4px 16px rgba(90, 50, 200, 0.25);
  transition: background 0.2s ease, box-shadow 0.2s ease;
}

.capture-case-ok:active {
  background: linear-gradient(135deg, rgba(110, 70, 220, 0.6) 0%, rgba(80, 40, 180, 0.5) 100%);
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.08),
    0 2px 8px rgba(90, 50, 200, 0.3);
}

body.capture-case-open {
  overflow: hidden;
}

body.capture-case-open .action-bar {
  opacity: 0;
  pointer-events: none;
}

@keyframes captureCasePopIn {
  from {
    opacity: 0;
    transform: translateY(20px) scale(0.92);
  }
  to {
    opacity: 1;
    transform: translateY(0) scale(1);
  }
}

@keyframes captureCaseResultReveal {
  from {
    opacity: 0;
    transform: translateY(8px) scale(0.96);
  }
  to {
    opacity: 1;
    transform: translateY(0) scale(1);
  }
}

@media (max-width: 380px) {
  .capture-modal {
    max-height: min(86dvh, 680px);
  }

  .capture-modal-body {
    padding: 8px 8px 10px;
  }

  .capture-city-banner {
    width: calc(100% + 16px);
    margin: -8px -8px 0;
    height: 96px;
  }

  .capture-card-title-row {
    flex-direction: column;
    align-items: flex-start;
    gap: 6px;
  }

  .capture-level-pill {
    padding: 4px 8px;
    font-size: 11px;
  }

  .capture-metric-grid {
    grid-template-columns: 1fr;
  }

  .capture-meta-grid {
    grid-template-columns: 1fr;
  }

  .capture-mode-head {
    flex-direction: column;
    align-items: flex-start;
  }

  .capture-stake-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .capture-modal .capture-stake-grid {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }

  .capture-case-wheel {
    width: min(270px, 80vw);
  }
}

@media (max-width: 430px) {
  .capture-modal {
    max-height: min(87dvh, 720px);
  }

  .capture-primary-cta,
  .capture-upgrade-btn {
    min-height: 40px;
    font-size: 13px;
  }
}

/* miniapp/styles/pages/club.css */
/* ═══════════════════════════════════════════
   Club page
   ═══════════════════════════════════════════ */

.club-shell {
  display: grid;
  gap: 10px;
  padding: 0 0 112px;
}

/* ── Hero (compact header) ── */
.club-hero {
  padding: 14px;
  border-radius: 20px;
  border: 1px solid rgba(255, 255, 255, 0.08);
  background:
    radial-gradient(200px 100px at 50% 0%, rgba(124, 92, 255, 0.14), transparent 68%),
    rgba(124, 92, 255, 0.04);
}

.club-hero-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
}

.club-title {
  font-size: 24px;
  font-weight: 800;
  letter-spacing: -0.02em;
  color: #fff;
}

.club-hero-actions {
  display: flex;
  align-items: center;
  gap: 6px;
}

.club-hero-icon {
  width: 38px;
  height: 38px;
  border: 0;
  border-radius: 12px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  background: rgba(255, 255, 255, 0.06);
  color: rgba(255, 255, 255, 0.88);
  font: inherit;
  font-size: 20px;
  cursor: pointer;
}

.club-hero-icon--sm {
  width: 32px;
  height: 32px;
  border-radius: 10px;
  font-size: 15px;
  color: rgba(255, 255, 255, 0.5);
}

/* ── Mode switch (2 tabs) ── */
.club-mode-switch {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 4px;
  margin-top: 10px;
  padding: 4px;
  border-radius: 14px;
  background: rgba(255, 255, 255, 0.04);
  border: 1px solid rgba(255, 255, 255, 0.06);
}

.club-mode-btn {
  min-height: 36px;
  padding: 0 14px;
  border: 0;
  border-radius: 11px;
  background: transparent;
  color: rgba(255, 255, 255, 0.45);
  font: inherit;
  font-size: 13px;
  font-weight: 700;
  white-space: nowrap;
  cursor: pointer;
  transition: background 160ms ease, color 160ms ease;
}

.club-mode-btn.active {
  background: rgba(124, 92, 255, 0.85);
  color: #fff;
  box-shadow: 0 4px 12px rgba(95, 76, 219, 0.25);
}

.club-mode-btn:active {
  transform: scale(0.97);
}

/* ── Shared card base ── */
.club-form,
.club-search,
.club-my,
.club-empty,
.club-card,
.club-detail-card,
.club-info-item,
.club-request-card,
.club-member-card {
  border-radius: 16px;
  border: 1px solid rgba(255, 255, 255, 0.07);
  background: rgba(255, 255, 255, 0.035);
}

/* ── Form ── */
.club-form {
  display: grid;
  gap: 10px;
  padding: 14px;
}

.club-form-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 14px;
}

.club-form.hidden,
.club-my.hidden,
.club-empty.hidden,
.club-detail-view.hidden,
.club-detail-pane.hidden,
.club-pane.hidden,
.club-dash-section.hidden {
  display: none;
}

.club-form-title {
  font-size: 15px;
  font-weight: 700;
  color: rgba(255, 255, 255, 0.92);
}

.club-form-subtitle {
  margin-top: 4px;
  font-size: 12px;
  color: rgba(255, 255, 255, 0.42);
}

.club-form-avatar-block {
  display: grid;
  justify-items: center;
  gap: 8px;
}

.club-form-avatar-preview {
  width: 74px;
  height: 74px;
  font-size: 26px;
}

.club-form-avatar-actions {
  display: flex;
  gap: 8px;
}

.club-textarea {
  min-height: 80px;
  resize: vertical;
}

.club-role-fields {
  display: grid;
  gap: 10px;
}

.club-role-field {
  display: grid;
  gap: 6px;
}

.club-role-field-label {
  font-size: 12px;
  font-weight: 700;
  color: rgba(255, 255, 255, 0.72);
}

.club-role-field .filter-input.is-disabled {
  opacity: 0.58;
  cursor: not-allowed;
}

.club-form-actions,
.club-card-actions,
.club-detail-actions,
.club-request-actions,
.club-member-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.club-pane {
  display: grid;
  gap: 10px;
}

/* ── Search ── */
.club-search {
  padding: 10px 14px;
}

.club-search-row {
  display: flex;
  align-items: center;
  gap: 8px;
  min-height: 46px;
  padding: 0 12px;
  border-radius: 14px;
  background: rgba(16, 10, 31, 0.68);
  border: 1px solid rgba(124, 92, 255, 0.14);
  transition: border-color 160ms ease, box-shadow 160ms ease, background 160ms ease;
  -webkit-tap-highlight-color: transparent;
}

.club-search-row:focus-within {
  background: rgba(30, 18, 55, 0.78);
  border-color: rgba(124, 92, 255, 0.42);
  box-shadow: 0 0 0 1px rgba(124, 92, 255, 0.16), 0 10px 24px rgba(64, 33, 140, 0.18);
}

.club-search-icon {
  color: rgba(255, 255, 255, 0.35);
  font-size: 18px;
  line-height: 1;
  transition: color 160ms ease;
}

.club-search-row:focus-within .club-search-icon {
  color: rgba(180, 160, 255, 0.88);
}

.club-search .filter-input {
  background: transparent;
  border: 0;
  box-shadow: none;
  outline: none;
  padding: 0;
  padding-left: 0;
}

.club-search .filter-input:focus,
.club-search .filter-input:focus-visible {
  background: transparent;
  border: 0;
  box-shadow: none;
  outline: none;
}

.club-search .filter-input::placeholder {
  color: rgba(255, 255, 255, 0.3);
}

/* ══════════════════════════════════════════
   MY CLUB DASHBOARD
   ══════════════════════════════════════════ */

.club-my {
  padding: 0;
  border-color: rgba(124, 92, 255, 0.18);
  background: rgba(124, 92, 255, 0.03);
  overflow: hidden;
}

/* ── Dashboard header ── */
.club-dash-header {
  position: relative;
  padding: 20px 16px 16px;
  background:
    radial-gradient(180px 100px at 20% 0%, rgba(124, 92, 255, 0.2), transparent 60%),
    radial-gradient(120px 80px at 90% 100%, rgba(31, 230, 209, 0.08), transparent 60%);
  border-bottom: 1px solid rgba(255, 255, 255, 0.06);
}

.club-dash-header-top {
  display: flex;
  align-items: center;
  gap: 14px;
}

.club-dash-name {
  font-size: 24px;
  font-weight: 800;
  letter-spacing: -0.03em;
  color: #fff;
  line-height: 1.1;
}

.club-dash-meta {
  margin-top: 4px;
  font-size: 12px;
  color: rgba(255, 255, 255, 0.4);
}

/* ── Stats row ── */
.club-dash-stats {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 6px;
  margin-top: 14px;
}

.club-dash-stat {
  text-align: center;
  padding: 10px 4px;
  border-radius: 12px;
  background: rgba(255, 255, 255, 0.04);
  border: 1px solid rgba(255, 255, 255, 0.05);
}

.club-dash-stat-val {
  font-size: 18px;
  font-weight: 800;
  color: #fff;
  line-height: 1;
}

.club-dash-stat-lbl {
  margin-top: 4px;
  font-size: 9px;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  color: rgba(255, 255, 255, 0.35);
}

/* ── Description ── */
.club-dash-desc {
  padding: 12px 16px;
  font-size: 13px;
  line-height: 1.45;
  color: rgba(255, 255, 255, 0.55);
  border-bottom: 1px solid rgba(255, 255, 255, 0.05);
}

/* ── Quick actions grid ── */
.club-dash-actions {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 6px;
  padding: 10px;
}

.club-dash-action {
  display: flex;
  align-items: center;
  gap: 8px;
  min-height: 46px;
  padding: 0 14px;
  border: 0;
  border-radius: 12px;
  background: rgba(255, 255, 255, 0.05);
  color: rgba(255, 255, 255, 0.82);
  font: inherit;
  font-size: 13px;
  font-weight: 600;
  cursor: pointer;
  transition: background 0.15s, transform 0.12s;
}

.club-dash-action:active {
  transform: scale(0.97);
}

.club-dash-action:hover {
  background: rgba(255, 255, 255, 0.08);
}

.club-dash-action-icon {
  font-size: 16px;
  flex-shrink: 0;
}

.club-dash-action--accent {
  background: rgba(124, 92, 255, 0.12);
  border: 1px solid rgba(124, 92, 255, 0.22);
  color: rgba(200, 180, 255, 0.95);
}

.club-dash-action--accent:hover {
  background: rgba(124, 92, 255, 0.18);
}

.club-dash-action--danger {
  color: rgba(255, 160, 160, 0.7);
}

.club-dash-action--upgrade {
  background: linear-gradient(135deg, rgba(255, 196, 82, 0.18), rgba(124, 92, 255, 0.16));
  border: 1px solid rgba(255, 206, 112, 0.22);
  color: rgba(255, 235, 188, 0.95);
}

.club-dash-action--upgrade:hover {
  background: linear-gradient(135deg, rgba(255, 196, 82, 0.24), rgba(124, 92, 255, 0.22));
}

.club-store-panel {
  padding-top: 4px;
}

.club-store-list {
  display: grid;
  gap: 10px;
}

.club-store-card {
  display: grid;
  grid-template-columns: 82px minmax(0, 1fr) auto;
  align-items: center;
  gap: 14px;
  padding: 16px;
  border-radius: 18px;
  border: 1px solid rgba(255, 255, 255, 0.08);
  background: rgba(255, 255, 255, 0.035);
}

.club-store-art {
  width: 82px;
  height: 82px;
  object-fit: contain;
  filter: drop-shadow(0 12px 24px rgba(0, 0, 0, 0.35));
}

.club-store-copy {
  min-width: 0;
}

.club-store-title {
  font-size: 15px;
  line-height: 1.18;
  font-weight: 800;
  color: #fff;
}

.club-store-price {
  display: inline-flex;
  align-items: center;
  margin-top: 8px;
  padding: 4px 10px;
  border-radius: 999px;
  background: linear-gradient(135deg, #b33dff, #7a3cff);
  color: #fff;
  font-size: 12px;
  font-weight: 800;
  letter-spacing: 0.01em;
}

.club-store-sub {
  margin-top: 8px;
  color: rgba(255, 255, 255, 0.56);
  font-size: 13px;
  line-height: 1.35;
}

.club-store-buy {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  min-height: 48px;
  padding: 0 16px;
  border: 0;
  border-radius: 16px;
  background: rgba(124, 92, 255, 0.16);
  color: #d08cff;
  font: inherit;
  font-size: 13px;
  font-weight: 800;
  white-space: nowrap;
  cursor: pointer;
  transition: transform 0.12s ease, background 0.16s ease, opacity 0.16s ease;
}

.club-store-buy:hover {
  background: rgba(124, 92, 255, 0.24);
}

.club-store-buy:active {
  transform: scale(0.97);
}

.club-store-buy-icon {
  font-size: 16px;
}

.club-store-buy--ghost {
  opacity: 0.68;
}

.club-store-buy--ghost:hover {
  opacity: 0.86;
}

.club-dash-action--danger:hover {
  background: rgba(248, 113, 113, 0.08);
}

.club-dash-action:disabled {
  opacity: 0.35;
  pointer-events: none;
}

/* ── Expandable sections (members, requests) ── */
.club-dash-section {
  padding: 0 12px 12px;
}

.club-dash-section-title {
  font-size: 12px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: rgba(255, 255, 255, 0.4);
  margin-bottom: 8px;
  padding-top: 4px;
  border-top: 1px solid rgba(255, 255, 255, 0.05);
}

.club-dash-empty {
  font-size: 13px;
  color: rgba(255, 255, 255, 0.35);
  padding: 8px 0;
}

.club-dash-members-list,
.club-dash-requests-list {
  display: grid;
  gap: 6px;
}

/* ══════════════════════════════════════════
   MEMBERS — Grouped by role
   ══════════════════════════════════════════ */

/* ── Role group header ── */
.club-role-header {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 10px 0 4px;
}

.club-role-header:first-child {
  padding-top: 0;
}

.club-role-icon {
  font-size: 14px;
  line-height: 1;
}

.club-role-label {
  font-size: 12px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: rgba(255, 255, 255, 0.45);
}

.club-role-count {
  margin-left: auto;
  font-size: 11px;
  font-weight: 600;
  color: rgba(255, 255, 255, 0.25);
}

.club-role-header--founder .club-role-label { color: rgba(255, 200, 60, 0.8); }
.club-role-header--deputy  .club-role-label { color: rgba(124, 92, 255, 0.75); }

/* ── Member card v2 ── */
.club-member-card-v2 {
  padding: 10px 12px;
  border-radius: 14px;
  border: 1px solid rgba(255, 255, 255, 0.06);
  background: rgba(255, 255, 255, 0.03);
  transition: border-color 0.2s;
}

.club-member-row {
  display: flex;
  align-items: center;
  gap: 12px;
}

.club-member-info {
  min-width: 0;
  flex: 1;
}

.club-member-name {
  font-size: 14px;
  font-weight: 700;
  color: rgba(255, 255, 255, 0.92);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.club-member-sub {
  margin-top: 2px;
  font-size: 11px;
  color: rgba(255, 255, 255, 0.38);
}

/* ── Admin action buttons ── */
.club-member-btns {
  display: flex;
  gap: 6px;
  margin-top: 8px;
  padding-top: 8px;
  border-top: 1px solid rgba(255, 255, 255, 0.05);
}

.club-member-btn {
  flex: 1;
  min-height: 32px;
  padding: 0 12px;
  border: 0;
  border-radius: 10px;
  font: inherit;
  font-size: 12px;
  font-weight: 600;
  cursor: pointer;
  transition: background 0.15s, transform 0.12s;
}

.club-member-btn:active {
  transform: scale(0.97);
}

.club-member-btn--promote {
  background: rgba(124, 92, 255, 0.12);
  color: rgba(200, 180, 255, 0.9);
  border: 1px solid rgba(124, 92, 255, 0.18);
}

.club-member-btn--promote:hover {
  background: rgba(124, 92, 255, 0.2);
}

.club-member-btn--demote {
  background: rgba(255, 196, 82, 0.1);
  color: rgba(255, 228, 168, 0.9);
  border: 1px solid rgba(255, 196, 82, 0.18);
}

.club-member-btn--demote:hover {
  background: rgba(255, 196, 82, 0.16);
}

.club-member-btn--remove {
  background: rgba(248, 113, 113, 0.08);
  color: rgba(255, 160, 160, 0.75);
}

.club-member-btn--remove:hover {
  background: rgba(248, 113, 113, 0.14);
}

/* ══════════════════════════════════════════
   CLUB LIST (All clubs tab)
   ══════════════════════════════════════════ */

.club-list-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  padding: 0 2px;
}

.club-list-title {
  font-size: 15px;
  font-weight: 700;
  color: rgba(255, 255, 255, 0.88);
}

.club-list-meta {
  color: rgba(255, 255, 255, 0.38);
  font-size: 12px;
}

/* ── Generated club avatar ── */
.club-avatar-gen {
  flex-shrink: 0;
  border-radius: 14px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: 800;
  color: #fff;
  letter-spacing: 0.02em;
  text-shadow: 0 1px 3px rgba(0, 0, 0, 0.3);
  box-shadow:
    0 2px 8px rgba(0, 0, 0, 0.2),
    inset 0 1px 0 rgba(255, 255, 255, 0.15);
}

.club-avatar-gen.avatar-photo {
  background-color: rgba(255, 255, 255, 0.08);
  box-shadow:
    0 10px 22px rgba(0, 0, 0, 0.22),
    0 0 0 1px rgba(255, 255, 255, 0.12);
}

.club-list {
  display: grid;
  gap: 8px;
}

/* ── New v2 club cards ── */
.club-card-v2 {
  border-radius: 16px;
  border: 1px solid rgba(255, 255, 255, 0.07);
  background: rgba(255, 255, 255, 0.035);
  padding: 14px;
  display: grid;
  gap: 10px;
  transition: border-color 0.2s;
}

.club-card-v2:active {
  border-color: rgba(124, 92, 255, 0.25);
}

.club-card-v2-top {
  display: flex;
  align-items: center;
  gap: 12px;
}

.club-card-v2-info {
  min-width: 0;
  flex: 1;
}

.club-card-v2-name {
  font-size: 16px;
  font-weight: 700;
  color: rgba(255, 255, 255, 0.94);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  line-height: 1.2;
}

.club-card-v2-founder {
  margin-top: 2px;
  font-size: 12px;
  color: rgba(255, 255, 255, 0.38);
}

.club-card-v2-chips {
  display: flex;
  align-items: center;
  gap: 6px;
  flex-wrap: wrap;
}

.club-chip {
  display: inline-flex;
  align-items: center;
  gap: 3px;
  padding: 4px 9px;
  border-radius: 8px;
  background: rgba(255, 255, 255, 0.05);
  border: 1px solid rgba(255, 255, 255, 0.06);
  font-size: 12px;
  font-weight: 600;
  color: rgba(255, 255, 255, 0.7);
  white-space: nowrap;
}

/* ── Members fill bar ── */
.club-card-v2-bar-wrap {
  height: 3px;
  border-radius: 2px;
  background: rgba(255, 255, 255, 0.06);
  overflow: hidden;
}

.club-card-v2-bar {
  height: 100%;
  border-radius: 2px;
  background: linear-gradient(90deg, rgba(124, 92, 255, 0.7), rgba(31, 230, 209, 0.6));
  transition: width 0.4s ease;
}

/* ── Card actions row ── */
.club-card-v2-actions {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
}

.club-btn-open {
  min-height: 34px;
  padding: 0 16px;
  border: 0;
  border-radius: 10px;
  background: rgba(255, 255, 255, 0.06);
  color: rgba(255, 255, 255, 0.75);
  font: inherit;
  font-size: 13px;
  font-weight: 600;
  cursor: pointer;
  transition: background 0.15s;
}

.club-btn-open:active {
  transform: scale(0.97);
}

.club-btn-open:hover {
  background: rgba(255, 255, 255, 0.1);
}

.club-btn-apply {
  min-height: 34px;
  padding: 0 16px;
  border: 0;
  border-radius: 10px;
  background: rgba(124, 92, 255, 0.8);
  color: #fff;
  font: inherit;
  font-size: 13px;
  font-weight: 700;
  cursor: pointer;
  box-shadow: 0 2px 8px rgba(124, 92, 255, 0.25);
  transition: background 0.15s;
}

.club-btn-apply:active {
  transform: scale(0.97);
}

.club-btn-apply:hover {
  background: rgba(124, 92, 255, 0.95);
}

/* ── Status badges ── */
.club-badge {
  display: inline-flex;
  align-items: center;
  padding: 5px 12px;
  border-radius: 8px;
  font-size: 12px;
  font-weight: 600;
  white-space: nowrap;
}

.club-badge--mine {
  background: rgba(34, 197, 94, 0.12);
  color: #bbf7d0;
}

.club-badge--pending {
  background: rgba(255, 179, 71, 0.12);
  color: rgba(255, 220, 150, 0.9);
}

.club-badge--full {
  background: rgba(248, 113, 113, 0.1);
  color: #fecaca;
}

/* (old status badges removed — replaced by .club-badge) */

/* ── Empty state ── */
.club-empty {
  padding: 20px 16px;
  text-align: center;
  color: rgba(255, 255, 255, 0.5);
  font-size: 13px;
}

.club-empty-title {
  font-size: 18px;
  font-weight: 800;
  color: #fff;
}

.club-empty-subtitle {
  margin-top: 6px;
  color: rgba(255, 255, 255, 0.42);
  font-size: 13px;
  line-height: 1.4;
}

.club-empty-actions {
  justify-content: center;
  margin-top: 12px;
}

/* ══════════════════════════════════════════
   DETAIL VIEW (viewing other clubs)
   ══════════════════════════════════════════ */

.club-detail-top {
  display: flex;
  justify-content: flex-start;
}

.club-detail-back {
  min-height: 36px;
  padding: 0 12px;
  border: 0;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.05);
  color: rgba(255, 255, 255, 0.8);
  font: inherit;
  font-size: 13px;
  cursor: pointer;
}

.club-detail-card {
  padding: 0;
  border-color: rgba(124, 92, 255, 0.18);
  background: rgba(124, 92, 255, 0.03);
  overflow: hidden;
}

.club-detail-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 10px;
}

.club-detail-name {
  font-size: 20px;
  font-weight: 700;
  color: rgba(255, 255, 255, 0.96);
  margin-top: 2px;
}

.club-detail-meta {
  margin-top: 4px;
  color: rgba(255, 255, 255, 0.4);
  font-size: 12px;
}

.club-stats-inline {
  display: flex;
  align-items: center;
  gap: 6px;
  flex-wrap: wrap;
  margin-top: 10px;
}

.club-stat-inline {
  min-height: 30px;
  padding: 0 10px;
  border-radius: 999px;
  display: inline-flex;
  align-items: center;
  gap: 5px;
  background: rgba(255, 255, 255, 0.05);
  color: rgba(255, 255, 255, 0.5);
  font-size: 12px;
}

.club-stat-inline b {
  color: rgba(255, 255, 255, 0.9);
}

.club-detail-tabs {
  display: flex;
  gap: 6px;
}

.club-detail-pane {
  display: grid;
  gap: 8px;
}

.club-info-grid {
  display: grid;
  gap: 8px;
}

.club-info-item,
.club-request-card,
.club-member-card {
  padding: 10px 12px;
}

.club-info-title {
  font-size: 9px;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: rgba(255, 255, 255, 0.32);
}

.club-info-value {
  margin-top: 3px;
  color: rgba(255, 255, 255, 0.88);
  font-size: 14px;
  line-height: 1.4;
}

.club-request-title,
.club-member-title {
  display: flex;
  align-items: center;
  gap: 10px;
  color: rgba(255, 255, 255, 0.92);
  font-weight: 700;
  font-size: 14px;
}

.club-member-meta,
.club-request-meta {
  margin-top: 2px;
  color: rgba(255, 255, 255, 0.38);
  font-size: 11px;
}

.club-avatar {
  width: 36px;
  height: 36px;
  border-radius: 50%;
  overflow: hidden;
  flex: 0 0 36px;
  background: rgba(124, 92, 255, 0.15);
  border: 1px solid rgba(255, 255, 255, 0.08);
}

/* ── Responsive ── */
@media (max-width: 640px) {
  .club-form-head {
    flex-direction: column;
    align-items: stretch;
  }

  .club-form-avatar-block {
    justify-items: flex-start;
  }

  .club-form-actions,
  .club-detail-actions {
    flex-direction: column;
    align-items: stretch;
  }

  .club-dash-stats {
    grid-template-columns: repeat(2, 1fr);
  }

  .club-store-card {
    grid-template-columns: 68px minmax(0, 1fr);
  }

  .club-store-art {
    width: 68px;
    height: 68px;
  }

  .club-store-buy {
    grid-column: 1 / -1;
    justify-content: center;
    width: 100%;
  }
}

/* miniapp/styles/pages/coins.css */
/* --- Coins tab: match listings visual style --- */
.page-coins .coin-hero {
  padding: 14px;
  border-radius: 16px;
  background: rgba(122, 60, 255, 0.08);
  border: 1px solid rgba(122, 60, 255, 0.28);
  box-shadow: none;
}

.page-coins .coin-hero-top {
  align-items: center;
}

.page-coins .coin-balance-row {
  margin-top: 4px;
  align-items: center;
}

.page-coins .coin-balance {
  font-size: 22px;
  font-weight: 800;
}

.page-coins .coin-tiles {
  margin: 8px 0 18px;
  grid-template-columns: 1fr;
  gap: 12px;
}

.page-coins .coin-tile {
  padding: 12px;
  border-radius: 16px;
  border: 1px solid rgba(122, 60, 255, 0.24);
  background: rgba(122, 60, 255, 0.12);
  box-shadow: inset 0 0 18px rgba(122, 60, 255, 0.08);
  display: grid;
  grid-template-columns: 1fr auto;
  grid-template-areas:
    "title icon"
    "note icon"
    "badge icon";
  gap: 4px 12px;
  text-align: left;
  min-height: 82px;
}

.page-coins .coin-tile::before {
  display: none;
}

/* align tile depth with listings for readability */
.page-coins .coin-tile {
  background: rgba(122, 60, 255, 0.12);
  border-color: rgba(122, 60, 255, 0.24);
}

.page-coins .coin-tile-title {
  color: rgba(245, 238, 255, 0.96);
}

.page-coins .coin-tile-note {
  color: rgba(198, 179, 255, 0.72);
}

.page-coins .coin-tile-title {
  grid-area: title;
  font-size: 16px;
  font-weight: 700;
}

.page-coins .coin-tile-note {
  grid-area: note;
  font-size: 12px;
  color: rgba(198, 179, 255, 0.7);
}

.page-coins .coin-tile-badge {
  grid-area: badge;
  position: static;
  margin-top: 4px;
  align-self: start;
  justify-self: start;
  padding: 5px 10px;
  font-size: 11px;
  background: rgba(10, 6, 22, 0.4);
  border: 1px solid rgba(255, 255, 255, 0.16);
}

.page-coins .coin-tile-icon {
  grid-area: icon;
  align-self: center;
  justify-self: end;
  width: 36px;
  height: 36px;
  border-radius: 12px;
  background: rgba(122, 60, 255, 0.2);
  border: 1px solid rgba(255, 255, 255, 0.12);
  font-size: 18px;
}

.page-coins .coin-tile--promo,
.page-coins .coin-tile--tasks,
.page-coins .coin-tile--referrals,
.page-coins .coin-tile--shop {
  border-color: rgba(122, 60, 255, 0.18);
  box-shadow: none;
}

.coin-panel {
  margin-bottom: 14px;
  position: relative;
  overflow: hidden;
}

.coin-panel::before {
  content: "";
  position: absolute;
  inset: -1px;
  background:
    radial-gradient(circle at 18% 0%, rgba(var(--panel-accent, 122, 60, 255), 0.20), transparent 60%),
    radial-gradient(circle at 100% 30%, rgba(var(--panel-accent-2, 124, 92, 255), 0.14), transparent 62%),
    linear-gradient(180deg, rgba(255, 255, 255, 0.03), transparent 55%);
  pointer-events: none;
}

.coin-panel > * {
  position: relative;
  z-index: 1;
}

.coin-panel--promo {
  --panel-accent: 124, 92, 255;
  --panel-accent-2: 255, 205, 140;
  border-color: rgba(124, 92, 255, 0.22);
  box-shadow: 0 18px 34px rgba(124, 92, 255, 0.06);
}

.coin-panel--tasks {
  --panel-accent: 124, 92, 255;
  --panel-accent-2: 122, 255, 186;
  border-color: rgba(124, 92, 255, 0.22);
  box-shadow: 0 18px 34px rgba(124, 92, 255, 0.06);
}

.coin-panel--referrals {
  --panel-accent: 122, 202, 255;
  --panel-accent-2: 255, 146, 200;
  border-color: rgba(122, 202, 255, 0.18);
  box-shadow: 0 18px 34px rgba(122, 202, 255, 0.06);
}

.coin-panel--shop {
  --panel-accent: 124, 92, 255;
  --panel-accent-2: 255, 205, 110;
  border-color: rgba(124, 92, 255, 0.22);
  box-shadow: 0 18px 34px rgba(124, 92, 255, 0.06);
}

.coin-panel-note {
  font-size: 12px;
  color: rgba(198, 179, 255, 0.75);
  margin-top: 6px;
}

.coin-panel--promo .coin-panel-note {
  color: rgba(233, 226, 255, 0.72);
}

.coin-panel--tasks .coin-panel-note {
  color: rgba(233, 226, 255, 0.72);
}

.coin-panel--referrals .coin-panel-note {
  color: rgba(208, 235, 255, 0.72);
}

.coin-panel--shop .coin-panel-note {
  color: rgba(233, 226, 255, 0.72);
}

.coin-panel--promo .tariff-pill {
  border-color: rgba(124, 92, 255, 0.4);
  background: rgba(124, 92, 255, 0.12);
  color: rgba(244, 237, 255, 0.94);
}

.coin-panel--promo .tariff-pill:active {
  transform: scale(0.98);
}

.coin-panel--tasks .task-week-timer {
  color: rgba(233, 226, 255, 0.82);
}

.coin-panel--referrals .referral-text {
  color: rgba(208, 235, 255, 0.8);
}

.coin-panel--shop .shop-card {
  border-color: rgba(124, 92, 255, 0.26);
}
.coin-info-grid {
  margin-top: 12px;
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 10px;
}

.coin-info {
  padding: 10px;
  border-radius: 14px;
  border: 1px solid rgba(122, 60, 255, 0.28);
  background: rgba(15, 9, 33, 0.7);
  text-align: center;
}

.coin-info-label {
  font-size: 10px;
  color: rgba(198, 179, 255, 0.7);
}

.coin-info-value {
  margin-top: 4px;
  font-size: 13px;
  font-weight: 700;
}

.coin-info-value.is-full {
  color: #ffd1a1;
}

.coin-action-row {
  margin-top: 12px;
  display: flex;
  justify-content: flex-end;
}

.coin-tariffs {
  margin-top: 10px;
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
}

.tariff-pill {
  padding: 6px 12px;
  border-radius: 999px;
  border: 1px solid rgba(122, 60, 255, 0.45);
  background: rgba(20, 10, 40, 0.75);
  font-size: 11px;
  color: #efe7ff;
}

.task-list {
  margin-top: 12px;
  display: grid;
  gap: 10px;
  padding-bottom: 86px;
}

.task-week-timer {
  margin: 10px 0 12px;
  font-size: 12px;
  color: rgba(226, 216, 255, 0.85);
}

.task-actions {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  margin-top: 10px;
}

.task-card.ready {
  border-color: rgba(122, 255, 186, 0.35);
  box-shadow: 0 0 0 1px rgba(122, 255, 186, 0.08), 0 12px 24px rgba(122, 255, 186, 0.08);
}

.task-card.done .task-status {
  opacity: 0.9;
}

.task-card {
  padding: 12px;
  border-radius: 14px;
  border: 1px solid rgba(122, 60, 255, 0.28);
  background: rgba(15, 9, 33, 0.7);
  display: grid;
  gap: 4px;
}

.task-card.locked {
  opacity: 0.6;
}

.task-card.done {
  border-color: rgba(122, 255, 186, 0.35);
  box-shadow: inset 0 0 12px rgba(122, 255, 186, 0.15);
}

.task-title {
  font-size: 15px;
  font-weight: 900;
  letter-spacing: 0.2px;
}

.task-meta {
  font-size: 12px;
  color: rgba(198, 179, 255, 0.78);
  line-height: 1.25;
}

.task-status {
  font-size: 11px;
  font-weight: 600;
  color: rgba(202, 188, 255, 0.9);
}

.task-ready-pill {
  padding: 6px 10px;
  border-radius: 999px;
  border: 1px solid rgba(122, 255, 186, 0.28);
  background: rgba(122, 255, 186, 0.10);
  color: rgba(220, 255, 240, 0.92);
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.2px;
}

.tasks-footer {
  position: sticky;
  bottom: 0;
  margin-top: 12px;
  padding: 12px 0 0;
  background: linear-gradient(180deg, rgba(10, 6, 22, 0) 0%, rgba(10, 6, 22, 0.78) 28%, rgba(10, 6, 22, 0.92) 100%);
}

.tasks-footer::before {
  content: "";
  position: absolute;
  left: -12px;
  right: -12px;
  top: 0;
  height: 1px;
  background: rgba(255, 255, 255, 0.06);
}

.tasks-footer-hint {
  font-size: 12px;
  color: rgba(198, 179, 255, 0.78);
  margin-bottom: 8px;
}

.tasks-claim-btn {
  width: 100%;
  justify-content: center;
  padding: 12px 14px;
  border-radius: 16px;
  font-weight: 900;
}

.coin-shop .shop-grid {
  margin-top: 12px;
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 12px;
}

.shop-card {
  padding: 12px;
  border-radius: 16px;
  border: 1px solid rgba(122, 60, 255, 0.32);
