.image-zoom {
  background: rgba(0, 0, 0, 0.92);
  backdrop-filter: blur(20px);
  -webkit-backdrop-filter: blur(20px);
  padding: 0;
}

.image-zoom-card {
  position: relative;
  width: 100%;
  height: 100%;
  max-width: none;
  border-radius: 0;
  border: none;
  background: transparent;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 60px 16px 80px;
  overflow: hidden;
  touch-action: none;
}

.image-zoom-card img {
  max-width: 100%;
  max-height: 100%;
  object-fit: contain;
  border-radius: 8px;
  transition: transform 0.15s ease-out;
  cursor: grab;
  transform-origin: center;
  user-select: none;
  -webkit-user-drag: none;
}

.image-zoom-card img:active {
  cursor: grabbing;
}

.image-zoom-close {
  position: fixed;
  top: max(16px, env(safe-area-inset-top));
  right: 16px;
  width: 44px;
  height: 44px;
  padding: 0;
  border-radius: 50%;
  border: 1px solid rgba(255, 255, 255, 0.15);
  background: rgba(255, 255, 255, 0.1);
  color: #fff;
  font-size: 20px;
  display: grid;
  place-items: center;
  z-index: 10;
  transition: all 0.2s ease;
}

.image-zoom-close:active {
  background: rgba(255, 255, 255, 0.2);
  transform: scale(0.95);
}

.image-zoom-controls {
  position: fixed;
  bottom: max(24px, env(safe-area-inset-bottom));
  left: 50%;
  transform: translateX(-50%);
  display: inline-flex;
  gap: 8px;
  padding: 8px;
  border-radius: 16px;
  background: rgba(255, 255, 255, 0.08);
  border: 1px solid rgba(255, 255, 255, 0.1);
  backdrop-filter: blur(10px);
  -webkit-backdrop-filter: blur(10px);
  z-index: 10;
}

.image-zoom-controls .ghost-btn {
  min-width: 48px;
  height: 40px;
  border-radius: 12px;
  border: none;
  background: rgba(255, 255, 255, 0.1);
  color: #fff;
  font-size: 16px;
  font-weight: 500;
  padding: 0 14px;
  transition: all 0.15s ease;
}

.image-zoom-controls .ghost-btn:active {
  background: rgba(255, 255, 255, 0.2);
  transform: scale(0.95);
}

/* Override modal animation for image viewer */
.image-zoom .image-zoom-card {
  transform: none;
  opacity: 1;
  animation: imageViewerFadeIn 0.25s ease forwards;
}

@keyframes imageViewerFadeIn {
  from { opacity: 0; }
  to { opacity: 1; }
}

