/* ============================================
   LISTING GALLERY - ENHANCED
   ============================================ */

.listing-gallery {
  display: none;
  position: relative;
  overflow: hidden;
  border-radius: 20px;
  margin-bottom: 20px;
  border: 1px solid rgba(124, 92, 255, 0.2);
  background: linear-gradient(180deg, rgba(20, 12, 40, 0.8), rgba(12, 8, 25, 0.9));
  touch-action: pan-y;
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.3);
}

.gallery-loading {
  position: relative;
  aspect-ratio: 4 / 3;
  width: 100%;
  border-radius: 20px;
  overflow: hidden;
  display: grid;
  place-items: center;
  background: linear-gradient(180deg, rgba(20, 12, 40, 0.9), rgba(12, 8, 25, 0.95));
}

.gallery-loading-shimmer {
  position: absolute;
  inset: 0;
  background: linear-gradient(
    110deg,
    rgba(124, 92, 255, 0.08) 15%,
    rgba(165, 133, 255, 0.28) 35%,
    rgba(124, 92, 255, 0.08) 55%
  );
  background-size: 200% 100%;
  animation: galleryShimmer 1.1s linear infinite;
}

.gallery-loading-text {
  position: relative;
  z-index: 1;
  color: rgba(232, 223, 255, 0.92);
  font-size: 13px;
  font-weight: 700;
  letter-spacing: 0.3px;
}

@keyframes galleryShimmer {
  0% {
    background-position: 200% 0;
  }
  100% {
    background-position: -200% 0;
  }
}

.gallery-track {
  display: flex;
  transition: transform 320ms cubic-bezier(0.25, 0.46, 0.45, 0.94);
}

.gallery-slide {
  min-width: 100%;
  aspect-ratio: 4 / 3;
  display: grid;
  place-items: center;
  background: transparent;
  cursor: pointer;
}

.gallery-slide img {
  width: 100%;
  height: 100%;
  object-fit: contain;
  transition: transform 0.3s ease;
}

.gallery-slide:hover img {
  transform: scale(1.02);
}

.gallery-dots {
  position: absolute;
  bottom: 12px;
  left: 50%;
  transform: translateX(-50%);
  display: flex;
  gap: 8px;
  padding: 6px 12px;
  border-radius: 20px;
  background: rgba(10, 6, 20, 0.7);
  backdrop-filter: blur(8px);
}

.gallery-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: rgba(255, 255, 255, 0.3);
  transition: all 0.25s ease;
  cursor: pointer;
}

.gallery-dot:hover {
  background: rgba(255, 255, 255, 0.5);
}

.gallery-dot.active {
  width: 24px;
  border-radius: 10px;
  background: linear-gradient(90deg, #9b6bff, #7c5cff);
}

.gallery-arrow {
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  width: 40px;
  height: 40px;
  border-radius: 50%;
  border: 1px solid rgba(255, 255, 255, 0.15);
  background: rgba(20, 15, 40, 0.8);
  backdrop-filter: blur(8px);
  color: #fff;
  display: grid;
  place-items: center;
  font-size: 22px;
  cursor: pointer;
  transition: all 0.25s ease;
  opacity: 0;
}

.listing-gallery:hover .gallery-arrow {
  opacity: 1;
}

.gallery-arrow:disabled {
  opacity: 0 !important;
  cursor: default;
}

.gallery-arrow:hover:not(:disabled) {
  background: rgba(124, 92, 255, 0.5);
  border-color: rgba(124, 92, 255, 0.6);
  transform: translateY(-50%) scale(1.1);
}

.gallery-prev {
  left: 12px;
}

.gallery-next {
  right: 12px;
}

/* Gallery zoom hint */
.gallery-slide::after {
  content: "Нажмите для увеличения";
  position: absolute;
  bottom: 50px;
  left: 50%;
  transform: translateX(-50%);
  padding: 6px 12px;
  border-radius: 8px;
  background: rgba(0, 0, 0, 0.6);
  color: rgba(255, 255, 255, 0.8);
  font-size: 11px;
  opacity: 0;
  transition: opacity 0.3s ease;
  pointer-events: none;
}

.gallery-slide:hover::after {
  opacity: 1;
}

