/* =====================================================
   SELLER CARD - Минималистичный премиум дизайн
   ===================================================== */

.seller-card {
  position: relative;
  overflow: hidden;
}

.seller-card.card {
  padding: 0;
  border-radius: 20px;
  background: linear-gradient(145deg, rgba(22, 18, 42, 0.95), rgba(14, 12, 28, 0.98));
  border: 1px solid rgba(124, 92, 255, 0.15);
  /* no backdrop-filter here: with a masked avatar and a scaled row inside, WebKit paints the blur layer as a square
     (straight corners poking out beside the rounded card); the fill is almost opaque anyway */
  backdrop-filter: none;
  -webkit-backdrop-filter: none;
  isolation: isolate;
}

.seller-card-inner {
  padding: 20px;
}

.seller-card-main {
  display: flex;
  align-items: center;
  gap: 16px;
}

/* Аватар с красивой рамкой */
.seller-avatar-wrap {
  position: relative;
  flex-shrink: 0;
}

.seller-avatar-wrap[data-profile-frame]::before {
  content: "";
  position: absolute;
  inset: -3px;
  border-radius: 50%;
  z-index: 0;
  background: conic-gradient(from 0deg, #7C5CFF, #1FE6D1, #FF6B9D, #FFD93D, #7C5CFF);
  opacity: 0.88;
  animation: publicAvatarRingSpin 8s linear infinite;
}

.seller-avatar-wrap[data-profile-frame="profile_frame_aurora"]::before {
  background: conic-gradient(from 0deg, #1FE6D1, #7C5CFF, #4DA3FF, #1FE6D1);
}

.seller-avatar-wrap[data-profile-frame="profile_frame_sunset"]::before {
  background: conic-gradient(from 0deg, #FF4D8D, #FFB340, #FFD56A, #FF4D8D);
}

.seller-avatar-wrap[data-profile-frame="profile_frame_neon"]::before {
  background: conic-gradient(from 0deg, #00D1FF, #7C5CFF, #1FE6D1, #00D1FF);
}

.seller-avatar-wrap[data-profile-frame="profile_frame_lime"]::before {
  background: conic-gradient(from 0deg, #B6FF3B, #1FE6D1, #7CFFAA, #B6FF3B);
}

.seller-avatar-wrap[data-profile-frame="profile_frame_ice"]::before {
  background: conic-gradient(from 0deg, #BFF4FF, #C7D6FF, #4DA3FF, #BFF4FF);
}

.seller-avatar-wrap[data-profile-frame="profile_frame_ruby"]::before {
  background: conic-gradient(from 0deg, #FF4FA3, #FF89D6, #D55BFF, #FF4FA3);
}

