  gap: 8px;
  align-items: center;
}

.report-reasons {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 8px;
  margin: 12px 0 10px;
}

.report-reasons .pill {
  justify-content: center;
  text-align: center;
}

.report-input {
  min-height: 80px;
