.create-form {
  display: grid;
  gap: 12px;
  min-width: 0;
  max-width: 100%;
}

/* The body already reserves the space under the floating bar: no second reserve here. */
.page.page-create.active {
  padding-bottom: 0;
}

.page.page-create .create-card,
.page.page-create .create-form {
  min-width: 0;
  max-width: 100%;
  overflow-x: clip;
}

.page.page-create #createSubmit {
  position: relative;
  z-index: 2;
  margin: 4px 0 8px;
  scroll-margin-bottom: calc(var(--bottom-nav-height, 108px) + 36px + env(safe-area-inset-bottom));
  touch-action: manipulation;
}

.create-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  margin-bottom: 8px;
}

.rules-btn {
  width: 34px;
  height: 34px;
  border-radius: 12px;
  background: rgba(122, 60, 255, 0.16);
  border: 1px solid rgba(122, 60, 255, 0.4);
  display: grid;
  place-items: center;
  color: #fff;
}

.rules-overlay {
  position: fixed;
  inset: 0;
  background: rgba(8, 4, 18, 0.6);
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.2s ease;
  z-index: 30;
}

.rules-overlay.show {
  opacity: 1;
  pointer-events: auto;
}

.rules-drawer {
  position: absolute;
  top: 0;
  left: 0;
  height: 100%;
  max-height: 100dvh;
  width: min(360px, 88vw);
  background: linear-gradient(180deg, rgba(36, 20, 68, 0.95), rgba(20, 12, 40, 0.95));
  border-right: 1px solid rgba(122, 60, 255, 0.35);
  padding: 16px 14px calc(24px + var(--bottom-nav-height));
  display: flex;
  flex-direction: column;
  gap: 12px;
  box-shadow: 18px 0 36px rgba(10, 4, 24, 0.45);
  transform: translateX(-100%);
  transition: transform 0.25s ease;
  overflow-y: auto;
  -webkit-overflow-scrolling: touch;
}

.rules-overlay.show .rules-drawer {
  transform: translateX(0);
}

.rules-drawer-header {
  display: grid;
  grid-template-columns: auto 1fr auto;
  align-items: center;
  gap: 10px;
}

.rules-icon {
  width: 36px;
  height: 36px;
  border-radius: 12px;
  background: rgba(122, 60, 255, 0.2);
  border: 1px solid rgba(122, 60, 255, 0.4);
  display: grid;
  place-items: center;
  font-size: 18px;
  color: #fff;
  box-shadow: inset 0 0 10px rgba(122, 60, 255, 0.3);
}

.rules-title {
  font-size: 13px;
  font-weight: 700;
}

.rules-close {
  width: 32px;
  height: 32px;
  border-radius: 10px;
  font-size: 14px;
  background: rgba(255, 255, 255, 0.08);
  border: 1px solid rgba(255, 255, 255, 0.2);
}

.rules-section {
  display: grid;
  gap: 6px;
}

.rules-section-title {
  font-size: 12px;
  font-weight: 700;
  color: #e8dcff;
}

.rules-list {
  display: grid;
  gap: 6px;
  padding-left: 16px;
  color: var(--muted);
  font-size: 11px;
  line-height: 1.35;
}

.rules-note {
  font-size: 11px;
  color: var(--muted);
  line-height: 1.35;
}

.photo-block {
  display: grid;
  gap: 10px;
}

.photo-add {
  border: 1px dashed rgba(122, 60, 255, 0.5);
  border-radius: 14px;
  padding: 12px 14px;
  background: rgba(12, 7, 25, 0.6);
  color: #e7ddff;
  font-size: 13px;
  cursor: pointer;
  text-align: left;
}

.photo-input {
  display: none;
}

.photo-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 8px;
}

.photo-thumb {
  position: relative;
  border-radius: 12px;
  overflow: hidden;
  border: 1px solid rgba(122, 60, 255, 0.25);
  animation: photoIn 180ms ease-out;
}

.photo-thumb img {
  width: 100%;
  height: 80px;
  object-fit: cover;
  display: block;
}

.photo-remove {
  position: absolute;
  top: 4px;
  right: 4px;
  width: 22px;
  height: 22px;
  border-radius: 50%;
  border: none;
  background: rgba(12, 7, 25, 0.8);
  color: #fff;
  cursor: pointer;
  font-size: 12px;
}

.photo-thumb.removing {
  animation: photoOut 160ms ease-out forwards;
}

.photo-hint {
  font-size: 12px;
  color: var(--muted);
}

.action-bar.action-bar--legacy {
  position: fixed;
  bottom: calc(20px + env(safe-area-inset-bottom));
  left: 50%;
  transform: translateX(calc(-50% + var(--swipe-dx, 0px)));
  width: min(304px, calc(100% - 24px));
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 10px 8px;
  border-radius: 28px;
  background: rgba(18, 14, 35, 0.85);
  backdrop-filter: blur(24px);
  -webkit-backdrop-filter: blur(24px);
  border: 1px solid rgba(124, 92, 255, 0.25);
  box-shadow:
    0 8px 32px rgba(0, 0, 0, 0.4),
    0 0 0 1px rgba(255, 255, 255, 0.03) inset,
    0 -2px 12px rgba(124, 92, 255, 0.15) inset;
  z-index: 100;
  overflow: visible;
  opacity: 1;
  transition: transform 220ms cubic-bezier(0.2, 0.8, 0.2, 1), opacity 200ms ease;
}

.action-bar.action-bar--legacy.has-admin {
  width: min(460px, calc(100% - 20px));
}

.action-bar.action-bar--legacy.is-swiping {
  transition: none;
}

.action-bar.action-bar--legacy.has-admin {
  width: min(352px, calc(100% - 24px));
}

/* Remove old indicator - using new glow effect */
.action-bar--legacy .nav-indicator {
  display: none;
}

.action-bar--legacy .nav-btn {
  position: relative;
  z-index: 1;
  width: 60px;
  height: 60px;
  border-radius: 20px;
  border: none;
  background: transparent;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  transition: all 0.3s cubic-bezier(0.34, 1.56, 0.64, 1);
}

.action-bar--legacy .nav-btn::before {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: 20px;
  background: transparent;
  opacity: 0;
  transition: all 0.3s ease;
}

.action-bar--legacy .nav-btn:active {
  transform: scale(0.92);
}

/* Hover effect */
.action-bar--legacy .nav-btn:not(.active):hover::before {
  background: rgba(124, 92, 255, 0.1);
  opacity: 1;
}

/* Active state - elevated with glow */
.action-bar--legacy .nav-btn.active {
  transform: translateY(-8px) scale(1.1);
}

.action-bar--legacy .nav-btn.active::before {
  background: linear-gradient(145deg, rgba(155, 107, 255, 0.95), rgba(108, 77, 255, 0.9));
  opacity: 1;
  box-shadow:
    0 12px 28px rgba(124, 92, 255, 0.5),
    0 4px 12px rgba(124, 92, 255, 0.3),
    0 0 24px rgba(155, 107, 255, 0.4),
    inset 0 1px 1px rgba(255, 255, 255, 0.2);
}

/* Glow dot indicator under active tab */
.action-bar--legacy .nav-btn.active::after {
  content: "";
  position: absolute;
  bottom: -14px;
  left: 50%;
  transform: translateX(-50%);
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: linear-gradient(135deg, #b07cff, #7c5cff);
  box-shadow:
    0 0 8px rgba(155, 107, 255, 0.8),
    0 0 16px rgba(124, 92, 255, 0.5);
  animation: navDotPulse 2s ease-in-out infinite;
}

@keyframes navDotPulse {
  0%, 100% {
    opacity: 1;
    box-shadow: 0 0 8px rgba(155, 107, 255, 0.8), 0 0 16px rgba(124, 92, 255, 0.5);
  }
  50% {
    opacity: 0.7;
    box-shadow: 0 0 12px rgba(155, 107, 255, 1), 0 0 24px rgba(124, 92, 255, 0.7);
  }
}

.action-bar--legacy .nav-btn .nav-icon {
  position: relative;
  z-index: 2;
  width: 26px;
  height: 26px;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: all 0.3s cubic-bezier(0.34, 1.56, 0.64, 1);
