/* --- VIP Hero (hidden, kept for backwards compat) --- */
.vip-hero {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 180px;
  border-radius: 20px;
  overflow: hidden;
  isolation: isolate;
}

/* Dark radial base */
.vip-hero-bg {
  position: absolute;
  inset: 0;
  z-index: 0;
  background:
    radial-gradient(ellipse 80% 90% at 50% 30%, rgba(20, 10, 40, 0.95), rgba(8, 4, 20, 0.98) 70%);
  border: 1px solid rgba(124, 92, 255, 0.12);
  border-radius: inherit;
}

/* Soft violet light rays */
.vip-hero-rays {
  position: absolute;
  inset: 0;
  z-index: 1;
  background:
    conic-gradient(
      from 0deg at 50% 55%,
      transparent 0deg,
      rgba(124, 92, 255, 0.06) 15deg,
      transparent 30deg,
      transparent 60deg,
      rgba(160, 120, 255, 0.04) 75deg,
      transparent 90deg,
      transparent 120deg,
      rgba(124, 92, 255, 0.06) 135deg,
      transparent 150deg,
      transparent 180deg,
      rgba(160, 120, 255, 0.05) 195deg,
      transparent 210deg,
      transparent 240deg,
      rgba(124, 92, 255, 0.06) 255deg,
      transparent 270deg,
      transparent 300deg,
      rgba(160, 120, 255, 0.04) 315deg,
      transparent 330deg,
      transparent 360deg
    );
  animation: vipRaysRotate 30s linear infinite;
  pointer-events: none;
}

@keyframes vipRaysRotate {
  to { transform: rotate(360deg); }
}

/* Pulsing rings */
.vip-hero-ring {
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  border-radius: 50%;
  border: 1px solid rgba(124, 92, 255, 0.12);
  z-index: 1;
  pointer-events: none;
  animation: vipRingPulse 4s ease-in-out infinite;
}

.vip-hero-ring--1 {
  width: 120px;
  height: 120px;
  border-color: rgba(124, 92, 255, 0.10);
}

.vip-hero-ring--2 {
  width: 200px;
  height: 200px;
  border-color: rgba(124, 92, 255, 0.06);
  animation-delay: 2s;
}

@keyframes vipRingPulse {
  0%, 100% { transform: translate(-50%, -50%) scale(1); opacity: 0.4; }
  50% { transform: translate(-50%, -50%) scale(1.15); opacity: 0.8; }
}

/* Floating particles */
.vip-hero-particle {
  position: absolute;
  width: 3px;
  height: 3px;
  border-radius: 50%;
  background: rgba(124, 92, 255, 0.8);
  box-shadow: 0 0 6px rgba(124, 92, 255, 0.6);
  z-index: 2;
  pointer-events: none;
  animation: vipParticleFloat 6s ease-in-out infinite;
}

.vip-hero-particle--1 { top: 25%; left: 12%; animation-duration: 5.2s; animation-delay: 0s; width: 2px; height: 2px; }
.vip-hero-particle--2 { top: 60%; left: 8%; animation-duration: 6.8s; animation-delay: 1.2s; }
.vip-hero-particle--3 { top: 35%; right: 10%; animation-duration: 5.8s; animation-delay: 0.6s; width: 2.5px; height: 2.5px; }
.vip-hero-particle--4 { top: 70%; right: 15%; animation-duration: 7s; animation-delay: 2.4s; width: 2px; height: 2px; }
.vip-hero-particle--5 { top: 18%; left: 30%; animation-duration: 6.2s; animation-delay: 3.1s; width: 1.5px; height: 1.5px; }
