    0 10px 22px rgba(0, 0, 0, 0.2),
    inset 0 1px 0 rgba(255, 255, 255, 0.15);
}

/* --- Silver VIP benefits modal --- */
.vip-benefits-card {
  max-width: 420px;
  border-color: rgba(192, 196, 204, 0.2);
  background:
    radial-gradient(ellipse 130% 55% at 50% 0%, rgba(192, 196, 204, 0.08), transparent 55%),
    linear-gradient(165deg, rgba(30, 30, 38, 0.98) 0%, rgba(15, 15, 22, 0.98) 100%);
}

.vip-benefit-item--silver {
  border-color: rgba(192, 196, 204, 0.14);
  background: rgba(192, 196, 204, 0.06);
}

.vip-benefit-index--silver {
  background: linear-gradient(140deg, rgba(220, 225, 230, 0.9), rgba(160, 170, 185, 0.9));
  box-shadow: 0 0 0 3px rgba(192, 196, 204, 0.1);
}

/* --- VIP cards spacing fix --- */
.vip-swipe-dots {
