/* ========================================
   M-COIN PACKS — TOP-UP SCREEN
   ======================================== */
.coin-pack-screen {
  display: flex;
  flex-direction: column;
  gap: 16px;
  padding: 16px;
  padding-bottom: 8px;
}

/* --- Hero --- */
.coin-pack-hero {
  position: relative;
  display: flex;
  align-items: center;
  gap: 14px;
  padding: 18px 16px;
  border-radius: 18px;
  background: rgba(255, 255, 255, 0.04);
  border: 1px solid rgba(255, 255, 255, 0.08);
  overflow: hidden;
}

.coin-pack-hero-glow {
  position: absolute;
  top: -20px;
  left: -10px;
  width: 120px;
  height: 120px;
  background: radial-gradient(circle, rgba(255, 200, 50, 0.15), transparent 65%);
  pointer-events: none;
}

.coin-pack-hero-coin {
  flex-shrink: 0;
  width: 52px;
  height: 52px;
  filter: drop-shadow(0 3px 10px rgba(255, 200, 50, 0.4));
  position: relative;
  z-index: 1;
}

.coin-pack-hero-text {
  position: relative;
  z-index: 1;
  min-width: 0;
}

.coin-pack-title {
  font-size: 20px;
  font-weight: 800;
  color: rgba(255, 255, 255, 0.92);
  letter-spacing: -0.02em;
}

.coin-pack-balance {
  margin-top: 3px;
  font-size: 13px;
  font-weight: 600;
  color: rgba(255, 215, 0, 0.7);
}

.coin-pack-payment-banner {
  padding: 12px 14px;
  border-radius: 14px;
  border: 1px solid rgba(86, 220, 137, 0.45);
  background: linear-gradient(135deg, rgba(29, 122, 70, 0.4), rgba(18, 94, 104, 0.38));
  box-shadow: 0 10px 24px rgba(0, 0, 0, 0.24);
}

.coin-pack-payment-banner.is-pending {
  border-color: rgba(230, 187, 80, 0.45);
  background: linear-gradient(135deg, rgba(128, 90, 20, 0.38), rgba(120, 70, 20, 0.34));
}

.coin-pack-payment-banner-title {
  font-size: 13px;
  font-weight: 800;
  color: #f4fff9;
  letter-spacing: 0.01em;
}

.coin-pack-payment-banner-text {
  margin-top: 4px;
  font-size: 12px;
  line-height: 1.45;
  color: rgba(244, 255, 249, 0.86);
}

/* --- Pack Cards Grid --- */
.coin-pack-list {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 10px;
}

/* --- Pack Card --- */
.coin-pack-card {
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: center;
  height: 100%;
  gap: 4px;
  padding: 20px 10px 14px;
  border-radius: 16px;
  background: rgba(255, 255, 255, 0.04);
  border: 1px solid rgba(255, 255, 255, 0.08);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  overflow: hidden;
  transition: transform 0.15s;
}

.coin-pack-card:active {
  transform: scale(0.98);
}

/* Featured card */
.coin-pack-card--featured {
  border-color: rgba(255, 215, 0, 0.22);
  background:
    radial-gradient(ellipse 120% 80% at 50% 0%, rgba(255, 215, 0, 0.08), transparent 55%),
    rgba(18, 14, 8, 0.92);
  box-shadow:
    0 0 30px rgba(255, 215, 0, 0.05),
    inset 0 1px 0 rgba(255, 245, 180, 0.06);
}

.coin-pack-popular {
  position: absolute;
  top: 8px;
  right: 8px;
  padding: 2px 8px;
  border-radius: 6px;
  font-size: 8px;
  font-weight: 800;
  letter-spacing: 0.8px;
  text-transform: uppercase;
  color: #1a1400;
  background: linear-gradient(135deg, #FFD700, #F5C842);
  box-shadow: 0 2px 6px rgba(255, 215, 0, 0.3);
}

.coin-pack-amount {
  font-size: 28px;
  font-weight: 900;
  color: #fff;
  line-height: 1;
  letter-spacing: -0.02em;
}

.coin-pack-label {
  font-size: 11px;
  font-weight: 600;
  color: rgba(255, 255, 255, 0.35);
  text-transform: uppercase;
  letter-spacing: 0.8px;
}

.coin-pack-bonus {
  margin-top: 4px;
  padding: 3px 10px;
  border-radius: 8px;
  font-size: 10px;
  font-weight: 700;
  color: rgba(120, 255, 180, 0.9);
  background: rgba(80, 200, 140, 0.10);
  border: 1px solid rgba(120, 255, 180, 0.15);
}

/* --- Pack Pricing Block --- */
.coin-pack-cost-label {
  display: flex;
  align-items: center;
  gap: 5px;
  margin-top: 6px;
  font-size: 11px;
  font-weight: 500;
  color: rgba(255, 255, 255, 0.4);
}

.coin-pack-discount-badge {
  display: inline-flex;
  padding: 1px 5px;
  border-radius: 5px;
  background: rgba(255, 255, 255, 0.12);
  color: rgba(255, 255, 255, 0.8);
  font-size: 10px;
  font-weight: 800;
}

.coin-pack-card--featured .coin-pack-discount-badge {
  background: rgba(255, 215, 0, 0.2);
  color: #FFD700;
}

.coin-pack-price-row {
  display: flex;
  align-items: baseline;
  gap: 6px;
  margin-top: 2px;
}

.coin-pack-price-new {
  font-size: 18px;
  font-weight: 800;
  color: #fff;
  line-height: 1;
}

.coin-pack-price-old {
  font-size: 13px;
  font-weight: 600;
  color: rgba(255, 255, 255, 0.3);
  text-decoration: line-through;
  line-height: 1;
}

.coin-pack-buy-btn {
  width: 100%;
  margin-top: auto;
  border: 0;
  border-radius: 12px;
  padding: 10px 12px;
  background: rgba(255, 255, 255, 0.07);
  border: 1px solid rgba(255, 255, 255, 0.10);
  color: rgba(255, 255, 255, 0.85);
  font-size: 14px;
  font-weight: 800;
  cursor: pointer;
  transition: transform 0.12s, box-shadow 0.12s;
}

.coin-pack-buy-btn:active {
  transform: scale(0.97);
}

.coin-pack-buy-btn:disabled {
  opacity: 0.6;
  cursor: default;
}

/* Featured card gets gold button */
.coin-pack-card--featured .coin-pack-buy-btn {
  color: #1a1400;
  background: linear-gradient(135deg, #FFD700, #F5C842, #DAA520);
  border: none;
  box-shadow: 0 3px 12px rgba(255, 215, 0, 0.25);
}

/* --- Footnote --- */
.coin-pack-footnote {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  font-size: 11px;
  color: rgba(200, 180, 255, 0.35);
}

.coin-pack-footnote svg {
  width: 14px;
  height: 14px;
  opacity: 0.5;
}

/* --- How to Earn M-Coin Section --- */
.coin-earn-section {
  margin-top: 12px;
  padding: 16px;
  border-radius: 16px;
  background: rgba(255, 255, 255, 0.03);
  border: 1px solid rgba(255, 255, 255, 0.06);
}

.coin-earn-title {
  font-size: 16px;
  font-weight: 800;
  color: rgba(255, 255, 255, 0.88);
  margin-bottom: 14px;
  letter-spacing: 0.01em;
}

.coin-earn-list {
  display: flex;
  flex-direction: column;
  gap: 0;
}

.coin-earn-item {
  display: flex;
  align-items: flex-start;
  gap: 12px;
  padding: 14px 0;
  border-bottom: 1px solid rgba(255, 255, 255, 0.05);
}

.coin-earn-item:last-child {
  border-bottom: none;
  padding-bottom: 0;
}

.coin-earn-item:first-child {
  padding-top: 0;
}

.coin-earn-icon {
  flex-shrink: 0;
  width: 32px;
  height: 32px;
  display: grid;
  place-items: center;
  font-size: 18px;
  border-radius: 10px;
  background: rgba(124, 92, 255, 0.06);
  border: 1px solid rgba(124, 92, 255, 0.1);
}

.coin-earn-name {
  font-size: 14px;
  font-weight: 700;
  color: rgba(255, 255, 255, 0.9);
  margin-bottom: 3px;
}

.coin-earn-desc {
  font-size: 12px;
  line-height: 1.45;
  color: rgba(255, 255, 255, 0.42);
}

.payment-legal-footer--packs {
  margin-top: 14px;
  margin-bottom: 4px;
}

/* =====================================================================
   RP MARKET — ACTIVITY (from handoff "RP MARKET активность.zip")
   Verbatim port of the M-COIN page CSS, with the design's #D400FF
   accent swapped for the project's --accent (#7a3cff). Class names
   match the design's (cn-*) so the legacy mcoin-* rules in shop.css
   don't interfere.
   ===================================================================== */
.cn-page {
  display: grid;
  gap: 12px;
  padding: 0 12px;
  width: 100%;
  max-width: 100%;
  min-width: 0;
  box-sizing: border-box;
}

.page.page-coins,
.page.page-coins .cn-page,
.page.page-coins .cn-page > *,
.page.page-coins .cn-grid,
.page.page-coins .cn-grid > *,
.page.page-coins .cn-balance,
.page.page-coins .cn-balance > *,
.page.page-coins .cn-vip-hero,
.page.page-coins .cn-row,
.page.page-coins .cn-history {
  min-width: 0;
  max-width: 100%;
  box-sizing: border-box;
}

.page.page-coins {
  overflow-x: clip;
}

/* ── Баланс: две валюты симметрично ── */
.cn-balance {
  position: relative;
  margin: 0;
  padding: 22px 20px 20px;
  width: 100%;
  max-width: 100%;
  min-width: 0;
  box-sizing: border-box;
  border-radius: 28px;
  background: rgba(18, 18, 28, 0.92);
  border: 1px solid rgba(255, 255, 255, 0.06);
  overflow: hidden;
}

.cn-balance::before {
  content: "";
  position: absolute;
  inset: 0;
  pointer-events: none;
  background: radial-gradient(120% 80% at 50% 0%, rgba(124, 92, 255, 0.10), transparent 60%);
}

.cn-balance .row {
  display: flex;
  align-items: stretch;
  gap: 14px;
  position: relative;
  z-index: 1;
  width: 100%;
  min-width: 0;
}

.cn-balance .cn-cur {
  flex: 1;
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.cn-balance .cn-cur.left  { align-items: flex-start; text-align: left; }
.cn-balance .cn-cur.right { align-items: flex-end;   text-align: right; }

.cn-balance .k {
  font-size: 10px;
  letter-spacing: 0.16em;
  font-weight: 700;
  color: rgba(242, 242, 247, 0.55);
  text-transform: uppercase;
  line-height: 1;
}

.cn-balance .v {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  min-width: 0;
  max-width: 100%;
  font-size: 26px;
  font-weight: 800;
  letter-spacing: -0.02em;
  color: #fff;
  line-height: 1;
  font-feature-settings: "tnum";
}

.cn-balance .cn-cur.right .v {
  justify-content: flex-end;
}

.cn-balance .v span:last-child {
  min-width: 0;
}

.cn-balance .sub {
  font-size: 10.5px;
  color: rgba(242, 242, 247, 0.40);
  line-height: 1;
}

.cn-balance .coin-dot {
  width: 18px;
  height: 18px;
  border-radius: 50%;
  background: radial-gradient(circle at 30% 25%, #FFE48F, #E0A82C 60%, #8E6011);
  box-shadow:
    inset 0 0 0 1px rgba(255, 255, 255, 0.22),
    0 0 10px rgba(224, 168, 44, 0.35);
  flex: 0 0 auto;
}

.cn-balance .coin-dot.dot-m {
  background: radial-gradient(circle at 30% 25%, #FFCFE0, #E8486C 55%, #7A1530);
  box-shadow:
    inset 0 0 0 1px rgba(255, 255, 255, 0.22),
    0 0 10px rgba(232, 72, 108, 0.35);
}

.cn-balance .divider {
  width: 1px;
  align-self: stretch;
  background: linear-gradient(
    180deg,
    transparent,
    rgba(255, 255, 255, 0.10) 25%,
    rgba(255, 255, 255, 0.10) 75%,
    transparent
  );
}

.cn-balance .actions {
  margin-top: 16px;
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 8px;
  position: relative;
  z-index: 1;
  width: 100%;
  min-width: 0;
}

.cn-balance .actions > * {
  min-width: 0;
  max-width: 100%;
}

.cn-btn {
  flex: 1;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  min-height: 40px;
  min-width: 0;
  width: 100%;
  max-width: 100%;
  padding: 0 18px;
  border-radius: 12px;
  font-size: 13px;
  font-weight: 700;
  letter-spacing: 0.01em;
  cursor: pointer;
  -webkit-appearance: none;
  appearance: none;
  outline: none;
  transition: background 160ms ease, border-color 200ms ease, transform 140ms ease;
  box-sizing: border-box;
  overflow: hidden;
  text-overflow: ellipsis;
}

.cn-btn:active {
  transform: scale(0.97);
}

.cn-btn--primary {
  background: var(--accent, #7a3cff);
  color: #fff;
  border: 1px solid transparent;
  box-shadow:
    0 8px 22px rgba(124, 92, 255, 0.32),
    inset 0 1px 0 rgba(255, 255, 255, 0.18);
}

.cn-btn--primary:hover {
  background: var(--accent-2, #a067ff);
}

.cn-btn--ghost {
  background: rgba(255, 255, 255, 0.04);
  border: 1px solid rgba(255, 255, 255, 0.10);
  color: rgba(242, 242, 247, 0.82);
}

.cn-btn--ghost:hover {
  background: rgba(255, 255, 255, 0.07);
  border-color: rgba(255, 255, 255, 0.16);
  color: #fff;
}

/* ── Fuse VIP plate visually to the balance card when they sit
       together — bottom of balance shares its edge with top of VIP,
       so the two read as one "account" surface. Pure CSS via :has(),
       hero markup stays untouched. ── */
.cn-balance:has(+ .cn-vip-hero) {
  border-bottom: 0;
  border-bottom-left-radius: 0;
  border-bottom-right-radius: 0;
}

.cn-balance + .cn-vip-hero {
  margin-top: -12px; /* negate the .cn-page grid gap above */
  border-top: 1px solid rgba(255, 255, 255, 0.04);
  border-top-left-radius: 0;
  border-top-right-radius: 0;
  /* Soft transition from the balance card's dark top into purple at
     the bottom-right — no harsh edge against the balance row above. */
  background:
    radial-gradient(70% 140% at 100% 110%, rgba(124, 92, 255, 0.30), transparent 60%),
    linear-gradient(180deg, rgba(18, 18, 28, 0.92) 0%, rgba(28, 22, 52, 0.92) 60%, rgba(36, 26, 70, 0.92) 100%);
}

/* Tame the corner-glow pseudo so it doesn't punch through the soft
   top edge — keep the glow but shift it to the lower-right. */
.cn-balance + .cn-vip-hero::after {
  right: -16px;
  top: auto;
  bottom: -28px;
  opacity: 0.45;
}

/* ── VIP — компактная фиолетовая плашка ── */
.cn-vip-hero {
  position: relative;
  display: flex;
  align-items: center;
  gap: 12px;
  width: 100%;
  max-width: 100%;
  min-width: 0;
  box-sizing: border-box;
  padding: 12px 14px;
  border-radius: 14px;
  overflow: hidden;
  background:
    radial-gradient(80% 140% at 100% 50%, rgba(124, 92, 255, 0.22), transparent 55%),
    linear-gradient(135deg, rgba(124, 92, 255, 0.08), rgba(20, 12, 30, 0.35));
  border: 1px solid rgba(124, 92, 255, 0.30);
  text-align: left;
  color: #fff;
  cursor: pointer;
  -webkit-appearance: none;
  appearance: none;
  outline: none;
}

.cn-vip-hero::after {
  content: "";
  position: absolute;
  right: -16px;
  top: -20px;
  width: 96px;
  height: 96px;
  border-radius: 50%;
  background: radial-gradient(circle, rgba(124, 92, 255, 0.55), transparent 70%);
  filter: blur(20px);
  opacity: 0.6;
  pointer-events: none;
}

.cn-vip-hero .crown {
  width: 30px;
  height: 30px;
  border-radius: 9px;
  flex: 0 0 auto;
  background: linear-gradient(135deg, var(--accent, #7a3cff), #5a23c8);
  display: grid;
  place-items: center;
  color: #fff;
  font-size: 14px;
  line-height: 1;
  box-shadow:
    0 4px 12px rgba(124, 92, 255, 0.35),
    inset 0 1px 0 rgba(255, 255, 255, 0.30);
  position: relative;
  z-index: 1;
}

.cn-vip-hero .body {
  flex: 1;
  min-width: 0;
  position: relative;
  z-index: 1;
  display: flex;
  flex-direction: column;
  gap: 1px;
}

.cn-vip-hero .t {
  font-size: 13px;
  font-weight: 800;
  letter-spacing: -0.005em;
  color: #fff;
  line-height: 1.2;
}

.cn-vip-hero .s {
  font-size: 10.5px;
  color: rgba(232, 196, 255, 0.72);
  line-height: 1.3;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

/* CTA pill — also has classes `mcoin-card-badge mcoin-card-badge--vip`
   that JS rewrites with `vip-badge--active` / `vip-badge--expired`.
   Style the chip so it stays readable through all of those states. */
.cn-vip-hero .cta {
  position: relative;
  z-index: 1;
  height: 28px;
  padding: 0 12px;
  border-radius: 8px;
  background: linear-gradient(135deg, var(--accent, #7a3cff), #5a23c8);
  color: #fff;
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.02em;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  white-space: nowrap;
  box-shadow:
    0 4px 12px rgba(124, 92, 255, 0.40),
    inset 0 1px 0 rgba(255, 255, 255, 0.25);
}

.cn-vip-hero .cta.vip-badge--active {
  background: rgba(74, 222, 128, 0.18);
  color: #6ee895;
  border: 1px solid rgba(74, 222, 128, 0.32);
  box-shadow: none;
}

.cn-vip-hero .cta.vip-badge--expired {
  background: rgba(239, 68, 68, 0.18);
  color: #ff8a8a;
  border: 1px solid rgba(239, 68, 68, 0.30);
  box-shadow: none;
}

.cn-vip-hero .cta:empty::before {
  content: "Открыть";
}

/* ── 2×2 grid: трата + утилиты ── */
.cn-grid {
  margin: 0;
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 10px;
  width: 100%;
  max-width: 100%;
  min-width: 0;
}

.cn-card {
  position: relative;
  padding: 16px;
  width: 100%;
  max-width: 100%;
  min-width: 0;
  box-sizing: border-box;
  border-radius: 18px;
  background: rgba(18, 18, 28, 0.92);
  border: 1px solid rgba(255, 255, 255, 0.06);
  overflow: hidden;
  display: flex;
  flex-direction: column;
  gap: 8px;
  min-height: 140px;
  text-align: left;
  cursor: pointer;
  -webkit-appearance: none;
  appearance: none;
  outline: none;
  color: #fff;
  transition: border-color 200ms ease, transform 140ms ease;
}

.cn-card > * {
  min-width: 0;
}

.cn-card:hover {
  border-color: rgba(255, 255, 255, 0.12);
}

.cn-card:active {
  transform: scale(0.98);
}

.cn-card .ic {
  width: 38px;
  height: 38px;
  border-radius: 12px;
  display: grid;
  place-items: center;
  font-size: 18px;
  line-height: 1;
  flex: 0 0 auto;
}

.cn-card .ic svg {
  width: 20px;
  height: 20px;
  display: block;
}

.cn-card .ttl {
  font-size: 14px;
  font-weight: 700;
  letter-spacing: -0.005em;
  color: #fff;
  line-height: 1.2;
  min-width: 0;
}

.cn-card .desc {
  font-size: 11px;
  color: rgba(242, 242, 247, 0.55);
  line-height: 1.4;
  flex: 1;
  min-width: 0;
}

.cn-card .arrow {
  position: absolute;
  right: 14px;
  top: 14px;
  color: rgba(242, 242, 247, 0.40);
  font-size: 14px;
  line-height: 1;
  width: 22px;
  height: 22px;
  border-radius: 7px;
  background: rgba(255, 255, 255, 0.04);
  display: grid;
  place-items: center;
}

.cn-card-badge {
  position: absolute;
  top: 14px;
  right: 44px;
  padding: 3px 8px;
  border-radius: 7px;
  background: rgba(124, 92, 255, 0.16);
  border: 1px solid rgba(124, 92, 255, 0.28);
  color: #d4cbff;
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.02em;
  line-height: 1.2;
  font-feature-settings: "tnum";
}

.cn-card-badge:empty {
  display: none;
}

/* Per-card icon tints (from design palette) */
.cn-card--shop .ic {
  background: rgba(91, 174, 255, 0.12);
  color: #5BAEFF;
  border: 1px solid rgba(91, 174, 255, 0.25);
}

.cn-card--cases {
  background:
    radial-gradient(120% 80% at 100% 0%, rgba(124, 92, 255, 0.18), transparent 60%),
    rgba(18, 18, 28, 0.92);
  border-color: rgba(124, 92, 255, 0.30);
}

.cn-card--cases .ic {
  background: rgba(124, 92, 255, 0.14);
  color: var(--accent, #7a3cff);
  border: 1px solid rgba(124, 92, 255, 0.30);
}

.cn-card--tasks .ic {
  background: rgba(74, 222, 128, 0.12);
  color: #4ade80;
  border: 1px solid rgba(74, 222, 128, 0.25);
}

.cn-card--inventory .ic {
  background: rgba(96, 210, 230, 0.12);
  color: #5BD9E8;
  border: 1px solid rgba(96, 210, 230, 0.25);
}

/* ── Slim row — Избранное / Продвижение ── */
.cn-row {
  display: flex;
  align-items: center;
  gap: 12px;
  width: 100%;
  padding: 14px 16px;
  border-radius: 16px;
  background: rgba(18, 18, 28, 0.92);
  border: 1px solid rgba(255, 255, 255, 0.06);
  text-align: left;
  color: #fff;
  cursor: pointer;
  -webkit-appearance: none;
  appearance: none;
  outline: none;
  transition: border-color 200ms ease, transform 140ms ease;
  box-sizing: border-box;
}

.cn-row:hover {
  border-color: rgba(255, 255, 255, 0.12);
}

.cn-row:active {
  transform: scale(0.99);
}

.cn-row .ic {
  width: 38px;
  height: 38px;
  border-radius: 12px;
  display: grid;
  place-items: center;
  flex: 0 0 auto;
}

.cn-row .ic svg {
  width: 18px;
  height: 18px;
}

.cn-row-ic--fav {
  background: rgba(255, 100, 122, 0.10);
  color: #FF8FA0;
  border: 1px solid rgba(255, 100, 122, 0.22);
}

.cn-row-ic--promo {
  background: rgba(255, 195, 107, 0.12);
  color: #ffd07a;
  border: 1px solid rgba(255, 195, 107, 0.26);
}

.cn-row-ic--vip {
  background: rgba(139, 108, 255, 0.14);
  color: #b9a4ff;
  border: 1px solid rgba(139, 108, 255, 0.30);
}

.cn-row .body {
  flex: 1;
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.cn-row .t {
  font-size: 13px;
  font-weight: 700;
  letter-spacing: -0.005em;
  color: #fff;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  line-height: 1.2;
}

.cn-row .s {
  font-size: 11px;
  color: rgba(242, 242, 247, 0.55);
  line-height: 1.3;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.cn-row .count-pill {
  font-size: 11px;
  font-weight: 700;
  color: rgba(242, 242, 247, 0.82);
  padding: 4px 9px;
  border-radius: 8px;
  background: rgba(255, 255, 255, 0.04);
  border: 1px solid rgba(255, 255, 255, 0.10);
  font-feature-settings: "tnum";
  flex: 0 0 auto;
}

.cn-row .arrow {
  width: 24px;
  height: 24px;
  border-radius: 7px;
  background: rgba(255, 255, 255, 0.04);
  display: grid;
  place-items: center;
  color: rgba(242, 242, 247, 0.40);
  font-size: 13px;
  line-height: 1;
  flex: 0 0 auto;
}

/* ── История — transactions list ── */
.cn-history {
  margin: 0;
  padding: 16px 18px;
  border-radius: 24px;
  background: rgba(18, 18, 28, 0.92);
  border: 1px solid rgba(255, 255, 255, 0.06);
}

.cn-history .h {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 10px;
}

.cn-history .h .t {
  font-size: 11px;
  letter-spacing: 0.18em;
  font-weight: 800;
  color: rgba(242, 242, 247, 0.55);
  text-transform: uppercase;
  line-height: 1;
}

.cn-history-link {
  font-size: 11px;
  font-weight: 600;
  color: rgba(242, 242, 247, 0.55);
  background: transparent;
  border: 0;
  padding: 0;
  cursor: pointer;
  -webkit-appearance: none;
  appearance: none;
  outline: none;
}

.cn-history-link:hover {
  color: #fff;
}

.cn-history-list {
  display: grid;
}

.cn-history-empty {
  padding: 12px 0;
  text-align: center;
  font-size: 12px;
  font-weight: 600;
  color: rgba(242, 242, 247, 0.40);
}

.tx {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 10px 0;
  border-top: 1px solid rgba(255, 255, 255, 0.06);
}

.tx:first-of-type {
  border: 0;
  padding-top: 0;
}

.tx .ic {
  width: 34px;
  height: 34px;
  border-radius: 10px;
  display: grid;
  place-items: center;
  font-size: 14px;
  font-weight: 800;
  line-height: 1;
  flex: 0 0 auto;
}

.tx .ic.in {
  background: rgba(74, 222, 128, 0.10);
  color: #4ade80;
  border: 1px solid rgba(74, 222, 128, 0.20);
}

.tx .ic.out {
  background: rgba(255, 100, 122, 0.10);
  color: #FF8FA0;
  border: 1px solid rgba(255, 100, 122, 0.20);
}

.tx .info {
  flex: 1;
  min-width: 0;
}

.tx .info .t {
  font-size: 13px;
  font-weight: 600;
  color: #fff;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.tx .info .s {
  font-size: 11px;
  color: rgba(242, 242, 247, 0.55);
  margin-top: 1px;
}

.tx .v {
  font-size: 13px;
  font-weight: 800;
  font-feature-settings: "tnum";
  flex: 0 0 auto;
  white-space: nowrap;
}

.tx .v.in  { color: #4ade80; }
.tx .v.out { color: rgba(242, 242, 247, 0.82); }

/* ── Small phones ── */
@media (max-width: 360px) {
  .cn-balance        { padding: 18px 16px 16px; }
  .cn-balance .v     { font-size: 22px; }
  .cn-btn            { min-height: 38px; font-size: 12px; padding: 0 14px; }
  .cn-vip-hero       { padding: 11px 12px; gap: 10px; }
  .cn-vip-hero .crown{ width: 28px; height: 28px; font-size: 13px; }
  .cn-vip-hero .t    { font-size: 12px; }
  .cn-vip-hero .s    { font-size: 10.5px; }
  .cn-card           { padding: 14px; min-height: 130px; }
  .cn-card .ttl      { font-size: 13px; }
  .cn-card-badge     { right: 40px; }
  .cn-row            { padding: 12px 14px; gap: 10px; }
  .cn-row .ic        { width: 34px; height: 34px; }
  .cn-history        { padding: 14px 16px; }
}

@media (max-width: 430px) {
  .page.page-coins.active {
    gap: 18px;
  }

  .cn-page {
    padding: 0 10px;
  }

  .cn-balance {
    padding: 18px 14px 16px;
    border-radius: 24px;
  }

  .cn-balance .row {
    gap: 8px;
  }

  .cn-balance .v {
    font-size: clamp(20px, 7.4vw, 24px);
  }

  .cn-balance .k {
    font-size: 9px;
    letter-spacing: 0.14em;
  }

  .cn-balance .sub {
    font-size: 10px;
  }

  .cn-balance .actions {
    gap: 8px;
  }

  .cn-grid {
    gap: 8px;
  }

  .cn-card {
    padding: 14px 13px;
    min-height: 128px;
    border-radius: 17px;
  }

  .cn-card .ttl {
    font-size: 12px;
  }

  .cn-card .desc {
    font-size: 10.5px;
  }

  .cn-card .arrow {
    right: 12px;
    top: 12px;
  }

  .cn-card-badge {
    right: 38px;
    top: 12px;
  }
}

@media (max-width: 390px) {
  .cn-page {
    padding: 0 8px;
  }

  .cn-balance {
    padding: 16px 12px 14px;
  }

  .cn-balance .v {
    font-size: clamp(18px, 7vw, 22px);
    gap: 6px;
  }

  .cn-balance .coin-dot {
    width: 16px;
    height: 16px;
  }

  .cn-balance .actions {
    grid-template-columns: minmax(0, 1fr);
  }

  .cn-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 8px;
  }

  .cn-card {
    padding: 13px 12px;
    min-height: 124px;
  }

  .cn-card .ic {
    width: 34px;
    height: 34px;
  }

  .cn-card .ttl {
    font-size: 11px;
  }

  .cn-card .desc {
    font-size: 10px;
    line-height: 1.35;
  }

  .cn-row {
    padding: 13px 14px;
  }
}

@media (max-width: 375px) {
  .page.page-coins.active {
    gap: 16px;
  }

  .cn-balance .row {
    gap: 6px;
  }

  .cn-balance .divider {
    opacity: 0.65;
  }

  .cn-card {
    min-height: 120px;
  }
}

/* =====================================================================
   Coins / «Активность» polish — unified surfaces, per-tile tint, no chevrons.
   Structure is unchanged; this block only refines the cn-* components.
   ===================================================================== */
.page.page-coins .cn-page {
  gap: 12px;
  /* Last rows must clear the floating bottom navigation. */
  padding-bottom: 8px;
}

/* One surface language for every card on the page. */
.page.page-coins .cn-balance,
.page.page-coins .cn-card,
.page.page-coins .cn-row,
.page.page-coins .cn-history {
  background:
    linear-gradient(160deg, rgba(255, 255, 255, 0.045), rgba(255, 255, 255, 0) 42%),
    rgba(18, 18, 28, 0.92);
  border: 1px solid rgba(255, 255, 255, 0.075);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.05);
}

/* Balance */
.page.page-coins .cn-balance .k {
  font-size: 11px;
  color: rgba(242, 242, 247, 0.68);
}

.page.page-coins .cn-balance .sub {
  font-size: 11.5px;
  color: rgba(242, 242, 247, 0.62);
}

.page.page-coins .cn-balance .v {
  font-size: 28px;
}

.page.page-coins .cn-cur.is-zero .v {
  color: rgba(242, 242, 247, 0.55);
}

.page.page-coins .cn-cur.is-zero .coin-dot {
  filter: saturate(0.45);
  opacity: 0.7;
  box-shadow: inset 0 0 0 1px rgba(255, 255, 255, 0.16);
}

/* VIP strip: a touch more presence, same footprint */
.page.page-coins .cn-vip-hero .crown {
  width: 34px;
  height: 34px;
  border-radius: 11px;
  font-size: 16px;
}

.page.page-coins .cn-vip-hero .t {
  font-size: 14px;
}

.page.page-coins .cn-vip-hero .s {
  font-size: 11.5px;
  color: rgba(226, 208, 255, 0.82);
}

/* 2×2 tiles: icon on top, text anchored to the bottom, no dead space. */
.page.page-coins .cn-card {
  --tint: 124, 92, 255;
  min-height: 132px;
  padding: 14px 14px 15px;
  gap: 0;
  background:
    radial-gradient(110% 80% at 100% 0%, rgba(var(--tint), 0.16), transparent 62%),
    linear-gradient(160deg, rgba(255, 255, 255, 0.045), rgba(255, 255, 255, 0) 42%),
    rgba(18, 18, 28, 0.92);
}

.page.page-coins .cn-card--shop { --tint: 91, 174, 255; }
.page.page-coins .cn-card--cases { --tint: 140, 104, 255; }
.page.page-coins .cn-card--tasks { --tint: 74, 222, 128; }
.page.page-coins .cn-card--inventory { --tint: 96, 210, 230; }

.page.page-coins .cn-card--cases {
  border-color: rgba(140, 104, 255, 0.38);
}

.page.page-coins .cn-card .ic,
.page.page-coins .cn-row .ic {
  width: 40px;
  height: 40px;
  border-radius: 13px;
}

.page.page-coins .cn-card .ic {
  background: linear-gradient(145deg, rgba(var(--tint), 0.24), rgba(var(--tint), 0.08));
  border: 1px solid rgba(var(--tint), 0.34);
  color: rgb(var(--tint));
}

.page.page-coins .cn-card .ttl {
  margin-top: auto;
  padding-top: 14px;
  font-size: 15px;
}

.page.page-coins .cn-card .desc {
  flex: 0 0 auto;
  margin-top: 3px;
  font-size: 11.5px;
  color: rgba(242, 242, 247, 0.68);
}

/* Single count chip, top-right (there is no chevron any more). */
.page.page-coins .cn-card-badge {
  top: 14px;
  right: 14px;
  padding: 3px 9px;
  border-radius: 999px;
  background: rgba(var(--tint), 0.18);
  border-color: rgba(var(--tint), 0.38);
  color: #fff;
  font-size: 11px;
}

.page.page-coins .cn-card-badge[hidden] {
  display: none;
}

/* Slim rows share the tile language. */
.page.page-coins .cn-row {
  gap: 12px;
  padding: 12px 14px;
  border-radius: 18px;
}

.page.page-coins .cn-row .t {
  font-size: 14px;
}

.page.page-coins .cn-row .s {
  font-size: 11.5px;
  color: rgba(242, 242, 247, 0.68);
}

.page.page-coins .cn-row .count-pill {
  padding: 4px 10px;
  border-radius: 999px;
  color: #fff;
  background: rgba(255, 255, 255, 0.08);
  border-color: rgba(255, 255, 255, 0.16);
}

.page.page-coins .cn-row .count-pill[hidden] {
  display: none;
}

/* Simplification (all layouts): no advertising plates on the market and the Activity page.
   Elements stay in the DOM, so JS that references them keeps working. */
.market-vip-promo,
.market-top-bar,
.page.page-coins .cn-vip-hero {
  display: none !important;
}

/* The balance card was fused to the VIP plate; with the plate gone it is a full card again. */
.page.page-coins .cn-balance:has(+ .cn-vip-hero) {
  border-bottom: 1px solid rgba(255, 255, 255, 0.075);
  border-radius: 28px;
}

/* =====================================================================
   ACTIVITY — market language (2026-10): the Market screen is the reference.
   Same violet-tinted surface and thin violet border for every card, one
   violet icon style, one accent for the main action, rows grouped in one card.
   Markup unchanged; these rules sit last on purpose.
   ===================================================================== */
.page.page-coins .cn-page .cn-balance,
.page.page-coins .cn-page .cn-card,
.page.page-coins .cn-page .cn-history {
  background: linear-gradient(160deg, rgba(34, 20, 66, 0.95), rgba(22, 13, 43, 0.97));
  border: 1px solid rgba(124, 92, 255, 0.2);
  border-radius: 18px;
  box-shadow: none;
}

.page.page-coins .cn-page .cn-balance::before {
  background: radial-gradient(120% 80% at 50% 0%, rgba(124, 92, 255, 0.12), transparent 62%);
}

.page.page-coins .cn-page .cn-balance .k,
.page.page-coins .cn-page .cn-balance .sub {
  color: #a79bc9;
}

/* buttons: same as the market (violet main, glass secondary) */
.page.page-coins .cn-page .cn-btn {
  min-height: 46px;
  border-radius: 14px;
  font-size: 15px;
}

.page.page-coins .cn-page .cn-btn--primary {
  background: linear-gradient(180deg, #8b5cf6, #6d28d9);
  box-shadow: 0 8px 24px rgba(124, 58, 237, 0.33);
}

.page.page-coins .cn-page .cn-btn--ghost {
  background: rgba(30, 18, 55, 0.6);
  border: 1px solid rgba(124, 92, 255, 0.2);
  color: #e6dcff;
}

/* tiles: compact, one icon style */
.page.page-coins .cn-page .cn-card {
  min-height: 0;
  padding: 14px;
  gap: 10px;
}

.page.page-coins .cn-page .cn-card--cases {
  background: linear-gradient(160deg, rgba(34, 20, 66, 0.95), rgba(22, 13, 43, 0.97));
  border-color: rgba(124, 92, 255, 0.2);
}

.page.page-coins .cn-page .cn-card .ic,
.page.page-coins .cn-page .cn-row .ic {
  background: rgba(139, 92, 246, 0.16);
  border: 1px solid rgba(124, 92, 255, 0.2);
  color: #c4b5fd;
}

.page.page-coins .cn-page .cn-card .ttl {
  font-size: 16px;
}

.page.page-coins .cn-page .cn-card .desc,
.page.page-coins .cn-page .cn-row .s {
  font-size: 12px;
  color: #a79bc9;
}

.page.page-coins .cn-page .cn-card-badge,
.page.page-coins .cn-page .cn-row .count-pill {
  padding: 3px 10px;
  border-radius: 999px;
  background: rgba(139, 92, 246, 0.2);
  border: 1px solid rgba(124, 92, 255, 0.28);
  color: #c4b5fd;
  font-size: 12px;
  font-weight: 700;
}

.page.page-coins .cn-page .cn-card-badge {
  top: 12px;
  right: 12px;
}

/* Избранное / Продвижение / VIP: one grouped card with hairline dividers */
.page.page-coins .cn-page .cn-row {
  border-radius: 0;
  border: 1px solid rgba(124, 92, 255, 0.2);
  background: rgba(28, 17, 54, 0.96);
  box-shadow: none;
}

.page.page-coins .cn-page .cn-row .t {
  font-size: 15px;
}

.page.page-coins .cn-page .cn-grid + .cn-row {
  border-radius: 18px 18px 0 0;
}

.page.page-coins .cn-page .cn-row + .cn-row {
  margin-top: -12px;
  border-top: 0;
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.06);
}

.page.page-coins .cn-page .cn-row:has(+ .cn-history) {
  border-radius: 0 0 18px 18px;
}

.page.page-coins .cn-page .cn-balance .actions {
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 10px;
}

/* =====================================================================
   M-Coin packs: no pop-in. Skeletons hold the space while packs load, cards fade in.
   Legal links moved from the payment pages to menu -> Правила -> Документы.
   ===================================================================== */
.coin-pack-card--skeleton {
  min-height: 168px;
  border-radius: 16px;
  background:
    linear-gradient(100deg, rgba(95, 65, 170, 0.12) 30%, rgba(180, 152, 255, 0.24) 50%, rgba(95, 65, 170, 0.12) 70%);
  background-size: 220% 100%;
  border: 1px solid rgba(124, 92, 255, 0.16);
  animation: marketThumbPulse 1.4s linear infinite;
}

.coin-pack-card--in {
  animation: coinPackIn 0.28s ease-out both;
  animation-delay: calc(var(--pack-i, 0) * 45ms);
}

@keyframes coinPackIn {
  from { opacity: 0; transform: translateY(8px); }
  to { opacity: 1; transform: translateY(0); }
}

@media (prefers-reduced-motion: reduce) {
  .coin-pack-card--skeleton,
  .coin-pack-card--in {
    animation: none;
  }
}

/* =====================================================================
   CREATE LISTING — market language (2026-10)
   Live preview card on top, labelled fields, server + price in one row,
   big photo drop zone, 30-day note under the button. Mini-app only: the
   desktop website keeps its own form layout (desktop-shell.css).
   ===================================================================== */
.create-label,
.create-preview,
.create-note {
  display: none;
}

body:not(.web-desktop) .page-create .create-card {
  background: none;
  border: 0;
  box-shadow: none;
  padding: 0;
}

body:not(.web-desktop) .page-create .create-header {
  margin: 4px 2px 12px;
}

body:not(.web-desktop) .page-create .create-header .section-title {
  font-size: 26px;
  font-weight: 700;
  letter-spacing: -0.4px;
}

body:not(.web-desktop) .page-create .rules-btn {
  width: 40px;
  height: 40px;
  border-radius: 13px;
  background: rgba(30, 18, 55, 0.6);
  border: 1px solid rgba(124, 92, 255, 0.2);
  color: #c4b5fd;
}

body:not(.web-desktop) .page-create .create-form {
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 10px;
}

body:not(.web-desktop) .page-create .create-form > * {
  grid-column: 1 / -1;
  min-width: 0;
}

/* order: type, category, name, server+price, photos, description, preview, publish */
body:not(.web-desktop) .page-create .create-type-switch { order: 1; }
body:not(.web-desktop) .page-create .create-label--category { order: 2; }
body:not(.web-desktop) .page-create #createCategoryPills { order: 3; }
body:not(.web-desktop) .page-create .create-label--title { order: 4; }
body:not(.web-desktop) .page-create .create-form > input[name="title"] { order: 5; }
body:not(.web-desktop) .page-create .create-label--serverprice { order: 6; }
body:not(.web-desktop) .page-create .server-picker { order: 7; grid-column: 1 / 2; }
body:not(.web-desktop) .page-create #priceInput { order: 8; grid-column: 2 / 3; }
body:not(.web-desktop) .page-create .create-label--photo { order: 9; }
body:not(.web-desktop) .page-create .photo-block { order: 10; }
body:not(.web-desktop) .page-create .create-label--desc { order: 11; }
body:not(.web-desktop) .page-create .create-form > textarea { order: 12; }
body:not(.web-desktop) .page-create .create-watch { order: 12; }
body:not(.web-desktop) .page-create .create-label--preview { order: 13; }
body:not(.web-desktop) .page-create .create-preview { order: 14; display: grid; }
body:not(.web-desktop) .page-create #createSubmit { order: 15; }
body:not(.web-desktop) .page-create .create-note { order: 16; display: block; }

body:not(.web-desktop) .page-create .create-label {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  margin: 10px 2px -2px;
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: #a79bc9;
}

body:not(.web-desktop) .page-create .create-label small {
  font-size: 12px;
  font-weight: 500;
  letter-spacing: 0;
  text-transform: none;
}

/* preview */
body:not(.web-desktop) .page-create .create-preview {
  grid-template-columns: 160px;
  justify-content: center;
  gap: 14px;
  align-items: center;
  padding: 14px;
  border-radius: 18px;
  background: linear-gradient(160deg, rgba(34, 20, 66, 0.95), rgba(22, 13, 43, 0.97));
  border: 1px solid rgba(124, 92, 255, 0.2);
}

body:not(.web-desktop) .page-create .create-preview-card {
  pointer-events: none;
  animation: none;
}

body:not(.web-desktop) .page-create .create-preview-card .market-card-thumb {
  aspect-ratio: 1 / 0.8;
}

body:not(.web-desktop) .page-create .create-preview .is-placeholder {
  opacity: 0.55;
}

body:not(.web-desktop) .page-create .create-preview-tips b {
  display: block;
  margin-bottom: 8px;
  font-size: 14px;
  color: #e6dcff;
}

body:not(.web-desktop) .page-create .create-preview-tips div {
  position: relative;
  padding-left: 18px;
  margin-bottom: 6px;
  font-size: 12px;
  line-height: 1.4;
  color: #a79bc9;
}

body:not(.web-desktop) .page-create .create-preview-tips div::before {
  content: "✓";
  position: absolute;
  left: 0;
  font-weight: 800;
  color: #8b5cf6;
}

/* type: capsule, sell green / buy blue (same colours as the market badges) */
body:not(.web-desktop) .page-create .create-type-switch {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 6px;
  margin: 0;
  padding: 4px;
  border-radius: 16px;
  border: 1px solid rgba(124, 92, 255, 0.24);
  background: rgba(17, 13, 33, 0.74);
}

body:not(.web-desktop) .page-create .create-type-chip {
  min-height: 44px;
  border-radius: 12px;
  border: 0;
  background: transparent;
  box-shadow: none;
  font-size: 15px;
  font-weight: 700;
  color: #a79bc9;
}

body:not(.web-desktop) .page-create .create-type-chip[data-create-type="sell"].active {
  color: #6ee7b7;
  background: rgba(16, 185, 129, 0.2);
  box-shadow: inset 0 0 0 1px rgba(52, 211, 153, 0.45);
}

body:not(.web-desktop) .page-create .create-type-chip[data-create-type="buy"].active {
  color: #93c5fd;
  background: rgba(59, 130, 246, 0.24);
  box-shadow: inset 0 0 0 1px rgba(96, 165, 250, 0.5);
}

/* fields */
body:not(.web-desktop) .page-create .create-form .filter-input,
body:not(.web-desktop) .page-create .create-form textarea {
  min-height: 50px;
  padding: 0 14px;
  border-radius: 14px;
  font-size: 16px;
  background: rgba(30, 18, 55, 0.6);
  border: 1px solid rgba(124, 92, 255, 0.2);
  color: #fff;
}

body:not(.web-desktop) .page-create .create-form textarea,
body:not(.web-desktop) .page-create .create-form textarea.filter-input {
  min-height: 96px;
  max-height: 260px;
  padding: 15px 14px;
  line-height: 1.4;
  resize: none;
  overflow-y: auto;
}

body:not(.web-desktop) .page-create .create-form .filter-input::placeholder,
body:not(.web-desktop) .page-create .create-form textarea::placeholder {
  color: #7d71a3;
}

body:not(.web-desktop) .page-create .create-form .filter-input:focus,
body:not(.web-desktop) .page-create .create-form textarea:focus {
  outline: none;
  border-color: #a78bfa;
  box-shadow: 0 0 0 3px rgba(139, 92, 246, 0.22);
}

body:not(.web-desktop) .page-create #priceInput {
  padding-right: 38px;
  background-image: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' width='20' height='20'><text x='4' y='15' font-size='15' font-weight='700' font-family='sans-serif' fill='%23a79bc9'>₽</text></svg>");
  background-repeat: no-repeat;
  background-position: right 12px center;
}

/* category chips */
body:not(.web-desktop) .page-create #createCategoryPills {
  flex-wrap: wrap;
  gap: 8px;
}

body:not(.web-desktop) .page-create #createCategoryPills .pill {
  padding: 7px 14px;
  border-radius: 999px;
  font-size: 13px;
  font-weight: 600;
  color: #d8ccf7;
  background: rgba(30, 18, 55, 0.6);
  border: 1px solid rgba(124, 92, 255, 0.2);
  box-shadow: none;
}

body:not(.web-desktop) .page-create #createCategoryPills .pill.active {
  color: #fff;
  background: linear-gradient(180deg, #8b5cf6, #6d28d9);
  border-color: transparent;
}

/* photos */
body:not(.web-desktop) .page-create .photo-add {
  min-height: 96px;
  border-radius: 16px;
  border: 1.5px dashed rgba(124, 92, 255, 0.5);
  background: rgba(139, 92, 246, 0.06);
  color: #c4b5fd;
  font-size: 15px;
  font-weight: 600;
  text-align: center;
}

body:not(.web-desktop) .page-create .photo-thumb {
  border-radius: 14px;
  border: 1px solid rgba(124, 92, 255, 0.28);
}

body:not(.web-desktop) .page-create .photo-thumb img {
  height: 104px;
}

body:not(.web-desktop) .page-create .photo-hint {
  font-size: 12px;
  color: #a79bc9;
}

/* publish */
body:not(.web-desktop) .page-create #createSubmit {
  min-height: 54px;
  margin-top: 12px;
  border-radius: 14px;
  font-size: 17px;
  font-weight: 700;
  background: linear-gradient(180deg, #8b5cf6, #6d28d9);
  border: 0;
  box-shadow: 0 8px 24px rgba(124, 58, 237, 0.33);
}

body:not(.web-desktop) .page-create .create-note {
  margin: -2px 4px 0;
  text-align: center;
  font-size: 12.5px;
  line-height: 1.4;
  color: #a79bc9;
}

/* the hidden preview photo must not draw a broken-image frame (class display rules beat the hidden attribute) */
.create-preview #createPreviewImg[hidden] {
  display: none;
}

/* VIP plans carousel: a clear gap between the two cards (they used to touch) and snapping that respects the side
   padding, so the next card never peeks in at the edge and the card always lands exactly where the first one sits. */
.vip-swipe-container {
  gap: 16px;
  scroll-padding-left: var(--vip-side-pad-left, 16px);
  scroll-padding-right: var(--vip-side-pad-right, 16px);
}

@media (max-width: 420px), (max-height: 760px) {
  .vip-swipe-container {
    scroll-padding-left: max(12px, var(--vip-side-pad-left, 12px));
    scroll-padding-right: max(12px, var(--vip-side-pad-right, 12px));
  }
}

/* The scrolling carousel inside made its parent column wider than the page (385px in a 358px page), which pushed the first
   card's right edge off screen and let the neighbour peek in. A grid/flex parent must be allowed to shrink. */
.page[data-page="coins-vip"] .vip-panel,
.page[data-page="coins-vip"] .vip-swipe-container {
  min-width: 0;
  max-width: 100%;
}

/* ===== Photo viewer: gestures (pinch, double-tap, pan, swipe between photos, swipe down to close) ===== */
.image-zoom {
  background: rgba(0, 0, 0, calc(0.94 * var(--iv-bg, 1)));
  -webkit-backdrop-filter: none;
  backdrop-filter: none;
  transition: background 0.18s ease;
}

.image-zoom.is-dragging-down {
  transition: none;
}

.image-zoom-card {
  padding: max(56px, env(safe-area-inset-top)) 0 max(40px, env(safe-area-inset-bottom));
  touch-action: none;
  -webkit-user-select: none;
  user-select: none;
}

.image-zoom-card img {
  max-width: 100%;
  max-height: 100%;
  border-radius: 0;
  transition: none;
  will-change: transform;
  transform-origin: center center;
  cursor: grab;
  -webkit-touch-callout: none;
}

.image-zoom-card img:active {
  cursor: grabbing;
}

/* the +/- buttons are replaced by gestures (wheel on desktop) */
.image-zoom-controls {
  display: none !important;
}

.iv-counter {
  position: fixed;
  top: max(24px, calc(env(safe-area-inset-top) + 10px));
  left: 50%;
  transform: translateX(-50%);
  padding: 5px 12px;
  border-radius: 999px;
  background: rgba(30, 18, 55, 0.7);
  color: #e6dbff;
  font-size: 13px;
  font-weight: 700;
  font-variant-numeric: tabular-nums;
  z-index: 10;
  pointer-events: none;
}

.iv-counter[hidden],
.iv-nav[hidden] {
  display: none;
}

.iv-nav {
  position: fixed;
  top: 50%;
  width: 44px;
  height: 44px;
  margin-top: -22px;
  border: 0;
  border-radius: 50%;
  background: rgba(30, 18, 55, 0.7);
  color: #fff;
  font-size: 26px;
  line-height: 1;
  z-index: 10;
  display: none;
  place-items: center;
}

.iv-nav--prev {
  left: 14px;
}

.iv-nav--next {
  right: 14px;
}

.iv-nav:disabled {
  opacity: 0.3;
}

@media (hover: hover) and (pointer: fine) {
  .iv-nav:not([hidden]) {
    display: grid;
  }
}

/* ===== Rules (listing / general / moderator): a centred modal window instead of a side drawer ===== */
.rules-overlay {
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
  background: rgba(6, 4, 12, 0.78);
  z-index: 500;
  transition: opacity 0.2s ease;
}

.rules-drawer {
  position: relative;
  top: auto;
  left: auto;
  width: min(440px, 100%);
  height: auto;
  max-height: min(84dvh, 760px);
  padding: 0 0 20px;
  gap: 14px;
  border: 1px solid rgba(124, 92, 255, 0.3);
  border-radius: 24px;
  background: linear-gradient(180deg, #20133a, #150c2b);
  box-shadow: 0 24px 60px rgba(0, 0, 0, 0.55);
  transform: translateY(14px) scale(0.97);
  opacity: 0;
  transition: transform 0.24s cubic-bezier(0.22, 0.61, 0.36, 1), opacity 0.2s ease;
  overflow-y: auto;
  overscroll-behavior: contain;
  scrollbar-width: none;
}

.rules-drawer::-webkit-scrollbar {
  display: none;
}

.rules-overlay.show .rules-drawer {
  transform: none;
  opacity: 1;
}

.rules-drawer-header {
  position: sticky;
  top: 0;
  z-index: 2;
  grid-template-columns: auto 1fr auto;
  gap: 12px;
  padding: 16px 16px 14px;
  background: #20133a;
  border-bottom: 1px solid rgba(124, 92, 255, 0.18);
}

.rules-icon {
  width: 40px;
  height: 40px;
  border-radius: 14px;
  font-size: 20px;
  background: rgba(124, 92, 255, 0.18);
  border: 1px solid rgba(167, 139, 250, 0.3);
  box-shadow: none;
}

.rules-title {
  font-size: 14px;
  font-weight: 800;
  line-height: 1.25;
  letter-spacing: 0.02em;
  color: #f4eeff;
}

.rules-close {
  width: 36px;
  height: 36px;
  border-radius: 50%;
  font-size: 14px;
  color: #e6dbff;
  background: rgba(124, 92, 255, 0.16);
  border: 1px solid rgba(124, 92, 255, 0.3);
}

.rules-drawer > .rules-section {
  margin: 0 18px;
  gap: 8px;
}

.rules-section-title {
  font-size: 16px;
  font-weight: 700;
  line-height: 1.3;
  color: #f4eeff;
}

.rules-list {
  list-style: none;
  padding: 0;
  gap: 8px;
  font-size: 14px;
  line-height: 1.5;
  color: #cdbfee;
}

.rules-list li {
  padding-left: 12px;
  border-left: 2px solid rgba(124, 92, 255, 0.35);
}

.rules-note {
  font-size: 14px;
  line-height: 1.5;
  color: #cdbfee;
}

html.android-lite .rules-drawer {
  transition: opacity 0.15s ease;
  transform: none;
}

/* history rows: long texts wrap instead of being cut off, neutral rows (activations) have no green arrow */
.tx .info .t {
