/* miniapp/styles/components/bottom-nav-liquid.css */
/* Liquid glass bottom navigation (normal + dark) */
.action-bar {
  --nav-col-size: 68px;
  --nav-gap-size: 8px;
  --nav-pad-y: 8px;
  --nav-pad-x: 10px;
  --nav-step: calc(var(--nav-col-size) + var(--nav-gap-size));
  --nav-indicator-size: 66px;
  --nav-indicator-offset-x: calc(var(--nav-pad-x) + (var(--nav-col-size) - var(--nav-indicator-size)) / 2);
  --nav-indicator-offset-y: calc(var(--nav-pad-y) + (var(--nav-col-size) - var(--nav-indicator-size)) / 2);
  width: fit-content;
  max-width: calc(100% - 22px);
  min-height: 84px;
  padding: var(--nav-pad-y) var(--nav-pad-x);
  border-radius: 32px;
  display: grid;
  grid-template-columns: repeat(var(--nav-count, 4), var(--nav-col-size));
  gap: var(--nav-gap-size);
  align-items: stretch;
  bottom: calc(30px + env(safe-area-inset-bottom));
  background:
    linear-gradient(180deg, rgba(72, 118, 238, 0.2), rgba(68, 95, 214, 0.14) 46%, rgba(34, 48, 108, 0.2) 100%),
    linear-gradient(130deg, rgba(110, 150, 255, 0.08), rgba(140, 118, 255, 0.08));
  border: 1px solid rgba(168, 205, 255, 0.3);
  box-shadow:
    0 9px 22px rgba(4, 10, 28, 0.3),
    inset 0 1px 0 rgba(186, 218, 255, 0.14),
    inset 0 -1px 0 rgba(90, 132, 230, 0.14);
  backdrop-filter: blur(10px) saturate(130%);
  -webkit-backdrop-filter: blur(10px) saturate(130%);
  transform: translate3d(calc(-50% + var(--swipe-dx, 0px)), var(--nav-shift-y, 0px), 0);
  will-change: transform, opacity;
  contain: paint;
  isolation: isolate;
  backface-visibility: hidden;
  transition:
    transform 260ms cubic-bezier(0.2, 0.8, 0.2, 1),
    opacity 220ms ease;
}

.action-bar[style*="--nav-count: 5"] {
  --nav-col-size: 58px;
  --nav-gap-size: 4px;
  --nav-pad-y: 7px;
  --nav-pad-x: 8px;
  --nav-indicator-size: 62px;
  min-height: 74px;
  border-radius: 28px;
}

.action-bar[style*="--nav-count: 5"] .nav-btn {
  width: 58px;
  height: 58px;
  border-radius: 18px;
  padding: 6px 2px 5px;
  gap: 2px;
}

.action-bar[style*="--nav-count: 5"] .nav-btn .nav-icon {
  width: 25px;
  height: 25px;
}

.action-bar[style*="--nav-count: 5"] .nav-btn[data-nav="capture"] .nav-icon {
  width: 27px;
  height: 27px;
}

.action-bar[style*="--nav-count: 5"] .nav-btn .nav-icon--profile,
.action-bar[style*="--nav-count: 5"] .nav-btn[data-nav="profile"] .nav-icon--profile {
  width: 28px;
  height: 28px;
}

.action-bar[style*="--nav-count: 5"] .nav-profile-avatar {
  width: 28px;
  height: 28px;
  font-size: 11px;
}

.action-bar[style*="--nav-count: 5"] .nav-btn .nav-label {
  font-size: 9px;
}

.action-bar::before {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: inherit;
  pointer-events: none;
  background: linear-gradient(180deg, rgba(176, 212, 255, 0.16), rgba(142, 188, 255, 0.04) 52%, rgba(142, 188, 255, 0));
  opacity: 0.44;
}

.action-bar::after {
  content: "";
  position: absolute;
  top: var(--nav-indicator-offset-y);
  left: var(--nav-indicator-offset-x);
  width: var(--nav-indicator-size);
  height: var(--nav-indicator-size);
  border-radius: 24px;
  pointer-events: none;
  z-index: 0;
  background: linear-gradient(160deg, rgba(102, 147, 232, 0.4), rgba(105, 99, 231, 0.34));
  box-shadow:
    0 5px 14px rgba(0, 0, 0, 0.2),
    inset 0 1px 0 rgba(183, 214, 255, 0.3);
  transform: translateX(calc(var(--nav-index, 0) * var(--nav-step)));
  transition: transform 320ms cubic-bezier(0.22, 0.7, 0.2, 1), box-shadow 240ms ease, background 240ms ease;
}

.nav-btn {
  width: 68px;
  height: 68px;
  position: relative;
  border-radius: 24px;
  padding: 7px 4px 6px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 3px;
  transform: translateY(0) scale(1);
  transition:
    transform 240ms cubic-bezier(0.22, 0.7, 0.2, 1),
    color 200ms ease,
    filter 220ms ease;
}

.nav-btn--isolated::after,
.nav-btn--group-start::after {
  content: "";
  position: absolute;
  top: 12px;
  bottom: 12px;
  right: calc(var(--nav-gap-size, 8px) * -0.5);
  width: 1px;
  border-radius: 999px;
  pointer-events: none;
  background: linear-gradient(180deg, rgba(255, 255, 255, 0), rgba(190, 217, 255, 0.3), rgba(255, 255, 255, 0));
  opacity: 0.9;
}

.nav-btn--center-main .nav-icon {
  transform: scale(1.05);
}

.nav-btn--center-main .nav-label {
  font-weight: 800;
  color: rgba(232, 242, 255, 0.82);
}

.nav-btn::before {
  border-radius: 19px;
  transition:
    opacity 200ms ease,
    background-color 220ms ease,
    box-shadow 260ms ease,
    transform 240ms cubic-bezier(0.22, 0.7, 0.2, 1);
}

.nav-btn .nav-icon {
  width: 24px;
  height: 24px;
  display: grid;
  place-items: center;
  transform: scale(1);
  filter: none;
  transition:
    transform 220ms cubic-bezier(0.22, 0.7, 0.2, 1),
    filter 220ms ease,
    color 220ms ease;
}

.nav-btn .nav-icon svg {
  width: 100%;
  height: 100%;
  display: block;
}

.nav-btn .nav-icon--coin {
  width: 24px;
  height: 24px;
  filter: grayscale(1) brightness(1.05);
}

.nav-btn .nav-icon--coin svg {
