}

.dk-search svg {
  width: 18px;
  height: 18px;
  flex: 0 0 auto;
}

.dk-search input {
  flex: 1;
  min-width: 0;
  border: 0;
  outline: 0;
  background: transparent;
  color: #fff;
  font: 500 14px/1 inherit;
}

.dk-search input::placeholder {
  color: rgba(214, 202, 255, 0.5);
}

.dk-top-actions {
  margin-left: auto;
  display: flex;
  align-items: center;
  gap: 10px;
}

.dk-balance {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  height: 44px;
  padding: 0 16px;
  border-radius: 15px;
  border: 1px solid var(--dk-border);
  background: var(--dk-surface);
  color: #fff;
  font: 800 13.5px/1 inherit;
  font-feature-settings: "tnum";
  cursor: pointer;
}

.dk-balance[hidden],
.dk-topup[hidden] {
