}

.dk-coin {
  width: 14px;
  height: 14px;
  border-radius: 50%;
  background: radial-gradient(circle at 30% 25%, #ffe48f, #e0a82c 60%, #8e6011);
}

.dk-topup,
.dk-create {
  display: inline-flex;
  align-items: center;
  gap: 8px;
