  background-image: none;
  border-color: rgba(124, 92, 255, 0.2);
  box-shadow: none;
}

/* ═══ Chats list page: same split as an open dialog — list left, placeholder right ═══ */
body.web-desktop .page-conversations.active {
  display: grid;
  position: fixed;
  z-index: 20;
  top: calc(var(--dk-top) + 24px);
  bottom: 24px;
  left: calc(var(--dk-side) + 32px);
  width: 340px !important;
  max-width: 340px !important;
  margin: 0 !important;
  padding: 0;
  overflow-y: auto;
  align-content: start;
  min-height: 0;
}

.dk-chat-placeholder {
  display: none;
}

body.web-desktop .dk-shell.dk-chat-empty .dk-chat-placeholder {
  display: flex;
  position: fixed;
  z-index: 10;
  top: calc(var(--dk-top) + 24px);
  bottom: 24px;
  left: calc(var(--dk-side) + 32px + 340px + 32px);
  right: 32px;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 10px;
  border-radius: 20px;
  background: #1a1033;
  border: 1px solid rgba(124, 92, 255, 0.2);
  color: rgba(235, 235, 245, 0.5);
}

.dk-chat-placeholder svg {
  width: 44px;
  height: 44px;
  opacity: 0.6;
}

.dk-chat-placeholder-title {
  font-size: 17px;
  font-weight: 700;
  color: rgba(245, 245, 250, 0.85);
}

.dk-chat-placeholder-text {
  font-size: 13px;
}

/* ═══ Кейсы — list: big neutral cards ═══ */
body.web-desktop .page .cases-home {
  display: grid;
  gap: 20px;
}

body.web-desktop .page .cases-grid {
  grid-template-columns: repeat(auto-fill, minmax(300px, 1fr));
  gap: 20px;
}

body.web-desktop .page .case-entry-card {
  padding: 16px;
  border-radius: 22px;
  background: #1a1033;
  background-image: none;
  border: 1px solid rgba(124, 92, 255, 0.2);
  box-shadow: none;
  transition: border-color 160ms ease, transform 160ms ease;
}

body.web-desktop .page .case-entry-card:hover {
  border-color: rgba(160, 103, 255, 0.55);
  transform: translateY(-2px);
}

body.web-desktop .page .case-entry-card .case-entry-art {
  min-height: 220px;
  background: #150c2b;
  border: 1px solid rgba(124, 92, 255, 0.16);
}

body.web-desktop .page .cases-chip {
  background: #1a1033;
  border: 1px solid rgba(124, 92, 255, 0.18);
  color: rgba(245, 245, 250, 0.82);
}

body.web-desktop .page .cases-chip.active {
  background: rgba(139, 92, 246, 0.28);
  border-color: rgba(160, 103, 255, 0.55);
  color: #fff;
}

/* ═══ Кейс — open: reel on the left, case card + prizes on the right (no bottom sheet) ═══ */
body.web-desktop .page.page-case-open.active:not(.page-market):not(.page-capture) {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 400px;
  gap: 24px;
  align-items: start;
  position: relative;
  min-height: 0;
}

body.web-desktop .page-case-open .case-reel-area {
  grid-column: 1;
  grid-row: 1;
  height: auto;
  min-height: 520px;
  padding: 24px;
  border-radius: 22px;
  background: #1a1033;
  border: 1px solid rgba(124, 92, 255, 0.2);
  overflow: hidden;
}

body.web-desktop .page-case-open .case-sheet {
  position: static !important;
  grid-column: 2;
  grid-row: 1;
  height: auto !important;
  max-height: none !important;
  transform: none !important;
  border-radius: 22px;
  background: #1a1033;
  background-image: none;
  border: 1px solid rgba(124, 92, 255, 0.2);
  box-shadow: none;
  overflow: visible;
}

body.web-desktop .page-case-open .case-sheet-handle {
  display: none;
}

body.web-desktop .page-case-open .case-sheet-prizes {
  max-height: none;
  overflow: visible;
}

body.web-desktop .page-case-open .case-open-prizes-grid {
  grid-template-columns: repeat(3, minmax(0, 1fr));
}

body.web-desktop .page-case-open .case-win-overlay {
  position: fixed;
  inset: 0;
  z-index: 200;
}

/* Notifications: the bell lives in the top bar; the in-card header (with the clipped bell) is hidden. */
.dk-bell {
  position: relative;
  display: grid;
  place-items: center;
  width: 38px;
  height: 38px;
  border-radius: 12px;
  border: 1px solid var(--dk-border);
  background: var(--dk-surface);
  color: rgba(245, 245, 250, 0.85);
  cursor: pointer;
}

.dk-bell[hidden],
.dk-bell-badge[hidden] {
  display: none;
}

.dk-bell:hover {
  border-color: var(--dk-border-strong);
  color: #fff;
}

.dk-bell svg {
  width: 20px;
  height: 20px;
}

.dk-bell-badge {
  position: absolute;
  top: -5px;
  right: -5px;
  min-width: 18px;
  height: 18px;
  padding: 0 5px;
  box-sizing: border-box;
  border-radius: 999px;
  background: var(--accent, #8b5cf6);
  color: #fff;
  font: 800 10.5px/18px inherit;
  text-align: center;
}

body.web-desktop .page-conversations .conversations-header {
  display: none;
}

/* toolbar: filters, type chips and the count share one centred row */
body.web-desktop .page-market > .market-type-switch {
  align-items: center;
}
